function buildSortedSurvivorFrameRing(modules: Record<string, string>, prefix: string): string[] {
  return Object.entries(modules)
    .map(([path, source]) => {
      const match = path.match(new RegExp(`${prefix}_(\\d+)\\.png$`));
      return {
        index: match ? Number.parseInt(match[1] ?? "0", 10) : 0,
        source
      };
    })
    .sort((a, b) => a.index - b.index)
    .map((entry) => entry.source);
}

const survivorIdleRifleFrames = buildSortedSurvivorFrameRing(
  survivorIdleRifleFrameModules,
  "survivor-idle_rifle"
);
const survivorMoveRifleFrames = buildSortedSurvivorFrameRing(
  survivorMoveRifleFrameModules,
  "survivor-move_rifle"
);
const survivorIdleKnifeFrames = buildSortedSurvivorFrameRing(
  survivorIdleKnifeFrameModules,
  "survivor-idle_knife"
);
const survivorMoveKnifeFrames = buildSortedSurvivorFrameRing(
  survivorMoveKnifeFrameModules,
  "survivor-move_knife"
);
const survivorMeleeAttackKnifeFrames = buildSortedSurvivorFrameRing(
  survivorMeleeAttackKnifeFrameModules,
  "survivor-meleeattack_knife"
);

function buildSpritePaintFrameImages(frameRing: string[]): HTMLImageElement[] {
  return frameRing.map((src) => {
    const image = new Image();
    image.decoding = "async";
    image.src = src;
    return image;
  });
}

const survivorIdleRifleImages = buildSpritePaintFrameImages(survivorIdleRifleFrames);
const survivorMoveRifleImages = buildSpritePaintFrameImages(survivorMoveRifleFrames);

