function buildSquadDoctrineRead(route: ActiveRoute, playerWeaponId: WeaponId, state = raidController.state): SquadDoctrineRead {
  const context = getSquadDoctrineContext(route, state);
  const mates = getSquadDoctrineMembers().map((mate) => ({
    ...mate,
    roleLabel: getSquadMateDoctrineRoleLabel(route, playerWeaponId, mate.weaponId, state),
    detail: getSquadMateDoctrineDetail(route, playerWeaponId, mate.weaponId, state)
  }));
  const squadMixSummary = getActiveSquadWeaponMixSummary(3);
  const roleSummary = mates.map((mate) => `${mate.name} ${mate.roleLabel}`).join(" | ");
  let title = "Balanced squad package";
  let summary = `${squadMixSummary} keep the route from hinging on one body or one angle.`;
  let packageLabel = `${squadMixSummary} hold the push together`;

  if (playerWeaponId === "none") {
    title = "Carry-the-operator package";
    summary = `${squadMixSummary} must buy the first clean angle, body drag, and route solve because the operator is entering on survival doctrine.`;
    packageLabel = `${squadMixSummary} buy the first clean angle`;
  } else if (playerWeaponId === "pistol") {
    title = "Emergency recovery package";
    summary = `${squadMixSummary} must carry the first lane and the first long-gun opportunity while the sidearm only survives the bad room.`;
    packageLabel = `${squadMixSummary} carry the first lane`;
  } else if (playerWeaponId === "amr") {
    title = "Anchor-break package";
    summary = `${squadMixSummary} convert one plated kill into a real crossing: crack the lane owner, shut the repeek, then flood the opened pocket before the route resets.`;
    packageLabel = `${squadMixSummary} turn one kill into a crossing`;
  } else if (playerWeaponId === "pkm") {
    title = "Belt-led crossing package";
    summary = `${squadMixSummary} live inside the suppression window: one body owns the lane while the faster guns collapse the pocket behind the belt.`;
    packageLabel = `${squadMixSummary} move under the belt`;
  } else if (playerWeaponId === "shotgun") {
    title = "Breach stack package";
    summary = `${squadMixSummary} have to buy the doorway and keep the follow-through honest, because the shotgun wins the room but not the whole approach by itself.`;
    packageLabel = `${squadMixSummary} buy the door then the follow-through`;
  } else if (playerWeaponId === "smg") {
    title = "Collapse package";
    summary = `${squadMixSummary} need one cleaner long angle and one fast flood body so the route can collapse before the open lane punishes the push.`;
    packageLabel = `${squadMixSummary} collapse before the lane resets`;
  }

  if (context.titleOverride) {
    title = context.titleOverride;
  }
  if (context.summaryOverride) {
    summary = context.summaryOverride;
  }
  if (context.packageLabelOverride) {
    packageLabel = context.packageLabelOverride;
  }

  return {
    title,
    summary,
    packageLabel,
    tags: [title, squadMixSummary, roleSummary || "No active squad doctrine", ...context.tags],
    mates
  };
}

function getWeaponDoctrineCurrentSpace(route: ActiveRoute, state: typeof raidController.state): string {
  if (state.phase !== "raid") {
    return `Planned insert: ${state.currentInsertionLabel}`;
  }

  const doorwayTelemetry = getDoorwayTelemetrySnapshot();
  if (doorwayTelemetry.playerInsideRoomStack) {
    return `Live space: room stack // ${formatRoomStackLoadout(doorwayTelemetry)}`;
  }

  if (state.extractionReady && state.carriedValue > 0) {
    return `Live space: extract peel // ${getFocusedExtractLabel() ?? route.extractLabel}`;
  }

  return `Live space: ${state.currentThreatLabel}`;
}

function buildWeaponDoctrineRead(
  route: ActiveRoute,
  weaponId: WeaponId,
  squadDoctrineRead: SquadDoctrineRead,
  currentSpaceLabel: string
): WeaponDoctrineRead {
  const dishHouseBreachLive =
    route.id === "broken-signal" &&
    weaponId === "smg" &&
    squadDoctrineRead.title === "Room flood package" &&
    currentSpaceLabel.includes("Dish house breach");
  const tone = dishHouseBreachLive ? "steady" : getWeaponDoctrineTone(route, weaponId);
  const fitLabel = dishHouseBreachLive ? "Route-owned" : getWeaponDoctrineFitLabel(route, weaponId);
  const weaponName = WEAPONS[weaponId].name;
  const squadMixSummary = getActiveSquadWeaponMixSummary(3);
  const primarySpace = dishHouseBreachLive ? "Tight relay rooms and first-door flood tempo" : getWeaponDoctrineBestSpace(route, weaponId);
  const summary =
    weaponId === "none"
      ? `${formatWeaponDoctrine(weaponId)} ${currentSpaceLabel}. Let ${squadMixSummary} buy the first clean angle and only touch bodies or caches that sit directly on the escape line.`
      : dishHouseBreachLive
        ? `Selected fit: SMG owns this live dish-house breach because Broken Signal has already been crossed and the route now pays for room-flood tempo, dirty corner breaks, and keeping the yard lid outside. ${currentSpaceLabel}. ${weaponName} should be treated as the correct solve for this authored room take while ${squadMixSummary} shapes the rest of the push.`
      : `${formatRouteWeaponFit(route, weaponId)} ${currentSpaceLabel}. ${weaponName} should be treated as a doctrine pick, not a damage skin, while ${squadMixSummary} shapes the rest of the push.`;

  let title = `${weaponName} doctrine board`;
  if (weaponId === "none") {
    title = "No-primary doctrine board";
  } else if (dishHouseBreachLive) {
    title = `${weaponName} owns the dish-house breach`;
  } else if (tone === "steady") {
    title = `${weaponName} fits this route`;
  } else if (tone === "warn") {
    title = `${weaponName} needs disciplined space`;
  } else {
    title = `${weaponName} is the risk`;
  }

  return {
    tone,
    fitLabel,
    title,
    summary,
    primarySpace,
    failureSpace: getWeaponDoctrineFailureSpace(weaponId),
    squadPackage: squadDoctrineRead.packageLabel,
    routeCall: currentSpaceLabel,
    tags: [
      fitLabel,
      weaponId === "none" ? "survival insert" : WEAPONS[weaponId].name,
      primarySpace,
      squadDoctrineRead.title
    ]
  };
}

function getBestRouteForWeapon(weaponId: WeaponId): ActiveRoute {
  return RAID_ROUTES.reduce((bestRoute, candidate) =>
    getWeaponRouteFitScore(candidate.id, weaponId) > getWeaponRouteFitScore(bestRoute.id, weaponId) ? candidate : bestRoute
  );
}

function trimDoctrinePrefix(copy: string): string {
  return copy.replace(/^[A-Za-z-]+\sdoctrine:\s*/i, "");
}

function buildFieldWeaponDecisionRead(
  route: ActiveRoute,
  stagedWeaponId: WeaponId,
  stashCredits: number,
  deploymentCost: number,
  capturedWeapon: NonNullable<RaidSummary["capturedWeapon"]> | null
): FieldWeaponDecisionRead | null {
  if (!capturedWeapon) {
    return null;
  }

  const fieldWeaponId = capturedWeapon.weaponId;
  const fieldWeaponName = capturedWeapon.weaponName;
  const stagedWeaponName = WEAPONS[stagedWeaponId].name;
  const currentFitScore = getWeaponDoctrineRouteFitScore(route, fieldWeaponId);
  const stagedFitScore = getWeaponDoctrineRouteFitScore(route, stagedWeaponId);
  const currentFitLabel = getWeaponDoctrineFitLabel(route, fieldWeaponId);
  const stagedFitLabel = getWeaponDoctrineFitLabel(route, stagedWeaponId);
  const bestRoute = getBestRouteForWeapon(fieldWeaponId);
  const bestFitLabel = getWeaponDoctrineFitLabel(bestRoute, fieldWeaponId);
  const bestFitScore = getWeaponDoctrineRouteFitScore(bestRoute, fieldWeaponId);
  const cashShortfall = stashCredits < deploymentCost;
  const strongHold = currentFitScore >= 82 || bestFitScore >= 84;
  const shouldPivotNow = currentFitScore >= stagedFitScore + 6;
  const shouldSell = !shouldPivotNow && !strongHold && (cashShortfall || capturedWeapon.salvageValue >= 120);
  const stagedNow = stagedWeaponId === fieldWeaponId;

  let recommendation: FieldWeaponRecommendation = "hold";
  let tone: FieldWeaponDecisionRead["tone"] = "steady";
  let title = `${fieldWeaponName} is worth holding`;
  let meta = `${currentFitLabel} now // ${capturedWeapon.salvageValue} cr if sold`;
  let copy =
    `${fieldWeaponName} does not have to replace ${stagedWeaponName} on ${route.name}, but the fit is close enough that the wall should keep a real doctrine pivot instead of cashing it on sight. ` +
    `Hold it for the next run that wants heavier lane control than the staged ${stagedWeaponName.toLowerCase()}.`;

  if (shouldPivotNow) {
    recommendation = "pivot-now";
    tone = "support";
    title = `${fieldWeaponName} can own the next run`;
    meta = `${currentFitLabel} now // beats ${stagedWeaponName}`;
    copy =
      `${fieldWeaponName} fits ${route.name} better than the staged ${stagedWeaponName}, so this is not just broker metal. ` +
      `Keep it on the wall and pivot the next raid around ${trimDoctrinePrefix(formatWeaponDoctrine(fieldWeaponId)).toLowerCase()}`;
  } else if (shouldSell) {
    recommendation = "sell";
    tone = "warn";
    title = `${fieldWeaponName} is broker-first`;
    meta = `${currentFitLabel} here // ${capturedWeapon.salvageValue} cr keeps the wall moving`;
    copy =
      `${fieldWeaponName} is a real battlefield trophy, but it does not beat the staged ${stagedWeaponName} strongly enough to justify sitting on credits when the wall still needs cash. ` +
      `Sell it unless the next order explicitly wants ${bestRoute.name.toLowerCase()} style ${fieldWeaponName.toLowerCase()} pressure.`;
  }

  if (stagedNow) {
    recommendation = "pivot-now";
    tone = "support";
    title = `${fieldWeaponName} is staged from the wall`;
    meta = `${currentFitLabel} now // recovered gun live for ${route.name}`;
    copy =
      `${fieldWeaponName} came home off ${capturedWeapon.sourceLabel.toLowerCase()} and is already staged for the next run instead of sitting as broker weight. ` +
      `This proves the recovered gun loop is real: keep it, pivot the doctrine board around it, and spend the next raid on ${trimDoctrinePrefix(formatWeaponDoctrine(fieldWeaponId)).toLowerCase()}.`;
  }

  return {
    tone,
    recommendation,
    title,
    meta,
    copy,
    stagedNow,
    stagedWeaponName,
    currentFitLabel,
    stagedFitLabel,
    bestRouteName: bestRoute.name,
    bestFitLabel,
    sellValueLabel: `${capturedWeapon.salvageValue} credits`,
    readout: [
      { label: "Current Route", value: `${route.name} // ${currentFitLabel}` },
      { label: "Staged Gun", value: `${stagedWeaponName} // ${stagedFitLabel}` },
      { label: "Staged From Wall", value: stagedNow ? "Yes // recovered gun is live" : "No // still a wall decision" },
      { label: "Best Pivot", value: `${bestRoute.name} // ${bestFitLabel}` },
      { label: "Sell Value", value: `${capturedWeapon.salvageValue} credits` },
      {
        label: "Next Call",
        value:
          recommendation === "pivot-now"
            ? "Keep and pivot now"
            : recommendation === "sell"
              ? "Cash it unless the order changes"
              : "Hold as a doctrine pivot"
      }
    ]
  };
}

function buildStashConsequenceRead(
  summary: RaidSummary | null,
  route: ActiveRoute,
  routeIdentityRead: RouteIdentityRead,
  squadCadenceBoard: {
    tone: "steady" | "warn" | "danger";
    headline: string;
    meta: string;
    copy: string;
  },
  squadHandoffBoard: SquadHandoffBoard,
  stashOperationalBoard: StashOperationalBoard,
  fieldWeaponDecisionRead: FieldWeaponDecisionRead | null,
  memorialRecords: MemorialRecord[],
  firstSessionRead: FirstSessionRead,
  selectedWeaponId: WeaponId
): StashConsequenceRead {
  const unresolvedMemorialCount = memorialRecords.filter((entry) => entry.tone !== "settled").length;
  const missingBodyCount = memorialRecords.filter((entry) => entry.bodyStatus === "left-behind").length;
  const blockedChairCount = squadHandoffBoard.lanes.filter((lane) => lane.tone === "danger").length;
  const pendingChairCount = squadHandoffBoard.lanes.filter((lane) => lane.tone === "warn").length;
  const capturedWeapon = summary?.capturedWeapon ?? null;
  const extractProductRead = summary ? buildExtractProductReadFromSummary(summary) : null;

  if (!summary) {
    const broughtHome = "Nothing is on the wall yet. The first extract still has to prove what comes home and what actually matters.";
    const lost = "No chair debt is active yet, but that only means the squad has not been blooded by a real run.";
    const changed = firstSessionRead.active
      ? `${firstSessionRead.targetBuildingLabel} and ${firstSessionRead.targetLaneLabel} are already framed as the first real solve, so the opener reads like a tactical problem instead of a cold sandbox.`
      : stashOperationalBoard.copy;
    const nextCall = firstSessionRead.active
      ? `${firstSessionRead.routeName}: ${firstSessionRead.recommendedWeaponName} + ${firstSessionRead.recommendedTacticalServiceName}. ${firstSessionRead.nextRunReason}`
      : `${route.name}: ${routeIdentityRead.doctrineCall}`;
    return {
      tone: "support",
      title: "First haul still missing",
      meta: `${route.name} // ${routeIdentityRead.identityLabel} // first extract decides the wall`,
      copy: "The stash is still promise, not proof. The first clean extract has to create the loop before the product fantasy is real.",
      broughtHome,
      lost,
      changed,
      nextCall,
      recommendedRouteId: firstSessionRead.active ? firstSessionRead.routeId : route.id,
      recommendedRouteName: firstSessionRead.active ? firstSessionRead.routeName : route.name,
      doctrineCall: routeIdentityRead.doctrineCall,
      readout: [
        { label: "Brought Home", value: broughtHome },
        { label: "Lost", value: lost },
        { label: "Changed", value: changed },
        { label: "Next Call", value: nextCall }
      ]
    };
  }

  const broughtHomeParts = [
    `${summary.extractedValue} credits banked`,
    summary.contractCompleted ? `${summary.contractReward} contract payout` : `${summary.contractTitle} missed`,
    summary.demandPayout > 0 ? `${summary.demandPayout} demand credits` : "no demand cashout",
    summary.extractedSupplies.medkits > 0 || summary.extractedSupplies.ammoPacks > 0
      ? formatSupplyRecoverySentence(summary.extractedSupplies)
      : "no extra field supplies",
    capturedWeapon ? `${capturedWeapon.weaponName} recovered off ${capturedWeapon.sourceLabel}` : null
  ].filter((entry): entry is string => Boolean(entry));
  const broughtHome = `${broughtHomeParts.join(" | ")}.`;

  let lost = "No chair changed hands on the last run. The squad came home without fresh memorial debt.";
  if (summary.result === "failed") {
    lost = `The run failed, so carried haul and committed supplies stayed in ${summary.routeName}. ${summary.squadCasualties.length > 0 ? `${summary.squadCasualties.join(", ")} also dropped off the live stack.` : "The wall still pays for the failed push even without a clean casualty ledger."}`;
  } else if (summary.squadCasualties.length > 0 || unresolvedMemorialCount > 0 || blockedChairCount > 0) {
    lost =
      `${summary.squadCasualties.length > 0 ? `${summary.squadCasualties.join(", ")} left the deployable stack.` : "The stack took no fresh named loss,"} ` +
      `${missingBodyCount > 0 ? `${missingBodyCount} body ${missingBodyCount === 1 ? "is" : "are"} still left behind and at least one family call is still owed.` : unresolvedMemorialCount > 0 ? `${unresolvedMemorialCount} memorial follow-through ${unresolvedMemorialCount === 1 ? "is" : "are"} still open.` : "The memorial wall is clean."}`;
  }

  let changed = stashOperationalBoard.copy;
  if (blockedChairCount > 0 || pendingChairCount > 0) {
    changed = squadHandoffBoard.copy;
  } else if (fieldWeaponDecisionRead) {
    changed = fieldWeaponDecisionRead.copy;
  } else if (squadCadenceBoard.tone !== "steady") {
    changed = squadCadenceBoard.copy;
  }

  let nextCall = formatDebriefRecommendation(summary, route, selectedWeaponId);
  if (blockedChairCount > 0) {
    nextCall = `${squadHandoffBoard.copy} ${route.name}: ${routeIdentityRead.doctrineCall}`;
  } else if (fieldWeaponDecisionRead?.recommendation === "pivot-now") {
    nextCall = `${fieldWeaponDecisionRead.title}. ${route.name}: ${routeIdentityRead.doctrineCall}`;
  } else if (fieldWeaponDecisionRead?.recommendation === "sell") {
    nextCall = `${fieldWeaponDecisionRead.title}. Cash the wall, then run ${route.name} with ${WEAPONS[selectedWeaponId].name.toLowerCase()} discipline.`;
  } else if (summary.result === "failed") {
    nextCall = `${formatDebriefRecommendation(summary, route, selectedWeaponId)} ${route.name}: ${routeIdentityRead.doctrineCall}`;
  }

  let tone: StashConsequenceRead["tone"] = extractProductRead?.tone ?? "steady";
  let title = "The wall changed after that run";
  let copy = `${extractProductRead?.summary ?? "The stash is finally speaking in consequences instead of prep guesses."} ${extractProductRead?.callToAction ?? nextCall}`;
  if (blockedChairCount > 0 || missingBodyCount > 0) {
    tone = "danger";
    title = "Home, but the wall is still in debt";
    copy = `${squadHandoffBoard.copy} ${squadCadenceBoard.copy}`;
  } else if (fieldWeaponDecisionRead?.recommendation === "pivot-now") {
    tone = "support";
    title = "Recovered gear changed the next run";
    copy = `${fieldWeaponDecisionRead.copy} ${routeIdentityRead.summary}`;
  } else if (summary.result === "failed") {
    tone = "danger";
    title = "The stash is answering a failed push";
    copy = `${extractProductRead?.summary ?? summary.reason} ${squadCadenceBoard.copy}`;
  }

  return {
    tone,
    title,
    meta: `${summary.routeName} // ${extractProductRead?.headline ?? "Operation logged"} // ${squadCadenceBoard.headline}`,
    copy,
    broughtHome,
    lost,
    changed,
    nextCall,
    recommendedRouteId: route.id,
    recommendedRouteName: route.name,
    doctrineCall: routeIdentityRead.doctrineCall,
    readout: [
      { label: "Brought Home", value: broughtHome },
      { label: "Lost", value: lost },
      { label: "Changed", value: changed },
      { label: "Next Call", value: nextCall }
    ]
  };
}

function getPendingNoiseResponse(route: ActiveRoute, noiseResponseLevel: number) {
  return route.noiseResponseTiers[Math.max(0, Math.floor(noiseResponseLevel))] ?? null;
}

function getLastTriggeredNoiseResponse(route: ActiveRoute, noiseResponseLevel: number) {
  const normalizedLevel = Math.max(0, Math.floor(noiseResponseLevel));
  return normalizedLevel > 0 ? route.noiseResponseTiers[normalizedLevel - 1] ?? null : null;
}

function formatNoiseState(
  route: ActiveRoute,
  soundPressure: number,
  recentNoiseLabel: string,
  noiseResponseLevel: number
): string {
  void soundPressure;
  void recentNoiseLabel;
  void noiseResponseLevel;
  return getNoisePressureRead(route, raidController.state).compact;
}

function formatContractProgress(contract: RaidContractState): string {
  if (contract.completed) {
    return `Contract locked. Extract to collect ${contract.rewardCredits} credits.`;
  }

  if (contract.failed) {
    return "Contract window missed for this raid.";
  }

  if (contract.id === "scavCull") {
    return `${contract.progress} / ${contract.target} scavs down. Reward ${contract.rewardCredits} cr.`;
  }

  if (contract.id === "lootSweep") {
    return `${contract.progress} / ${contract.target} loose loot credits secured. Reward ${contract.rewardCredits} cr.`;
  }

  return `Secure first intel inside 45s. Reward ${contract.rewardCredits} cr on extract.`;
}

function formatContractTarget(contract: RaidContractState): string {
  if (contract.id === "scavCull") {
    return `${contract.target} confirmed scav kills`;
  }

  if (contract.id === "lootSweep") {
    return `${contract.target} loose loot credits tagged`;
  }

  return `First intel secured inside 45 seconds`;
}

function formatContractApproach(contractId: ContractId): string {
  if (contractId === "scavCull") {
    return "Fight forward and clear the route before the extract breaks open.";
  }

  if (contractId === "lootSweep") {
    return "Search when lanes calm down and turn a clean route into a richer extract.";
  }

  return "Hit the first intel hard, then stabilize before the map collapses around you.";
}

function formatRouteThreat(route: ActiveRoute): string {
  const riflemen = route.scavLayout.filter((entry) => entry === "rifleman").length;
  const rushers = route.scavLayout.filter((entry) => entry === "rusher").length;

  if (route.id === "broken-signal") {
    return `Expect ${riflemen} rifle-heavy holds stretched across the relay line and ${rushers} late collapse pushes on extract.`;
  }

  if (route.id === "sundered-run") {
    return `Expect ${rushers} fast room crashes separated by long freight rotations and a low gate extract that punishes overloaded retreats.`;
  }

  return `Balanced scav spread across ${route.combatPockets.length} dock pockets with ${riflemen} lane anchors and ${rushers} close pushes once the east hold turns live.`;
}

function formatRouteNoisePlan(route: ActiveRoute): string {
  const firstResponse = route.noiseResponseTiers[0];
  const finalResponse = route.noiseResponseTiers[route.noiseResponseTiers.length - 1];

  if (route.id === "broken-signal") {
    return `${firstResponse.label} starts at ${firstResponse.threshold.toFixed(1)} noise, and ${finalResponse.label} follows fast if you keep trading from the same long lane.`;
  }

  if (route.id === "sundered-run") {
    return `${firstResponse.label} waits until ${firstResponse.threshold.toFixed(1)} noise, but ${finalResponse.label} turns the longer freight retreat into a close-range flood.`;
  }

  return `${firstResponse.label} opens at ${firstResponse.threshold.toFixed(1)} noise and ${finalResponse.label} punishes a second loud commitment across the dock run before extract.`;
}

function formatLiveNoisePlan(route: ActiveRoute, noiseResponseLevel: number, soundPressure: number): string {
  void noiseResponseLevel;
  void soundPressure;
  const read = getNoisePressureRead(route, raidController.state);
  return `${read.status}. ${read.detail}`;
}

function formatRouteWeaponFit(route: ActiveRoute, weaponId: WeaponId): string {
  if (weaponId === "none") {
    return "Selected fit: no primary equipped. This is a pure survival insert, so avoid every fight you cannot outrun.";
  }

  if (weaponId === "pistol") {
    return route.id === "sundered-run"
      ? "Selected fit: sidearm-only is barely workable here if the plan is survival, quick room steals, and an early cut out."
      : route.id === "broken-signal"
        ? "Selected fit: sidearm-only is a desperation insert. Cross clean, steal a long gun fast, and never volunteer for the relay lane."
        : "Selected fit: sidearm-only keeps the fee low and the movement sharp, but every open dock lane is now a bad debt.";
  }

  if (weaponId === "worn-ak") {
    return route.id === "broken-signal"
      ? "Selected fit: the worn AK is a starter gun only. It can still tap one relay body, but the bad sight and single-fire pace make every exposed lane feel fragile."
      : route.id === "sundered-run"
        ? "Selected fit: the worn AK is barely enough here if you stay disciplined. It will punish room greed and any trench repeek you try to take like a clean rifle."
        : "Selected fit: the worn AK can survive the docks if you treat it like a beater tap gun, not a real lane owner. Missed follow-ups get expensive fast.";
  }

  if (weaponId === "knife") {
    return route.id === "broken-signal"
      ? "Selected fit: knife-only is a stealth greed pick. Avoid the relay lane, cut isolated room bodies, and leave before the district hardens."
      : route.id === "sundered-run"
        ? "Selected fit: knife-only is barely survivable here. Use it only for silent close rooms and treat every open trench lip like death."
        : "Selected fit: knife-only is a self-imposed raid challenge. Win through stealth, isolate one room at a time, and never owe the open dock lane a fair fight.";
  }

  if (weaponId === "short-mosin") {
    return route.id === "broken-signal"
      ? "Selected fit: the cut-down Mosin can still steal one relay body, but the bad sight and ugly cycle make every second shot feel late."
      : route.id === "sundered-run"
        ? "Selected fit: the cut-down Mosin is barely workable here. It can crack one trench or bunker lip, but the reload and sight picture punish greed."
        : "Selected fit: the cut-down Mosin is a poor dock rifle. You can still win one road peek with it, but the route will punish every missed follow-up.";
  }

  if (route.id === "broken-signal") {
    return weaponId === "amr"
      ? "Selected fit: Bastion AMR is top-tier here if you treat the relay lane like a deliberate plate-breaking problem and let the boys exploit the crack."
      : weaponId === "rifle"
      ? "Selected fit: rifle lanes this route well. Brace the relay angles and challenge plated riflemen on your timing."
      : weaponId === "pkm"
        ? "Selected fit: PKM is strong here if you treat the relay mouth like a real support lane and let the belt carry the crossing."
      : weaponId === "smg"
        ? "Selected fit: SMG works, but use cover hard through the long relay stretch because front plates punish open peeks."
        : "Selected fit: shotgun is high risk here. Survive the open relay stretch before forcing plated holds into door fights.";
  }

  if (route.id === "sundered-run") {
    return weaponId === "shotgun"
      ? "Selected fit: shotgun owns the freight-gate collapse if you keep enough shells for the hold and break plate from the side."
      : weaponId === "amr"
        ? "Selected fit: Bastion AMR is mostly the wrong tool here. It can erase one outer anchor, but the gate rooms and reload punish the rest of the route."
      : weaponId === "pkm"
        ? "Selected fit: PKM can hold the outer lane, but the gate rooms punish the reload and handling tax if you over-commit."
      : weaponId === "smg"
        ? "Selected fit: SMG can snowball the south rooms, but greed will widen your disengage."
        : "Selected fit: rifle stays safe early, then can still beat plated anchors cleanly when the route tightens.";
  }

  return weaponId === "amr"
    ? "Selected fit: Bastion AMR is strong on the docks if you use it to break the one plated lane owner that is freezing the road or exfil ring."
    : weaponId === "rifle"
    ? "Selected fit: rifle gives the cleanest all-round route control and the safest answer to plated lane anchors across the longer dock run."
    : weaponId === "pkm"
      ? "Selected fit: PKM is a real dockside support answer. Lock the road or the exfil ring and let the boys move under the belt."
    : weaponId === "smg"
      ? "Selected fit: SMG can turn this into a fast-value run if you keep the map from going loud too early and refuse frontal plate trades."
      : "Selected fit: shotgun is strongest once the dockside route narrows, but plated mid-lane peeks are bad trades unless you are close.";
}

function formatRouteContractPlan(route: ActiveRoute, contractId: ContractId): string {
  if (contractId === "scavCull") {
    return route.id === "broken-signal"
      ? "Cull contract line: break the first rifle angle, then collect kills while rotating from relay mouth into the north lift."
      : route.id === "sundered-run"
        ? "Cull contract line: take the south rooms in sequence so the extract is not stacked with live rushers."
        : "Cull contract line: clear the mid dock pocket before you trigger the east hold.";
  }

  if (contractId === "lootSweep") {
    return route.id === "sundered-run"
      ? "Loot contract line: cash the south caches after each close clear, then leave before the freight gate hardens."
      : "Loot contract line: use the quietest detour cache on the route, not every cache on the map.";
  }

  return route.id === "broken-signal"
    ? "Quick intel line: hit the relay-side intel first or the longer north extract stops being worth the risk."
    : "Quick intel line: sprint the first objective, then stabilize before you start searching for extra value.";
}

function formatRouteInsertionForecast(route: ActiveRoute, stagedLabel: string, stagedSummary: string): string {
  const [primary, secondary, tertiary] = route.insertionPoints;

  if (!primary) {
    return "Insertion forecast unavailable.";
  }

  const secondaryLabel = secondary ? `, ${secondary.label}` : "";
  const tertiaryLabel = tertiary ? `, ${tertiary.label}` : "";
  return `Potential insertions: ${primary.label}${secondaryLabel}${tertiaryLabel}. Available exfils: ${formatExtractOptions(route)}. Current roll: ${stagedLabel}. ${stagedSummary}`;
}

function formatPocketEventForecast(label: string, summary: string): string {
  return `Pocket event: ${label}. ${summary}`;
}

function formatOpeningRollTitle(stagedInsertionLabel: string, stagedThreatLabel: string): string {
  return `${stagedInsertionLabel} // ${stagedThreatLabel}`;
}

function formatOpeningRollDetail(
  stagedInsertionSummary: string,
  stagedThreatSummary: string,
  stagedPocketEventLabel: string
): string {
  const eventClause =
    stagedPocketEventLabel === "No pocket event"
      ? "No side stash is rolled into this opener, so the cleanest lane should stay the priority."
      : `${stagedPocketEventLabel} stays live inside this opener if you want to gamble for more value.`;

  return `${stagedInsertionSummary} ${stagedThreatSummary} ${eventClause}`;
}

function formatLiveInsertionReadout(label: string, threatLabel: string): string {
  return `${label} | ${threatLabel}`;
}

interface ExtractDecisionBoard {
  tone: "good" | "warn" | "danger";
  classification: ExtractProductRead["classification"];
  title: string;
  summary: string;
  bank: string;
  upside: string;
  risk: string;
  settlement: string;
  squadRead: string;
  callToAction: string;
  squadRiskTitle: string;
  squadRiskStatus: string;
  squadRiskDetail: string;
  squadRiskTone: "steady" | "warning" | "critical";
  pressureTitle: string;
  pressureStatus: string;
  pressureDetail: string;
  pressureCompact: string;
  pressureTone: "steady" | "warning" | "critical";
  posture: string;
  window: string;
  commandTone: "idle" | "cooldown" | FrontlineSupportOrderId;
  commandTitle: string;
  commandMetric: string;
  commandDetail: string;
  commandOrderId: FrontlineSupportOrderId | null;
  commandActionable: boolean;
}

function getPendingReinforcementLabel(source: PendingReinforcementState["source"], label: string): string {
  if (source === "extraction-wave") {
    return "extract crash";
  }

  if (source === "intel-wave") {
    return "intel crash";
  }

  if (source === "body-wave") {
    return "body alarm";
  }

  return label;
}

interface ExtractOptionComparisonRead {
  extract: RaidExtractDefinition;
  focused: boolean;
  cleanliness: RaidOperationRead["extractCleanliness"];
  cleanlinessLabel: string;
  phase: RaidOperationRead["phase"];
  phaseLabel: string;
  exitIntentLabel: string;
  pressureLabel: string;
  squadRiskCompact: string;
  ringThreats: number;
  screenTeams: number;
  recoveryTracks: number;
  fallbackTracks: number;
  holdSeconds: number;
  distanceLabel: string;
  stanceLabel: string;
  summary: string;
  deltaLabel: string;
  supportLabel: string;
}

interface FrontlineAftermathBoard {
  visible: boolean;
  tone: "live" | "held" | "loss";
  title: string;
  lead: string;
  summary: string;
  chips: string[];
  trafficHead: string;
  trafficLine: string;
}

interface FrontlineFocusBoard {
  visible: boolean;
  tone: "pressure" | "support" | "loss";
  title: string;
  lead: string;
  summary: string;
  chips: string[];
  actionHead: string;
  actionLine: string;
  focusTargets: Array<{
    id: number;
    label: string;
    state: string;
    active: boolean;
  }>;
}

function getManifestItemCount(manifest: LootManifest): number {
  return manifest.intel + manifest.medical + manifest.munitions + manifest.hardware;
}

function buildExtractDecisionBoard(
  route: ActiveRoute,
  contract: RaidContractState,
  demand: ReturnType<typeof raidController.getActiveDemand>,
  carriedValue: number,
  carriedManifest: LootManifest,
  carriedSupplies: SupplyStock,
  extractionReady: boolean,
  extractionHoldTimer: number,
  extractionHoldDuration: number,
  extractionContested: boolean,
  extractionContesters: number,
  pendingReinforcements: PendingReinforcementState[],
  noiseResponseLevel: number,
  soundPressure: number,
  intelSites: ReadonlyArray<IntelState>,
  loot: ReadonlyArray<LootState>,
  supplyCaches: ReadonlyArray<SupplyCacheState>,
  combatTelemetry: ReturnType<typeof getCombatDensityMetrics>,
  frontlineIncidentExtractRelief: number
): ExtractDecisionBoard {
  const focusedExtract =
    (raidController.state.activeExtractId
      ? raidController.state.extractZones.find((extract) => extract.id === raidController.state.activeExtractId) ?? null
      : null) ??
    raidController.state.extractZones[0] ??
    null;
  const focusedExtractLabel = focusedExtract?.label ?? route.extractLabel;
  const squadLeanActive =
    raidController.state.extractionReady &&
    raidController.state.activeExtractId !== null &&
    (raidController.state.activeFrontlineSupportOrderId === null || raidController.state.frontlineSupportOrderTimer <= 0);
  const manifestCount = getManifestItemCount(carriedManifest);
  const demandCredits = manifestCount * demand.bonusPerItem;
  const bankCredits = carriedValue + demandCredits + (contract.completed ? contract.rewardCredits : 0);
  const bankParts = [
    `${bankCredits} cr bankable`,
    manifestCount > 0 ? `${manifestCount} hot item${manifestCount === 1 ? "" : "s"}` : "no hot cargo",
    carriedSupplies.medkits > 0 || carriedSupplies.ammoPacks > 0
      ? formatSupplyRecoverySentence(carriedSupplies)
      : "no sealed stock"
  ];
  const bank = bankParts.join(" | ");
  const intelRemaining = intelSites.filter((site) => !site.secured).length;
  const untouchedCaches = supplyCaches.filter((cache) => !cache.searched).length;
  const contractLive = !contract.completed && !contract.failed;
  const upsideParts: string[] = [];

  if (!extractionReady && intelRemaining > 0) {
    upsideParts.push(`${intelRemaining} intel ${intelRemaining === 1 ? "gate" : "gates"} exfil`);
  }
  if (contractLive) {
    upsideParts.push(`${contract.rewardCredits} cr contract still live`);
  }
  if (loot.length > 0) {
    upsideParts.push(`${loot.length} loose ${loot.length === 1 ? "pickup" : "pickups"} left`);
  }
  if (untouchedCaches > 0) {
    upsideParts.push(`${untouchedCaches} cache${untouchedCaches === 1 ? "" : "s"} untouched`);
  }
  const upside = upsideParts.length > 0 ? upsideParts.slice(0, 3).join(" | ") : "The route is mostly spent. Little upside remains beyond surviving the exit.";

  const pendingResponse = getPendingNoiseResponse(route, noiseResponseLevel);
  const nextWave =
    pendingReinforcements.length > 0
      ? pendingReinforcements.reduce((best, entry) => (entry.timer < best.timer ? entry : best))
      : null;
  const noiseGap = pendingResponse ? Math.max(0, pendingResponse.threshold - soundPressure) : null;
  const nearestEnemyText =
    combatTelemetry.nearestEnemyDistance === null ? "no close contact" : `${combatTelemetry.nearestEnemyDistance.toFixed(0)}u nearest hostile`;
  const risk =
    extractionContested && extractionHoldTimer > 0
      ? `${focusedExtractLabel} blocked by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"} | signal burning`
      : extractionContested
        ? `${focusedExtractLabel} blocked by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"}`
        : nextWave
          ? `${getPendingReinforcementLabel(nextWave.source, nextWave.label)} in ${nextWave.timer.toFixed(1)}s`
          : pendingResponse
            ? `${noiseGap?.toFixed(1)} noise to ${pendingResponse.label} | ${nearestEnemyText}`
            : `${nearestEnemyText} | route response ladder spent`;

  const holdRelief =
    frontlineIncidentExtractRelief + (getPlannedExtractBenefit(raidController.state)?.holdReliefSeconds ?? 0);
  const holdReliefText = holdRelief > 0 ? ` | hold relief -${holdRelief.toFixed(1)}s` : "";
  const window = nextWave
    ? `Window: ${focusedExtractLabel} | ${getPendingReinforcementLabel(nextWave.source, nextWave.label)} in ${nextWave.timer.toFixed(1)}s | hold ${extractionHoldDuration.toFixed(1)}s${holdReliefText}`
    : pendingResponse
      ? `Window: ${focusedExtractLabel} | ${noiseGap?.toFixed(1)} noise before ${pendingResponse.label} | hold ${extractionHoldDuration.toFixed(1)}s${holdReliefText}`
      : `Window: ${focusedExtractLabel} | hold ${extractionHoldDuration.toFixed(1)}s${holdReliefText}`;
  const windowWithSquadLean = squadLeanActive ? `${window} | boys leaning ${focusedExtractLabel}` : window;
  const commandRecommendation = getExtractCommandRecommendation(raidController.state);
  const squadRisk = getExtractSquadRiskRead(raidController.state);
  const operationRead = getRaidOperationRead(raidController.state);
  const extractProductRead = buildLiveExtractProductRead(
    operationRead,
    {
      bank,
      upside,
      risk
    },
    squadRisk
  );
  const reinforcementPressure = getReinforcementPressureRead(raidController.state);
  const plannedExtractPosture = getPlannedExtractPosture(raidController.state);
  const tone: ExtractDecisionBoard["tone"] =
    extractProductRead.classification === "disciplined-clean-peel"
      ? "good"
      : extractProductRead.classification === "forced-collapse" || extractProductRead.classification === "collapse-taxed-extract"
        ? "danger"
        : "warn";

  return {
    tone,
    classification: extractProductRead.classification,
    title: extractProductRead.headline,
    summary: `${extractProductRead.summary} ${extractProductRead.settlementRead}`,
    bank,
    upside,
    risk,
    settlement: extractProductRead.settlementRead,
    squadRead: extractProductRead.squadRead,
    callToAction: extractProductRead.callToAction,
    squadRiskTitle: squadRisk.title,
    squadRiskStatus: squadRisk.status,
    squadRiskDetail: squadRisk.detail,
    squadRiskTone: squadRisk.tone,
    pressureTitle: reinforcementPressure?.title ?? "No flare stack live",
    pressureStatus: reinforcementPressure?.status ?? "No inbound stack is currently flaring on this route.",
    pressureDetail:
      reinforcementPressure?.detail ??
      "The route is not currently calling in a new sweep, so the next extract call can stay focused on loot, boys strain, and ring control.",
    pressureCompact: reinforcementPressure?.compact ?? "No flare stack",
    pressureTone: reinforcementPressure?.tone ?? "steady",
    posture: plannedExtractPosture?.status ?? "No staged pull yet",
    window: windowWithSquadLean,
    commandTone: commandRecommendation.tone,
    commandTitle: commandRecommendation.title,
    commandMetric: commandRecommendation.metric,
    commandDetail: commandRecommendation.detail,
    commandOrderId: commandRecommendation.orderId,
    commandActionable: commandRecommendation.actionable
  };
}

function renderExtractPressureRead(board: ExtractDecisionBoard): string {
  return `
    <div class="decision-pressure decision-pressure-${board.pressureTone}${board.pressureTone === "steady" ? " hidden" : ""}">
      <div class="decision-pressure-head">
        <span>Crash Read</span>
        <strong>${escapeHtml(board.pressureTitle)}</strong>
      </div>
      <p class="decision-pressure-status">${escapeHtml(board.pressureStatus)}</p>
      <p>${escapeHtml(board.pressureDetail)}</p>
      <p>${escapeHtml(board.settlement)}</p>
    </div>
  `;
}

function renderExtractSquadRisk(board: ExtractDecisionBoard): string {
  return `
    <div class="decision-squad decision-squad-${board.squadRiskTone}${board.squadRiskTone === "steady" ? " hidden" : ""}">
      <div class="decision-squad-head">
        <span>Squad Risk</span>
        <strong>${escapeHtml(board.squadRiskTitle)}</strong>
      </div>
      <p class="decision-squad-status">${escapeHtml(board.squadRiskStatus)}</p>
      <p>${escapeHtml(board.squadRiskDetail)}</p>
      <p>${escapeHtml(board.squadRead)}</p>
    </div>
  `;
}

function renderExtractCommandCall(board: ExtractDecisionBoard): string {
  const actionMarkup = board.commandOrderId
    ? `
      <button
        class="decision-order-button"
        data-support-order="${escapeHtml(board.commandOrderId)}"
        type="button"
        ${board.commandActionable ? "" : "disabled"}
      >
        ${escapeHtml(board.commandMetric)}
      </button>
    `
    : `<span class="decision-order-status">${escapeHtml(board.commandMetric)}</span>`;

  return `
    <div class="decision-order decision-order-${board.commandTone}${board.commandTone === "idle" && !board.commandOrderId ? " hidden" : ""}">
      <div class="decision-order-head">
        <span>Boys Call</span>
        <strong>${escapeHtml(board.commandTitle)}</strong>
      </div>
      <p>${escapeHtml(board.commandDetail)}</p>
      ${actionMarkup}
    </div>
  `;
}

function renderPlannedExtractCueList(
  cues: ReturnType<typeof getPlannedExtractStageCues>,
  options: {
    listClassName: string;
    itemClassName: string;
    metaClassName: string;
    detailClassName: string;
  }
): string {
  if (cues.length === 0) {
    return "";
  }

  return `
    <div class="${options.listClassName}">
      ${cues
        .slice(0, 3)
        .map(
          (cue) => `
            <div class="${options.itemClassName}">
              <div class="${options.metaClassName}">
                <strong>${escapeHtml(cue.supportLabel)}</strong>
                <span>${escapeHtml(cue.label.replace(/^.*\/\/\s*/, "").trim())}</span>
              </div>
              <p class="${options.detailClassName}">${escapeHtml(cue.compactLabel)}</p>
            </div>
          `
        )
        .join("")}
    </div>
  `;
}

function getExtractCleanlinessRank(cleanliness: RaidOperationRead["extractCleanliness"]): number {
  if (cleanliness === "clean") {
    return 0;
  }

  if (cleanliness === "warming") {
    return 1;
  }

  if (cleanliness === "hot") {
    return 2;
  }

  return 3;
}

function buildExtractOptionComparisonRead(extract: RaidExtractDefinition): ExtractOptionComparisonRead {
  const route = raidController.getActiveRoute();
  const baselineExtract =
    raidController.state.extractZones.find((candidate) => candidate.id === (raidController.state.activeExtractId ?? route.extractOptions[0]?.id)) ??
    route.extractOptions[0] ??
    extract;
  const baselineOperationRead = getRaidOperationRead(raidController.state);
  const baselineHoldMultiplier = baselineExtract.holdDurationMultiplier ?? 1;
  const candidateHoldMultiplier = extract.holdDurationMultiplier ?? 1;
  const projectedHoldSeconds = Number(
    Math.max(0.8, raidController.state.extractionHoldDuration * (candidateHoldMultiplier / baselineHoldMultiplier)).toFixed(1)
  );
  const simulatedState = structuredClone(raidController.state);
  simulatedState.activeExtractId = extract.id;
  simulatedState.extractZone = {
    position: { ...extract.position },
    radius: extract.radius
  };
  simulatedState.extractionHoldDuration = projectedHoldSeconds;

  const operationRead = getRaidOperationRead(simulatedState);
  const postureRead = getPlannedExtractPosture(simulatedState);
  const squadRiskRead = getExtractSquadRiskRead(simulatedState);
  const ringThreats = simulatedState.enemies.filter(
    (enemy) => Phaser.Math.Distance.Between(enemy.position.x, enemy.position.y, extract.position.x, extract.position.y) <= extract.radius + 96
  ).length;
  const screenTeams = simulatedState.frontlineSupports.filter(
    (support) =>
      support.kind === "fireteam" &&
      !support.playerEscort &&
      Phaser.Math.Distance.Between(support.position.x, support.position.y, extract.position.x, extract.position.y) <= extract.radius + 132
  ).length;
  const recoveryTracks = simulatedState.frontlineSupports.filter(
    (support) =>
      (support.kind === "recovery" || support.kind === "convoy") &&
      Phaser.Math.Distance.Between(support.position.x, support.position.y, extract.position.x, extract.position.y) <= extract.radius + 132
  ).length;
  const fallbackTracks = simulatedState.frontlineIncidents.filter(
    (incident) =>
      !incident.resolved &&
      (incident.kind === "convoy" || incident.kind === "casualty") &&
      Phaser.Math.Distance.Between(incident.position.x, incident.position.y, extract.position.x, extract.position.y) <= extract.radius + 148
  ).length;
  const distanceToExtract = Phaser.Math.Distance.Between(
    simulatedState.player.position.x,
    simulatedState.player.position.y,
    extract.position.x,
    extract.position.y
  );
  const deltaRank =
    getExtractCleanlinessRank(operationRead.extractCleanliness) - getExtractCleanlinessRank(baselineOperationRead.extractCleanliness);
  const deltaLabel =
    deltaRank <= -2
      ? "Much cleaner than current"
      : deltaRank === -1
        ? "Cleaner than current"
        : deltaRank === 0
          ? "Matches current risk"
          : deltaRank === 1
            ? "Hotter than current"
            : "Much hotter than current";
  const summary =
    operationRead.phase === "collapse"
      ? `${extract.label} is already collapsing. Clear the ring and treat this as a forced peel, not one more greedy touch.`
      : operationRead.extractCleanliness === "clean"
        ? `${extract.label} stays disciplined enough to bank now if the next pocket is not clearly worth the risk.`
        : operationRead.extractCleanliness === "warming"
          ? `${extract.label} is still workable, but the district is starting to lean on the peel.`
          : `${extract.label} only stays viable if the boys screen the ring and the next move is the last move.`;
  const settlementSummary =
    operationRead.settlementPressurePenalty > 0
      ? `${operationRead.settlementLabel} is ${operationRead.settlementVolatilityLabel.toLowerCase()}, so the peel inherits settlement debt. ${operationRead.settlementExtractRisk}`
      : `${operationRead.settlementLabel} is stable enough that the peel mostly lives or dies on the lane itself.`;
  const supportLabel =
    postureRead !== null
      ? `${postureRead.stagedFireteams} screen | ${postureRead.stagedRecoveryTracks} recovery | ${postureRead.stagedFallbacks} fallback`
      : `${screenTeams} screen | ${recoveryTracks} recovery | ${fallbackTracks} fallback`;
  const stanceLabel = postureRead?.status ?? `${operationRead.phaseLabel} | ${operationRead.extractCleanlinessLabel}`;

  return {
    extract,
    focused: extract.id === baselineExtract.id,
    cleanliness: operationRead.extractCleanliness,
    cleanlinessLabel: operationRead.extractCleanlinessLabel,
    phase: operationRead.phase,
    phaseLabel: operationRead.phaseLabel,
    exitIntentLabel: operationRead.exitIntentLabel,
    pressureLabel: operationRead.pressureLabel,
    squadRiskCompact: squadRiskRead.compact,
    ringThreats,
    screenTeams,
    recoveryTracks,
    fallbackTracks,
    holdSeconds: projectedHoldSeconds,
    distanceLabel: `${distanceToExtract.toFixed(0)}u peel`,
    stanceLabel,
    summary: `${summary} ${settlementSummary}`,
    deltaLabel,
    supportLabel
  };
}

function renderExtractChoiceButtons(): string {
  if (raidController.state.phase !== "raid") {
    return "";
  }

  const focusedExtractId = raidController.state.activeExtractId ?? raidController.state.extractZones[0]?.id ?? null;
  const selectionLocked = raidController.state.extractionHoldTimer > 0;

  return raidController.state.extractZones
    .map((extract) => {
      const comparison = buildExtractOptionComparisonRead(extract);
      const simulatedState = structuredClone(raidController.state);
      simulatedState.activeExtractId = extract.id;
      simulatedState.extractZone = {
        position: { ...extract.position },
        radius: extract.radius
      };
      simulatedState.extractionHoldDuration = comparison.holdSeconds;
      const plannedExtractPosture = getPlannedExtractPosture(simulatedState);
      const plannedExtractStageCues = getPlannedExtractStageCues(simulatedState);
      const focused = extract.id === focusedExtractId;
      const focusedStageCues =
        focused && plannedExtractPosture
          ? renderPlannedExtractCueList(plannedExtractStageCues, {
              listClassName: "planned-extract-cue-list extract-choice-support-list",
              itemClassName: "planned-extract-cue extract-choice-support-cue",
              metaClassName: "planned-extract-cue-meta extract-choice-support-cue-meta",
              detailClassName: "planned-extract-cue-detail extract-choice-support-cue-detail"
            })
          : "";
      const stateTag =
        focused && plannedExtractPosture
          ? "Boys leaning"
          : focused
            ? "Focused"
            : selectionLocked
              ? "Locked"
              : comparison.cleanliness === "clean"
                ? "Cleaner option"
                : "Shift focus";
      const supportMarkup =
        focused && plannedExtractPosture
          ? `
        <div class="extract-choice-support">
          <div class="extract-choice-support-head">
            <span>Planned Lean</span>
            <strong>${escapeHtml(plannedExtractPosture.title.replace(/^.*\/\/\s*/, "").trim())}</strong>
          </div>
          <p>${escapeHtml(plannedExtractPosture.detail)}</p>
          ${focusedStageCues}
        </div>
      `
          : "";

      return `
        <button
          class="extract-choice extract-choice-${comparison.cleanliness}${focused ? " active" : ""}"
          data-extract-select="${escapeHtml(extract.id)}"
          type="button"
          ${selectionLocked ? "disabled" : ""}
        >
          <div class="extract-choice-head">
            <strong>${escapeHtml(extract.label)}</strong>
            <span class="extract-choice-state">${escapeHtml(stateTag)}</span>
          </div>
          <p>${escapeHtml(comparison.summary)}</p>
          <div class="extract-choice-compare-grid">
            <span>${escapeHtml(comparison.cleanlinessLabel)}</span>
            <span>${escapeHtml(comparison.pressureLabel)}</span>
            <span>${escapeHtml(comparison.distanceLabel)}</span>
            <span>${escapeHtml(`${comparison.holdSeconds.toFixed(1)}s hold`)}</span>
          </div>
          <div class="extract-choice-meta">
            <span>${escapeHtml(comparison.deltaLabel)}</span>
            <span>${escapeHtml(extract.id.toUpperCase())}</span>
          </div>
          <div class="extract-choice-lane-read">
            <strong>${escapeHtml(`${comparison.phaseLabel} | ${comparison.exitIntentLabel}`)}</strong>
            <p>${escapeHtml(`${comparison.supportLabel} | ${comparison.squadRiskCompact}`)}</p>
            <p>${escapeHtml(`${comparison.ringThreats} ring threat${comparison.ringThreats === 1 ? "" : "s"} | ${comparison.stanceLabel}`)}</p>
          </div>
          ${supportMarkup}
        </button>
      `;
    })
    .join("");
}

function formatExtractionStatus(
  state: RaidContractState,
  extractionReady: boolean,
  extractionHoldTimer: number,
  extractionContested: boolean,
  extractionContesters: number,
  extractionHoldSlipping: boolean,
  pendingReinforcements: PendingReinforcementState[]
): string {
  const route = raidController.getActiveRoute();
  const focusedExtract = raidController.state.extractZone;
  const focusedExtractLabel =
    raidController.getExtractOptions().find(
      (extract) =>
        extract.position.x === focusedExtract.position.x &&
        extract.position.y === focusedExtract.position.y &&
        extract.radius === focusedExtract.radius
    )?.label ?? route.extractLabel;
  const reinforcementPressure = getReinforcementPressureRead(raidController.state);

  if (pendingReinforcements.length > 0 && reinforcementPressure) {
    return `${reinforcementPressure.title}. ${reinforcementPressure.compact}.`;
  }

  if (extractionContested) {
    return extractionHoldTimer > 0
      ? `${focusedExtractLabel} contested by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"}. Clear the ring before the beacon slips out.`
      : `${focusedExtractLabel} blocked by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"}. Clear the ring before starting the uplink.`;
  }

  if (extractionHoldTimer > 0) {
    return extractionHoldSlipping
      ? `${focusedExtractLabel} signal slipping. Re-enter the ring; ${extractionHoldTimer.toFixed(1)}s still needs holding.`
      : `${focusedExtractLabel} uplink live. Stay in the ring for ${extractionHoldTimer.toFixed(1)}s while the beacon pulls heat.`;
  }

  if (extractionReady) {
    return `Route is hot. Reach ${formatExtractOptions(route)} and trigger the cleaner exfil when the lane is clear.`;
  }

  if (state.id === "quickIntel" && !state.completed && !state.failed) {
    return "Secure the first cache early if you want the bonus contract payout.";
  }

  return "Secure both intel caches before the route out becomes worth the risk.";
}

function formatThreatReadout(): string {
  const { enemies, noiseResponseLevel, pendingReinforcements } = raidController.state;
  const route = raidController.getActiveRoute();
  const reinforcementPressure = getReinforcementPressureRead(raidController.state);

  if (pendingReinforcements.length > 0 && reinforcementPressure) {
    return reinforcementPressure.status;
  }

  if (enemies.length === 0) {
    if (noiseResponseLevel > 0) {
      return `${getLastTriggeredNoiseResponse(route, noiseResponseLevel)?.label ?? "Route sweep"} burned. Route is temporarily clear.`;
    }

    return "Route is temporarily clear.";
  }

  const engaged = enemies.filter((enemy) => enemy.awareness === "engaged").length;
  const investigating = enemies.filter((enemy) => enemy.awareness === "investigating").length;
  const patrol = enemies.length - engaged - investigating;
  const pinned = enemies.filter((enemy) => enemy.pressureType === "pinned").length;
  const suppressed = enemies.filter((enemy) => enemy.pressureType === "suppressed").length;
  const staggered = enemies.filter((enemy) => enemy.pressureType === "staggered").length;
  const parts: string[] = [];

  if (engaged > 0) {
    parts.push(`${engaged} hot`);
  }
  if (investigating > 0) {
    parts.push(`${investigating} sweeping`);
  }
  if (patrol > 0) {
    parts.push(`${patrol} holding`);
  }
  if (pinned > 0) {
    parts.push(`${pinned} pinned`);
  }
  if (suppressed > 0) {
    parts.push(`${suppressed} suppressed`);
  }
  if (staggered > 0) {
    parts.push(`${staggered} staggered`);
  }
  if (noiseResponseLevel > 0) {
    parts.push(`${getLastTriggeredNoiseResponse(route, noiseResponseLevel)?.label ?? "Route sweep"} triggered`);
  }

  if (route.combatPockets.length > 3) {
    parts.push(`${route.combatPockets.length} pockets active`);
  }

  return parts.join(" | ");
}

function formatThreatHint(): string {
  const {
    enemies,
    extractionReady,
    extractionWaveTriggered,
    extractionContested,
    extractionContesters,
    pendingReinforcements,
    soundPressure,
    noiseResponseLevel
  } = raidController.state;
  const route = raidController.getActiveRoute();
  const pendingResponse = getPendingNoiseResponse(route, noiseResponseLevel);
  const rushers = enemies.filter((enemy) => enemy.archetypeId === "rusher").length;
  const riflemen = enemies.filter((enemy) => enemy.archetypeId === "rifleman").length;
  const engaged = enemies.filter((enemy) => enemy.awareness === "engaged").length;
  const investigating = enemies.filter((enemy) => enemy.awareness === "investigating").length;
  const pinned = enemies.filter((enemy) => enemy.pressureType === "pinned").length;
  const suppressed = enemies.filter((enemy) => enemy.pressureType === "suppressed").length;
  const staggered = enemies.filter((enemy) => enemy.pressureType === "staggered").length;

  if (pendingReinforcements.length > 0) {
    const nextWave = pendingReinforcements.reduce((best, entry) => (entry.timer < best.timer ? entry : best));
    return nextWave.source === "extraction-wave"
      ? `Extract flare up. ${pendingReinforcements.length} scav${pendingReinforcements.length === 1 ? "" : "s"} arrive in ${nextWave.timer.toFixed(1)}s, so clear a pocket before you hold.`
      : nextWave.source === "intel-wave"
        ? `Intel flare up. ${pendingReinforcements.length} scav${pendingReinforcements.length === 1 ? "" : "s"} are crashing the terminal in ${nextWave.timer.toFixed(1)}s, so own a room before you greed the next move.`
        : `${nextWave.label} is stepping in. Red flares mark ${pendingReinforcements.length} inbound scav${pendingReinforcements.length === 1 ? "" : "s"} for the next ${nextWave.timer.toFixed(1)}s.`;
  }

  if (extractionReady && extractionWaveTriggered) {
    if (extractionContested) {
      return `The ring is still contested by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"}. Break the ring before you commit to the hold.`;
    }

    return "Extraction triggered reinforcements. Clear rushers before you try to hold the ring.";
  }

  if (pendingResponse && soundPressure >= pendingResponse.threshold - 0.45) {
    return `${pendingResponse.label} is close. One more loud break can pull ${pendingResponse.reinforcements.length} more scavs onto this route.`;
  }

  if (!pendingResponse && noiseResponseLevel > 0) {
    return "The route already spent its response ladder. Keep control of existing contacts and save the cleanest lane for extract.";
  }

  if (staggered > 0) {
    return "A stagger window is open. Step through the door now or repick before they settle.";
  }

  if (suppressed >= 2) {
    return "Suppressed scavs are not shooting cleanly. Use the collapse window before the pressure fades.";
  }

  if (pinned > 0) {
    return "Pinned scavs are stuck on the lane. Reposition while their next peek is delayed.";
  }

  if (engaged >= 3) {
    return "Multiple scavs are actively fighting. Break contact now or hard-commit to one short side of the lane.";
  }

  if (investigating >= 3) {
    return "The patrol is sweeping toward the last sound. Shift before the search line hardens into crossfire.";
  }

  if (soundPressure >= 2.4) {
    return "You are giving the map a clear read. Reposition before you keep trading from the same lane.";
  }

  if (route.combatPockets.length > 3) {
    return `${route.combatPockets.length} combat pockets are active on this route. Use the wider line to bypass one fight instead of clearing every lane in sequence.`;
  }

  if (rushers >= 2) {
    return "Multiple rushers on field. Shotgun and SMG routes are strongest when you can own the corner.";
  }

  if (riflemen >= 2) {
    return "Riflemen control long lanes and their front plate catches weak peeks. Break sight, brace up, or swing their side.";
  }

  return "Use the threat mix to decide whether this is a fast collapse or a cover-by-cover route.";
}

function formatPressureTag(pressureType: EnemyPressureType | null): string {
  if (pressureType === "pinned") {
    return "Pinned";
  }

  if (pressureType === "suppressed") {
    return "Suppressed";
  }

  if (pressureType === "staggered") {
    return "Staggered";
  }

  return "Pressure Clear";
}

function formatTelemetryDoorwayReadout(
  doorwayTelemetry: ReturnType<typeof getDoorwayTelemetrySnapshot>,
  playerJitter: ReturnType<typeof getPlayerJitterMetrics>
): string {
  const doorwayLabel = doorwayTelemetry.nearestDoorwayLabel ?? "no doorway read";
  const doorwayDistance =
    typeof doorwayTelemetry.nearestDoorwayDistance === "number"
      ? `${doorwayTelemetry.nearestDoorwayDistance.toFixed(1)}u`
      : "--";
  const stallLabel =
    doorwayTelemetry.stalledFireteams > 0
      ? `${doorwayTelemetry.stalledFireteams} stalled`
      : `${doorwayTelemetry.roomHoldCount} active`;
  const jitterLabel =
    playerJitter && playerJitter.jitterRatio > 0 ? `${Math.round(playerJitter.jitterRatio * 100)}% jitter` : "stable";

  return `${doorwayLabel} | ${doorwayDistance} | ${stallLabel} | ${jitterLabel}`;
}

function formatRoomStackTitle(doorwayTelemetry: ReturnType<typeof getDoorwayTelemetrySnapshot>): string {
  if (doorwayTelemetry.roomStackDepth <= 0) {
    return "No room chain live";
  }

  const nextTarget =
    doorwayTelemetry.roomTraversalTargets.find((target) => target.depth === Math.max(1, doorwayTelemetry.playerRoomDepth + 1)) ??
    doorwayTelemetry.roomTraversalTargets[0];

  if (doorwayTelemetry.playerInsideRoomStack && doorwayTelemetry.playerRoomDepth >= doorwayTelemetry.roomStackDepth) {
    return "Locker room locked";
  }

  if (doorwayTelemetry.playerInsideRoomStack && doorwayTelemetry.playerRoomDepth > 0) {
    return `Hold room ${doorwayTelemetry.playerRoomDepth}, ${nextTarget.depth >= 3 ? "locker" : "stack"} next`;
  }

  return `Cut into room 1 of ${doorwayTelemetry.roomStackDepth}`;
}

function formatRoomStackSummary(doorwayTelemetry: ReturnType<typeof getDoorwayTelemetrySnapshot>): string {
  if (doorwayTelemetry.roomTraversalTargets.length === 0) {
    return "No chained interior rooms are staged on this route.";
  }

  const activeTarget =
    doorwayTelemetry.roomTraversalTargets.find((target) => target.depth === Math.max(1, doorwayTelemetry.playerRoomDepth + 1)) ??
    doorwayTelemetry.roomTraversalTargets[0];
  const footholdText =
    doorwayTelemetry.activeFootholdLabels.length > 0
      ? doorwayTelemetry.activeFootholdLabels.join(" | ")
      : doorwayTelemetry.activeRoomHoldFireteams > 0
        ? `${doorwayTelemetry.activeRoomHoldFireteams} boys stacked`
        : "No foothold yet";
  const nextAction =
    activeTarget.depth >= 3 ? "Lock the locker room" : activeTarget.depth >= 2 ? "Stack through the follow-through room" : "Cut the first room";
  const cqbRead =
    doorwayTelemetry.roomShotgunnerCount > 0
      ? `${doorwayTelemetry.roomShotgunnerCount} shotgun breacher${doorwayTelemetry.roomShotgunnerCount === 1 ? "" : "s"} inside ${doorwayTelemetry.roomThreatTapeSummary.toLowerCase()}.`
      : doorwayTelemetry.roomThreatTapeSummary !== "No tape read"
        ? `${doorwayTelemetry.roomThreatTapeSummary} is layered across the stack.`
        : "";
  return `${nextAction}. ${footholdText}.${cqbRead ? ` ${cqbRead}` : ""}`;
}

function formatRoomStackPressure(doorwayTelemetry: ReturnType<typeof getDoorwayTelemetrySnapshot>): string {
  const parts = [`${doorwayTelemetry.roomDefenderCount} inside`];
  if (doorwayTelemetry.reserveRoomDefenderCount > 0) {
    parts.push(`${doorwayTelemetry.reserveRoomDefenderCount} reserve`);
  }
  if (doorwayTelemetry.stalledFireteams > 0) {
    parts.push(`${doorwayTelemetry.stalledFireteams} stalled`);
  }
  return parts.join(" | ");
}

function formatWeaponMixSummary(
  weaponIds: ReadonlyArray<WeaponId>,
  fallback: string,
  limit = 2
): string {
  if (weaponIds.length === 0) {
    return fallback;
  }

  const counts = new Map<WeaponId, number>();
  for (const weaponId of weaponIds) {
    counts.set(weaponId, (counts.get(weaponId) ?? 0) + 1);
  }

  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .slice(0, limit)
    .map(([weaponId, count]) => `${count}x ${WEAPONS[weaponId].name}`)
    .join(" | ");
}

function formatRoomStackLoadout(doorwayTelemetry: ReturnType<typeof getDoorwayTelemetrySnapshot>): string {
  if (doorwayTelemetry.roomShotgunnerCount > 0) {
    return `CQB ${doorwayTelemetry.roomShotgunnerCount} shotgun${doorwayTelemetry.roomShotgunnerCount === 1 ? "" : "s"}`;
  }

  if (doorwayTelemetry.roomWeaponMixSummary !== "No interior gun read") {
    return doorwayTelemetry.roomWeaponMixSummary;
  }

  return "CQB no gun read";
}

function formatBattlefieldCountsLine(friendlyCount: number, hostileCount: number): string {
  return `${friendlyCount} friendly | ${hostileCount} hostile`;
}

function formatBattlefieldSamplesLine(
  playerPosition: { x: number; y: number },
  friendlies: ReadonlyArray<{ id: string | number; x: number; y: number }>,
  hostiles: ReadonlyArray<{ id: string | number; x: number; y: number }>
): string {
  const friendlySample = friendlies[0];
  const hostileSample = hostiles[0];
  const playerLabel = `${playerPosition.x.toFixed(0)}, ${playerPosition.y.toFixed(0)}`;
  const friendlyLabel = friendlySample ? `${friendlySample.x.toFixed(0)}, ${friendlySample.y.toFixed(0)}` : "--";
  const hostileLabel = hostileSample ? `${hostileSample.x.toFixed(0)}, ${hostileSample.y.toFixed(0)}` : "--";

  return `player ${playerLabel} | friend ${friendlyLabel} | host ${hostileLabel}`;
}

function getEnemyMapClass(enemy: EnemyState): string {
  if (enemy.awareness === "engaged") {
    return "map-enemy map-enemy-engaged";
  }

  if (enemy.awareness === "investigating") {
    return "map-enemy map-enemy-investigating";
  }

  return "map-enemy map-enemy-patrol";
}

function getLootMapClass(category: ContrabandCategoryId): string {
  if (category === "intel") {
    return "map-loot-intel";
  }

  if (category === "medical") {
    return "map-loot-medical";
  }

  if (category === "munitions") {
    return "map-loot-ammo";
  }

  return "map-loot-hardware";
}

function renderEnemyFacingLine(enemy: EnemyState, project: (point: { x: number; y: number }) => { x: number; y: number }): string {
  const start = project(enemy.position);
  const end = project({
    x: enemy.position.x + enemy.facing.x * 82,
    y: enemy.position.y + enemy.facing.y * 82
  });

  return `<line class="map-enemy-facing map-enemy-facing-${enemy.awareness}" x1="${start.x.toFixed(1)}" y1="${start.y.toFixed(1)}" x2="${end.x.toFixed(1)}" y2="${end.y.toFixed(1)}" />`;
}

function distanceBetween(a: { x: number; y: number }, b: { x: number; y: number }): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function getDoorwayCenterPoint(obstacle: (typeof raidController.state.obstacles)[number], doorway: ArenaDoorway): { x: number; y: number } {
  const depth = doorway.depth ?? 40;

  if (doorway.side === "top") {
    return { x: obstacle.x + doorway.offset, y: obstacle.y - 4 + (depth + 4) / 2 };
  }

  if (doorway.side === "bottom") {
    return { x: obstacle.x + doorway.offset, y: obstacle.y + obstacle.height - depth + (depth + 4) / 2 };
  }

  if (doorway.side === "left") {
    return { x: obstacle.x - 4 + (depth + 4) / 2, y: obstacle.y + doorway.offset };
  }

  return {
    x: obstacle.x + obstacle.width - depth + (depth + 4) / 2,
    y: obstacle.y + doorway.offset
  };
}

function getClosestObstacleDoorway(
  obstacle: (typeof raidController.state.obstacles)[number],
  referencePoint: { x: number; y: number }
): ArenaDoorway | null {
  const doorways = obstacle.doorways ?? [];

  if (doorways.length === 0) {
    return null;
  }

  let closestDoorway = doorways[0];
  let closestDistance = Number.POSITIVE_INFINITY;

  for (const doorway of doorways) {
    const center = getDoorwayCenterPoint(obstacle, doorway);
    const candidateDistance = distanceBetween(referencePoint, center);

    if (candidateDistance < closestDistance) {
      closestDistance = candidateDistance;
      closestDoorway = doorway;
    }
  }

  return closestDoorway;
}

function getObstacleBreachPoint(
  obstacle: (typeof raidController.state.obstacles)[number]
): { x: number; y: number } | null {
  if (!obstacle.breach || obstacle.breach.breached) {
    return null;
  }

  const doorway = getClosestObstacleDoorway(obstacle, {
    x: obstacle.x + obstacle.width / 2,
    y: obstacle.y + obstacle.height / 2
  });
  if (!doorway) {
    return null;
  }

  const depth = doorway.depth ?? 40;

  if (doorway.side === "top") {
    return { x: obstacle.x + doorway.offset, y: obstacle.y - 4 + (depth + 4) / 2 };
  }

  if (doorway.side === "bottom") {
    return { x: obstacle.x + doorway.offset, y: obstacle.y + obstacle.height - depth + (depth + 4) / 2 };
  }

  if (doorway.side === "left") {
    return { x: obstacle.x - 4 + (depth + 4) / 2, y: obstacle.y + doorway.offset };
  }

  return {
    x: obstacle.x + obstacle.width - depth + (depth + 4) / 2,
    y: obstacle.y + doorway.offset
  };
}

function getIntelLabel(id: number): string {
  return id === 1 ? "Alpha Intel" : "Bravo Intel";
}

function formatRouteTitle(): string {
  const {
    extractionHoldTimer,
    extractionReady,
    extractionContested,
    activeSearch,
    activeIntelCapture,
    supplyCaches,
    intelSites,
    player
  } = raidController.state;

  if (extractionHoldTimer > 0) {
    if (extractionContested) {
      return "Clear The Extract Ring";
    }

    return "Hold The Extract Ring";
  }

  if (activeSearch) {
    const cache = supplyCaches.find((entry) => entry.id === activeSearch.cacheId);
    return cache ? `Finish ${cache.label}` : "Finish The Search";
  }

  if (activeIntelCapture) {
    return `Hold ${getIntelLabel(activeIntelCapture.intelId)}`;
  }

  if (!extractionReady) {
    const pendingIntel = intelSites.filter((site) => !site.secured);

    if (pendingIntel.length > 0) {
      const nearestIntel = pendingIntel.reduce((best, site) =>
        distanceBetween(site.position, player.position) < distanceBetween(best.position, player.position) ? site : best
      );
      return `Push ${getIntelLabel(nearestIntel.id)}`;
    }
  }

  if (extractionContested) {
    return "Clear The Extract Ring";
  }

  return "Break For Extraction";
}

function formatRouteCopy(): string {
  const {
    extractionHoldTimer,
    extractionReady,
    extractionContested,
    extractionContesters,
    activeSearch,
    activeIntelCapture,
    supplyCaches,
    intelSites,
    player,
    pendingReinforcements,
    soundPressure,
    noiseResponseLevel,
    currentThreatSummary,
    currentPocketEventLabel,
    currentPocketPlan,
    frontlineSupports,
    frontlineIncidents,
    obstacles,
    activeObstacleBreach
  } = raidController.state;
  const route = raidController.getActiveRoute();
  const pendingResponse = getPendingNoiseResponse(route, noiseResponseLevel);
  const frontlineSupportSummary = getFrontlineSupportSummary(frontlineSupports);
  const liveFrontlineBodies =
    frontlineSupports.reduce((sum, support) => sum + support.strength, 0) +
    frontlineIncidents.reduce((sum, incident) => sum + incident.strength, 0);
  const breachObstacle = activeObstacleBreach
    ? obstacles.find((obstacle) => obstacle.id === activeObstacleBreach.obstacleId)
    : obstacles.find((obstacle) => obstacle.breach && !obstacle.breach.breached && getObstacleBreachPoint(obstacle));

  if (pendingReinforcements.length > 0) {
    const nextWave = pendingReinforcements.reduce((best, entry) => (entry.timer < best.timer ? entry : best));
    return nextWave.source === "extraction-wave"
      ? `Extraction reinforcements are marked with red flares. You have ${nextWave.timer.toFixed(1)}s to clear a safer hold lane before they step in.`
      : nextWave.source === "intel-wave"
        ? `Intel reinforcements are marked with red flares. You have ${nextWave.timer.toFixed(1)}s to harden the terminal block before the crash reaches the rooms.`
        : `${nextWave.label} is already committed. Use the flare markers to break the cleaner side of the incoming sweep before it closes.`;
  }

  if (extractionHoldTimer > 0) {
    if (extractionContested) {
      return `The uplink is paused by ${extractionContesters} scav${extractionContesters === 1 ? "" : "s"} inside the ring. Clear the pocket, then finish the hold from cover.`;
    }

    return "You are committed. Stay inside the ring, break the first rusher, and do not chase kills outside cover.";
  }

  if (activeSearch) {
    const cache = supplyCaches.find((entry) => entry.id === activeSearch.cacheId);
    return cache
      ? `${cache.label} is being pulled. Leaving the pocket drops the search, so hold the corner until the timer clears.`
      : "Hold position and finish the cache search before rotating.";
  }

  if (activeIntelCapture) {
    return `${getIntelLabel(activeIntelCapture.intelId)} is mid-uplink. The crash started the moment you lit the terminal, so hold the room for the full channel before you try to peel.`;
  }

  if (activeObstacleBreach && breachObstacle?.breach) {
    return `${breachObstacle.breach.label} is mid-cut. Hold the breach point until the lane opens, then expect Blue to lean toward the noise.`;
  }

  if (!extractionReady) {
    const pendingIntel = intelSites.filter((site) => !site.secured);

    if (pendingIntel.length > 0) {
      const nearestIntel = pendingIntel.reduce((best, site) =>
        distanceBetween(site.position, player.position) < distanceBetween(best.position, player.position) ? site : best
      );
      const detourCache = supplyCaches
        .filter((cache) => !cache.searched)
        .sort(
          (left, right) =>
            distanceBetween(left.position, nearestIntel.position) - distanceBetween(right.position, nearestIntel.position)
        )[0];

      const detourText =
        detourCache && distanceBetween(detourCache.position, nearestIntel.position) < 250
          ? ` ${detourCache.label}${detourCache.opportunityId ? " is the live pocket event and" : ""} sits on a workable detour if the lane is quiet.`
          : "";

      return `${getIntelLabel(nearestIntel.id)} is the next mandatory touch.${detourText}`;
    }
  }

  if (pendingResponse && soundPressure >= pendingResponse.threshold - 0.45) {
    return `${pendingResponse.label} is almost on top of you. Either cool the route now or hard-commit before the next sweep lands.`;
  }

  if (soundPressure >= 2.4) {
    return "The map has a read on you. Cut a new angle into extraction instead of reusing the lane you just fired from.";
  }

  if (route.combatPockets.length > 3) {
    const hotPlan = currentPocketPlan
      .filter((entry) => entry.role === "primary-hot" || entry.role === "secondary-hot")
      .map((entry) => entry.pocketLabel)
      .join(" + ");
    const thinPlan = currentPocketPlan.find((entry) => entry.role === "thin")?.pocketLabel ?? null;
    return `${currentThreatSummary} ${route.combatPockets.length} combat pockets and ${liveFrontlineBodies} visible frontline bodies are stretching this district into a broader push. ${hotPlan ? `Hot lanes are ${hotPlan}. ` : ""}${thinPlan ? `${thinPlan} is the cleaner rotate. ` : ""}Pick one workable lane, let the far pockets stay noisy, and rotate around the fight instead of treating the route like a single arena.`;
  }

  if (extractionContested) {
    return `The route out is open, but ${extractionContesters} scav${extractionContesters === 1 ? " still owns" : "s still own"} the ring. Clear the hold before you burn time starting the uplink.`;
  }

  if (frontlineSupportSummary) {
    return frontlineSupportSummary;
  }

  if (breachObstacle?.breach) {
    return `${breachObstacle.breach.label} is available. Opening that cut gives you a cleaner movement lane, but the work will spike noise before the next push.`;
  }

  return `Both caches are secure. ${currentPocketEventLabel} stays optional if it is still untouched, but the route out matters more now. Available exfils are ${formatExtractOptions(route).toLowerCase()}. Clear the most dangerous contact, then commit to the cleaner ring.`;
}

function formatRouteTags(): string[] {
  const {
    player,
    extractionReady,
    extractionWaveTriggered,
    extractionContested,
    extractionContesters,
    intelSites,
    supplyCaches,
    enemies,
    activeIntelCapture,
    pendingReinforcements,
    soundPressure,
    noiseResponseLevel,
    currentPocketEventLabel,
    currentPocketPlan,
    frontlineSupports,
    frontlineIncidents,
    activeFrontlineSupportOrderId,
    frontlineSupportOrderTimer,
    frontlineSupportOrderCooldown,
    frontlineIncidentExtractRelief,
    obstacles,
    activeObstacleBreach
  } =
    raidController.state;
  const route = raidController.getActiveRoute();
  const pendingResponse = getPendingNoiseResponse(route, noiseResponseLevel);
  const tags: string[] = [];
  const unsecuredIntel = intelSites.filter((site) => !site.secured);
  const unsearchedCaches = supplyCaches.filter((cache) => !cache.searched);

  if (!extractionReady && unsecuredIntel.length > 0) {
    const nearestIntel = unsecuredIntel.reduce((best, site) =>
      distanceBetween(site.position, player.position) < distanceBetween(best.position, player.position) ? site : best
    );
    tags.push(`${getIntelLabel(nearestIntel.id)} ${Math.round(distanceBetween(player.position, nearestIntel.position))}m`);
  }

  const hotPockets = currentPocketPlan
    .filter((entry) => entry.role === "primary-hot" || entry.role === "secondary-hot")
    .map((entry) => entry.pocketLabel);
  const thinPocket = currentPocketPlan.find((entry) => entry.role === "thin");

  if (hotPockets.length > 0) {
    tags.push(`hot ${hotPockets.join(" + ")}`);
  }

  if (thinPocket) {
    tags.push(`thin ${thinPocket.pocketLabel}`);
  }

  if (extractionReady) {
    tags.push(`extract ${Math.round(distanceBetween(player.position, route.extractZone.position))}m`);
    if (route.extractOptions.length > 1) {
      tags.push(`${route.extractOptions.length} exfils live`);
    }
  }

  if (unsearchedCaches.length > 0) {
    const nearestCache = unsearchedCaches.reduce((best, cache) =>
      distanceBetween(cache.position, player.position) < distanceBetween(best.position, player.position) ? cache : best
    );
    tags.push(`${nearestCache.label} ${Math.round(distanceBetween(player.position, nearestCache.position))}m`);
  }

  const livePocketEvent = unsearchedCaches.find((cache) => cache.opportunityId);
  if (livePocketEvent) {
    tags.push(`${currentPocketEventLabel} live`);
  }

  tags.push(`${enemies.length} scavs live`);

  if (pendingReinforcements.length > 0) {
    const nextWave = pendingReinforcements.reduce((best, entry) => (entry.timer < best.timer ? entry : best));
    tags.push(`${pendingReinforcements.length} inbound ${nextWave.timer.toFixed(1)}s`);
  }

  if (frontlineSupports.length > 0) {
    const activeSupport = frontlineSupports.find((support) => support.status === "covering") ?? frontlineSupports[0];
    tags.push(`${activeSupport.label.toLowerCase()} ${activeSupport.status}`);
  }

  if (route.combatPockets.length > 3) {
    tags.push(`${route.combatPockets.length} pockets live`);
  }

  const liveIncidentOpportunities = frontlineIncidents.filter((incident) => incident.opportunityLabel && !incident.resolved);
  if (liveIncidentOpportunities.length > 0) {
    tags.push(`${liveIncidentOpportunities.length} war beat${liveIncidentOpportunities.length === 1 ? "" : "s"} live`);
  }

  const supportOrderTag = getSupportOrderTag(
    activeFrontlineSupportOrderId,
    frontlineSupportOrderTimer,
    frontlineSupportOrderCooldown
  );
  if (supportOrderTag) {
    tags.push(supportOrderTag);
  }

  if (pendingResponse) {
    tags.push(`${pendingResponse.label} ${Math.max(0, pendingResponse.threshold - soundPressure).toFixed(1)} away`);
  } else if (noiseResponseLevel > 0) {
    tags.push("route sweeps burned");
  }

  if (activeIntelCapture) {
    tags.push(`${getIntelLabel(activeIntelCapture.intelId)} uplink live`);
  }

  if (activeObstacleBreach) {
    const obstacle = obstacles.find((entry) => entry.id === activeObstacleBreach.obstacleId);
    if (obstacle?.breach) {
      tags.push(`${obstacle.breach.label.toLowerCase()} ${activeObstacleBreach.timer.toFixed(1)}s`);
    }
  } else {
    const liveBreach = obstacles.find((obstacle) => obstacle.breach && !obstacle.breach.breached && getObstacleBreachPoint(obstacle));
    if (liveBreach?.breach) {
      tags.push(`${liveBreach.breach.label.toLowerCase()} live`);
    }
  }

  if (extractionReady) {
    tags.push(extractionWaveTriggered ? "extract wave active" : "extract ready");
  }

  if (extractionContested) {
    tags.push(`${extractionContesters} in ring`);
  }

  if (frontlineIncidentExtractRelief > 0) {
    tags.push(`extract relief -${frontlineIncidentExtractRelief.toFixed(1)}s`);
  }

  return tags.slice(0, 5);
}

function renderNoiseDisciplineTags(route: ActiveRoute): string {
  const read = getNoisePressureRead(route, raidController.state);
  const blindFireRead = getBlindFireRead(raidController.state);
  const tags = [read.pressureLabel, read.nextResponseLabel, read.reinforcementLabel];
  if (blindFireRead.tone !== "steady") {
    tags.push(blindFireRead.compact);
  }
  return tags
    .map((tag) => `<span class="route-tag">${escapeHtml(tag)}</span>`)
    .join("");
}

