const officerToolsPanel = requireElement<HTMLElement>("[data-officer-tools-panel]");
const officerToolsCampValue = requireElement<HTMLElement>("[data-officer-tools-camp]");
const officerToolsTitleValue = requireElement<HTMLElement>("[data-officer-tools-title]");
const officerToolsBodyValue = requireElement<HTMLElement>("[data-officer-tools-body]");
const officerToolsTabButtons = Array.from(document.querySelectorAll<HTMLButtonElement>("[data-officer-tools-tab]"));
const firstMinuteRail = requireElement<HTMLElement>("[data-first-minute-rail]");
const firstMinuteTitleValue = requireElement<HTMLElement>("[data-first-minute-title]");
const firstMinuteCopyValue = requireElement<HTMLElement>("[data-first-minute-copy]");
const firstMinuteStepsValue = requireElement<HTMLElement>("[data-first-minute-steps]");

app.addEventListener("click", (event) => {
  const target = event.target instanceof HTMLElement ? event.target : null;

  if (target?.closest("[data-first-minute-dismiss]")) {
    officerToolsState.firstMinuteDismissed = true;
    renderOfficerTools();
    return;
  }

  const firstMinuteActionButton = target?.closest<HTMLButtonElement>("[data-first-minute-action]");
  const firstMinuteAction = firstMinuteActionButton?.dataset.firstMinuteAction;
  if (firstMinuteAction === "place-trench") {
    officerToolsState.placementMode = "trench";
    officerToolsState.buildModeOpen = true;
    officerToolsState.open = false;
    officerToolsState.pane = "build";
    officerToolsState.lastAction = "Trench placement armed. Move the ghost, scroll to rotate, then click the ground.";
    syncOfficerBuildPlacementPreview();
    renderOfficerTools();
    return;
  }
  if (firstMinuteAction === "priorities") {
    officerToolsState.open = true;
    officerToolsState.pane = "priorities";
    officerToolsState.workLens = "all";
    officerToolsState.lastAction = "Priority board open. Pick who builds, defends, suppresses, rescues, or hauls.";
    renderOfficerTools();
    return;
  }
  if (firstMinuteAction === "objective") {
    officerToolsState.open = true;
    officerToolsState.pane = "camp";
    officerToolsState.lastAction = "Objective: protect the Russian camp, build a line, and break the Ukrainian camp.";
    renderOfficerTools();
    return;
  }
  if (firstMinuteAction === "squad") {
    raidHudState.squadMenuOpen = true;
    officerToolsState.open = false;
    officerToolsState.lastAction = "Command authority received. Pick one camp soldier for the live squad.";
    updateUi();
    return;
  }

  if (target?.closest("[data-officer-tools-toggle]")) {
    officerToolsState.open = !officerToolsState.open;
    renderOfficerTools();
    return;
  }

  if (target?.closest("[data-build-mode-toggle]")) {
    officerToolsState.buildModeOpen = !officerToolsState.buildModeOpen;
    officerToolsState.pane = "build";
    if (!officerToolsState.buildModeOpen && officerToolsState.placementMode !== null) {
      cancelOfficerPlacement("Placement cancelled.");
    } else {
      officerToolsState.lastAction = officerToolsState.buildModeOpen
        ? "Build mode ready. Pick trench or ammo, then click the battlefield ghost."
        : "Build mode collapsed.";
      renderOfficerTools();
    }
    return;
  }

  if (target?.closest("[data-camp-art-toggle]")) {
    officerToolsState.playerCampArtVisible = !officerToolsState.playerCampArtVisible;
    getActiveRaidScene()?.setTownWarPlayerCampArtVisible(officerToolsState.playerCampArtVisible);
    officerToolsState.lastAction = officerToolsState.playerCampArtVisible
      ? "Russian camp art visible."
      : "Russian camp art hidden for trench debugging.";
    renderOfficerTools();
    return;
  }

  if (target?.closest("[data-officer-tools-close]")) {
    officerToolsState.open = false;
    renderOfficerTools();
    return;
  }

  const tabButton = target?.closest<HTMLButtonElement>("[data-officer-tools-tab]");
  const tabId = tabButton?.dataset.officerToolsTab as OfficerToolsPaneId | undefined;
  if (tabId && OFFICER_TOOLS_TABS.some((tab) => tab.id === tabId)) {
    officerToolsState.pane = tabId;
    officerToolsState.open = true;
    renderOfficerTools();
    return;
  }

  const expeditionButton = target?.closest<HTMLButtonElement>("[data-officer-expedition]");
  const expeditionObjective = expeditionButton?.dataset.officerExpedition as TownWarExpeditionObjectiveId | undefined;
  if (expeditionObjective) {
    const campId = getOfficerCamp(townWarController.getSnapshot());
    const result = townWarController.orderExpedition(campId, expeditionObjective);
    officerToolsState.open = true;
    officerToolsState.pane = "push";
    officerToolsState.lastAction = result.ok ? result.readable : `Expedition failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const expeditionRetreatButton = target?.closest<HTMLButtonElement>("[data-officer-expedition-retreat]");
  const expeditionRetreatId = expeditionRetreatButton?.dataset.officerExpeditionRetreat;
  if (expeditionRetreatId) {
    const result = townWarController.requestExpeditionRetreat(expeditionRetreatId);
    officerToolsState.open = true;
    officerToolsState.pane = "push";
    officerToolsState.lastAction = result.ok ? result.readable : `Retreat failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const demolitionPrepButton = target?.closest<HTMLButtonElement>("[data-officer-demolition-prep]");
  if (demolitionPrepButton) {
    const campId = getOfficerCamp(townWarController.getSnapshot());
    const result = townWarController.prepareDemolition(campId);
    officerToolsState.open = true;
    officerToolsState.pane = "push";
    officerToolsState.lastAction = result.ok ? result.readable : `Demolition prep failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const campBreachButton = target?.closest<HTMLButtonElement>("[data-officer-camp-breach]");
  const weakPointId = campBreachButton?.dataset.officerCampBreach;
  if (weakPointId) {
    const townWar = townWarController.getSnapshot();
    const campId = getOfficerCamp(townWar);
    const targetCampId = campId === "camp-a" ? "camp-b" : "camp-a";
    const result = townWarController.orderCampBreach({
      attackerCampId: campId,
      targetCampId,
      weakPointId
    });
    officerToolsState.open = true;
    officerToolsState.pane = "push";
    officerToolsState.lastAction = result.ok ? result.readable : `Breach failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const workLensButton = target?.closest<HTMLButtonElement>("[data-officer-work-lens]");
  const workLensId = workLensButton?.dataset.officerWorkLens as OfficerWorkLensId | undefined;
  if (workLensId && OFFICER_WORK_LENSES.some((lens) => lens.id === workLensId)) {
    officerToolsState.workLens = workLensId;
    officerToolsState.open = true;
    officerToolsState.pane = "priorities";
    officerToolsState.lastAction =
      workLensId === "all" ? "Showing every Russian soldier on the priority board." : `Filtering priority board to ${workLensId} work.`;
    renderOfficerTools();
    return;
  }

  const selectSoldierButton = target?.closest<HTMLButtonElement>("[data-officer-select-soldier]");
  const selectSoldierId = selectSoldierButton?.dataset.officerSelectSoldier;
  if (selectSoldierId) {
    const townWar = townWarController.getSnapshot();
    const soldier = townWar.soldiers.find((entry) => entry.id === selectSoldierId);
    officerToolsState.selectedSoldierId = selectSoldierId;
    officerToolsState.open = true;
    officerToolsState.pane = "priorities";
    officerToolsState.lastAction = soldier
      ? `Inspecting ${soldier.displayName}: ${getTownWarTaskLabel(soldier)}.`
      : "Selected soldier is no longer on the board.";
    renderOfficerTools();
    return;
  }

  const placeButton = target?.closest<HTMLButtonElement>("[data-officer-place]");
  const placeKind = placeButton?.dataset.officerPlace;
  if (placeKind === "trench" || placeKind === "ammo-crate" || placeKind === "dugout") {
    const nextMode = placeKind;
    const fromBuildModeStrip = placeButton !== null && placeButton !== undefined && placeButton.closest("[data-build-mode-strip]") !== null;
    officerToolsState.placementMode = officerToolsState.placementMode === nextMode ? null : nextMode;
    officerToolsState.buildModeOpen = true;
    officerToolsState.open = fromBuildModeStrip ? false : true;
    officerToolsState.pane = "build";
    officerToolsState.lastAction =
      officerToolsState.placementMode === nextMode
        ? `${nextMode === "trench" ? "Trench placement armed. Scroll to rotate, then click the ghost." : nextMode === "dugout" ? "Dugout placement armed. Scroll to rotate the protected face, then click the ghost." : "Ammo crate placement armed. Move the mouse over the battlefield and click the ghost."}`
        : `${nextMode === "trench" ? "Trench" : nextMode === "dugout" ? "Dugout" : "Ammo crate"} placement cancelled.`;
    syncOfficerBuildPlacementPreview();
    renderOfficerTools();
    return;
  }

  const buildButton = target?.closest<HTMLButtonElement>("[data-officer-build]");
  const buildKind = buildButton?.dataset.officerBuild;
  if (buildKind) {
    townWarController.ensureDemoSeeded();
    officerToolsState.buildModeOpen = true;
    const campId = getOfficerCamp(townWarController.getSnapshot());
    const result =
      buildKind === "trench"
        ? townWarController.placeDebugTrench(campId, raidController.state.player.position, officerToolsState.placementAngleRadians)
        : buildKind === "ammo-crate"
          ? townWarController.orderAmmoCrate(campId, null)
          : buildKind === "dugout"
            ? townWarController.orderDugout(campId, raidController.state.player.position, 1, officerToolsState.placementAngleRadians)
          : null;
    officerToolsState.lastAction = result?.ok
      ? buildKind === "trench"
        ? "Fast trench completed at your current position."
        : buildKind === "dugout"
          ? "Dugout queued at your current position."
        : `Ammo crate queued for ${getOfficerCampLabel(townWarController.getSnapshot())}.`
      : `Order failed: ${result?.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const presetButton = target?.closest<HTMLButtonElement>("[data-officer-priority-preset]");
  const soldierPreset = presetButton?.dataset.officerPriorityPreset;
  const presetSoldierId = presetButton?.dataset.officerSoldier;
  if (soldierPreset && presetSoldierId) {
    const result = townWarController.applySoldierPriorityPreset(presetSoldierId, soldierPreset);
    officerToolsState.selectedSoldierId = presetSoldierId;
    officerToolsState.lastAction = result.ok
      ? `${result.soldier?.displayName ?? "Soldier"} shifted to ${soldierPreset}.`
      : `Priority failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const priorityButton = target?.closest<HTMLButtonElement>("[data-officer-priority-work]");
  const priorityWork = priorityButton?.dataset.officerPriorityWork as TownWarWorkPriorityId | undefined;
  const prioritySoldierId = priorityButton?.dataset.officerSoldier;
  const priorityValue = Number(priorityButton?.dataset.officerPriorityValue ?? "5");
  if (priorityWork && prioritySoldierId && Number.isFinite(priorityValue)) {
    const result = townWarController.setSoldierPriority(prioritySoldierId, priorityWork, priorityValue);
    officerToolsState.selectedSoldierId = prioritySoldierId;
    officerToolsState.lastAction = result.ok
      ? `${result.soldier?.displayName ?? "Soldier"} now favors ${priorityWork}.`
      : `Priority failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const priorityAdjustButton = target?.closest<HTMLButtonElement>("[data-officer-priority-adjust]");
  const adjustWork = priorityAdjustButton?.dataset.officerPriorityAdjust as TownWarWorkPriorityId | undefined;
  const adjustSoldierId = priorityAdjustButton?.dataset.officerSoldier;
  const adjustDelta = Number(priorityAdjustButton?.dataset.officerPriorityDelta ?? "0");
  if (adjustWork && adjustSoldierId && Number.isFinite(adjustDelta)) {
    const townWar = townWarController.getSnapshot();
    const soldier = townWar.soldiers.find((entry) => entry.id === adjustSoldierId);
    const currentPriority = soldier?.workPriorities[adjustWork] ?? 0;
    const nextPriority = Math.round(clampValue(currentPriority + adjustDelta, 0, 5));
    const result = townWarController.setSoldierPriority(adjustSoldierId, adjustWork, nextPriority);
    officerToolsState.selectedSoldierId = adjustSoldierId;
    officerToolsState.lastAction = result.ok
      ? `${result.soldier?.displayName ?? "Soldier"} ${adjustWork} priority ${result.priority}.`
      : `Priority failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const campWorkButton = target?.closest<HTMLButtonElement>("[data-officer-camp-work]");
  const campWork = campWorkButton?.dataset.officerCampWork as TownWarCampWorkPriorityId | undefined;
  const campPriority = Number(campWorkButton?.dataset.officerCampPriority ?? "5");
  if (campWork && Number.isFinite(campPriority)) {
    const campId = getOfficerCamp(townWarController.getSnapshot());
    const result = townWarController.setCampWorkPriority(campId, campWork, campPriority);
    officerToolsState.lastAction = result.ok
      ? `${campWork} camp priority set to ${result.priority}.`
      : `Camp work failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

  const operationButton = target?.closest<HTMLButtonElement>("[data-officer-operation]");
  const operationAction = operationButton?.dataset.officerOperation;
  if (operationAction) {
    const profile = operationButton?.dataset.officerOperationProfile ?? "balanced";
    const result =
      operationAction === "prepare"
        ? townWarController.prepareOperationStockpile(
            profile === "build"
              ? { ammo: 180, build: 260, food: 140, med: 70 }
              : profile === "medical"
                ? { ammo: 160, build: 140, food: 180, med: 120 }
                : { ammo: 220, build: 220, food: 180, med: 90 }
          )
        : operationAction === "start"
          ? townWarController.startNextOperation()
          : townWarController.endOperation();
    officerToolsState.lastAction = result.readable;
    updateUi();
    return;
  }

  const flankButton = target?.closest<HTMLButtonElement>("[data-officer-flank-lane]");
  const flankLane = flankButton?.dataset.officerFlankLane as TownWarFlankLaneId | undefined;
  const flankPressure = flankButton?.dataset.officerFlankPressure as TownWarFlankPressureLevel | undefined;
  if (flankLane && flankPressure) {
    const campId = getOfficerCamp(townWarController.getSnapshot());
    const result = townWarController.stageFlankPressure(flankLane, flankPressure, campId);
    officerToolsState.lastAction = result.ok
      ? `${flankLane} flank staged: ${result.outcome?.outcome ?? "active"}.`
      : `Flank failed: ${result.reason ?? "unknown"}.`;
    updateUi();
    return;
  }

});

stashOverlay.addEventListener("dragstart", (event) => {
  const source = event.target instanceof HTMLElement ? (event.target.closest("[data-drag-kind]") as HTMLElement | null) : null;
  const payload = parseStashDragPayload(source);

  if (!payload || !event.dataTransfer) {
    return;
  }

  stashDragState.payload = payload;
  stashUiState.selectedTileId = payload.tileId;
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", payload.kind === "weapon" ? payload.weaponId ?? "" : payload.resource ?? "");
});

stashOverlay.addEventListener("dragend", () => {
  stashDragState.payload = null;
  clearDragTargets();
});

stashOverlay.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) {
    return;
  }

  const source = event.target instanceof HTMLElement ? (event.target.closest("[data-drag-kind]") as HTMLElement | null) : null;
  const payload = parseStashDragPayload(source);
  if (!payload) {
    return;
  }

  event.preventDefault();
  manualDragState.payload = payload;
  manualDragState.pointerId = event.pointerId;
  manualDragState.startX = event.clientX;
  manualDragState.startY = event.clientY;
  manualDragState.active = false;
});

stashOverlay.addEventListener("mousedown", (event) => {
  if (event.button !== 0 || manualDragState.payload) {
    return;
  }

  const source = event.target instanceof HTMLElement ? (event.target.closest("[data-drag-kind]") as HTMLElement | null) : null;
  const payload = parseStashDragPayload(source);
  if (!payload) {
    return;
  }

  event.preventDefault();
  manualDragState.payload = payload;
  manualDragState.pointerId = -1;
  manualDragState.startX = event.clientX;
  manualDragState.startY = event.clientY;
  manualDragState.active = false;
});

window.addEventListener("pointermove", (event) => {
  if (!manualDragState.payload || manualDragState.pointerId !== event.pointerId) {
    return;
  }

  const distance = Math.hypot(event.clientX - manualDragState.startX, event.clientY - manualDragState.startY);
  if (!manualDragState.active && distance < 6) {
    return;
  }

  manualDragState.active = true;
  stashDragState.payload = manualDragState.payload;

  const dropTarget = resolveDropTarget(document.elementFromPoint(event.clientX, event.clientY), manualDragState.payload);
  previewDropTarget(dropTarget, manualDragState.payload);
});

window.addEventListener("mousemove", (event) => {
  if (!manualDragState.payload || manualDragState.pointerId !== -1) {
    return;
  }

  const distance = Math.hypot(event.clientX - manualDragState.startX, event.clientY - manualDragState.startY);
  if (!manualDragState.active && distance < 6) {
    return;
  }

  manualDragState.active = true;
  stashDragState.payload = manualDragState.payload;

  const dropTarget = resolveDropTarget(document.elementFromPoint(event.clientX, event.clientY), manualDragState.payload);
  previewDropTarget(dropTarget, manualDragState.payload);
});

window.addEventListener("pointerup", (event) => {
  if (!manualDragState.payload || manualDragState.pointerId !== event.pointerId) {
    return;
  }

  const payload = manualDragState.payload;
  const wasActive = manualDragState.active;
  if (wasActive) {
    const dropTarget = resolveDropTarget(document.elementFromPoint(event.clientX, event.clientY), payload);
    if (commitDropTarget(dropTarget, payload)) {
      manualDragState.suppressClick = true;
    }
  }

  clearManualDragState();
  stashDragState.payload = null;
  clearDragTargets();
});

window.addEventListener("mouseup", (event) => {
  if (!manualDragState.payload || manualDragState.pointerId !== -1) {
    return;
  }

  const payload = manualDragState.payload;
  const wasActive = manualDragState.active;
  if (wasActive) {
    const dropTarget = resolveDropTarget(document.elementFromPoint(event.clientX, event.clientY), payload);
    if (commitDropTarget(dropTarget, payload)) {
      manualDragState.suppressClick = true;
    }
  }

  clearManualDragState();
  stashDragState.payload = null;
  clearDragTargets();
});

window.addEventListener("pointercancel", (event) => {
  if (manualDragState.pointerId !== event.pointerId) {
    return;
  }

  clearManualDragState();
  stashDragState.payload = null;
  clearDragTargets();
});

stashOverlay.addEventListener("click", (event) => {
  if (manualDragState.suppressClick) {
    manualDragState.suppressClick = false;
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  const target = event.target instanceof HTMLElement ? event.target : null;
  const actionButton = target?.closest<HTMLElement>("[data-stash-action]");

  if (actionButton) {
    const tileId = actionButton.dataset.stashActionTile;
    const actionId = actionButton.dataset.stashAction;
    const tile = tileId ? findStashTile(tileId) : null;

    if (tile && actionId && isStashActionId(actionId)) {
      runStashTileAction(tile, actionId);
    }

    closeStashContextMenu();
    return;
  }

  const commandTabButton = target?.closest<HTMLButtonElement>("[data-command-tab]");
  const commandTab = commandTabButton?.dataset.commandTab as CommandTabId | undefined;
  if (commandTab) {
    stashUiState.activeCommandTab = commandTab;
    closeStashContextMenu();
    updateUi();
    return;
  }

  const topTabButton = target?.closest<HTMLButtonElement>("[data-stash-top-tab]");
  const topTab = topTabButton?.dataset.stashTopTab as TopTabId | undefined;
  if (topTab) {
    stashUiState.activeTopTab = topTab;
    closeStashContextMenu();
    updateUi();
    return;
  }

  const jumpTabButton = target?.closest<HTMLButtonElement>("[data-stash-jump-tab]");
  const jumpTab = jumpTabButton?.dataset.stashJumpTab as TopTabId | undefined;
  if (jumpTab) {
    stashUiState.activeTopTab = jumpTab;
    closeStashContextMenu();
    updateUi();
    return;
  }

  const stashFilterButton = target?.closest<HTMLButtonElement>("[data-stash-filter]");
  const stashFilter = stashFilterButton?.dataset.stashFilter as StashFilterId | undefined;
  if (stashFilter) {
    stashUiState.rackFilter = stashFilter;
    closeStashContextMenu();
    updateUi();
    return;
  }

  const recruitButton = target?.closest<HTMLButtonElement>("[data-squad-recruit]");
  const recruitId = recruitButton?.dataset.squadRecruit;
  if (recruitId) {
    raidController.promoteRecruit(recruitId);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const rollRecruitButton = target?.closest<HTMLButtonElement>("[data-camp-roll-recruits]");
  if (rollRecruitButton) {
    raidController.rollRecruitCandidates();
    closeStashContextMenu();
    updateUi();
    return;
  }

  const unifiedAssignButton = target?.closest<HTMLButtonElement>("[data-unified-squad-assign]");
  const unifiedAssignId = unifiedAssignButton?.dataset.unifiedSquadAssign;
  if (unifiedAssignId && raidController.state.phase === "raid") {
    raidController.assignUnifiedSoldierToSquad(unifiedAssignId);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const unifiedUnassignButton = target?.closest<HTMLButtonElement>("[data-unified-squad-unassign]");
  const unifiedUnassignId = unifiedUnassignButton?.dataset.unifiedSquadUnassign;
  if (unifiedUnassignId && raidController.state.phase === "raid") {
    raidController.unassignUnifiedSoldierFromSquad(unifiedUnassignId);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const rotateButton = target?.closest<HTMLButtonElement>("[data-squad-rotate]");
  const rotateId = rotateButton?.dataset.squadRotate;
  if (rotateId) {
    raidController.rotateSquadMate(rotateId);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const squadWeaponButton = target?.closest<HTMLButtonElement>("[data-squad-weapon]");
  const squadWeaponId = squadWeaponButton?.dataset.squadWeapon;
  const squadWeaponDirection = Number(squadWeaponButton?.dataset.squadWeaponDirection ?? "0");
  if (squadWeaponId && (squadWeaponDirection === -1 || squadWeaponDirection === 1)) {
    raidController.cycleSquadMateWeapon(squadWeaponId, squadWeaponDirection);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const memorialActionButton = target?.closest<HTMLButtonElement>("[data-memorial-action]");
  const memorialId = memorialActionButton?.dataset.memorialId;
  const memorialAction = memorialActionButton?.dataset.memorialAction as "call-family" | "hold-wake" | undefined;
  if (memorialId && memorialAction) {
    raidController.processMemorialAction(memorialId, memorialAction);
    closeStashContextMenu();
    updateUi();
    return;
  }

  const paperdollActionButton = target?.closest<HTMLButtonElement>("[data-paperdoll-action]");
  const paperdollSlotAction = paperdollActionButton?.dataset.paperdollSlotAction as PaperdollSlotId | undefined;
  const paperdollActionId = paperdollActionButton?.dataset.paperdollAction;
  const paperdollDirection = Number(paperdollActionButton?.dataset.paperdollDirection ?? "0");
  if (paperdollSlotAction && paperdollActionId) {
    handlePaperdollAction(
      paperdollSlotAction,
      paperdollActionId,
      paperdollDirection === -1 || paperdollDirection === 1 ? paperdollDirection : undefined
    );
    closeStashContextMenu();
    return;
  }

  const paperdollSlot = target?.closest<HTMLElement>("[data-paperdoll-slot]");
  const focusedPaperdollSlot = paperdollSlot?.dataset.paperdollSlot as PaperdollSlotId | undefined;
  if (focusedPaperdollSlot) {
    focusPaperdollSlot(focusedPaperdollSlot);
    closeStashContextMenu();
    return;
  }

  const quickSlotClearButton = target?.closest<HTMLButtonElement>("[data-quick-slot-clear]");
  const quickSlotToClear = quickSlotClearButton?.dataset.quickSlotClear as QuickSlotId | undefined;
  if (quickSlotToClear) {
    clearQuickSlotAssignment(quickSlotToClear);
    closeStashContextMenu();
    return;
  }

  const tile = target?.closest<HTMLElement>("[data-stash-tile-id]");
  if (tile?.dataset.stashTileId) {
    stashUiState.selectedTileId = tile.dataset.stashTileId;
    closeStashContextMenu();
    updateUi();
    return;
  }

  if (!target?.closest("[data-stash-context-menu]")) {
    closeStashContextMenu();
    updateUi();
  }
});

stashSearchValue.addEventListener("input", () => {
  stashUiState.rackSearchQuery = stashSearchValue.value;
  updateUi();
});

stashOverlay.addEventListener("mousemove", (event) => {
  const tileElement = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>("[data-stash-tile-id]") : null;

  if (!tileElement?.dataset.stashTileId) {
    renderTooltip(null);
    return;
  }

  renderTooltip(findStashTile(tileElement.dataset.stashTileId), event.clientX, event.clientY);
});

stashOverlay.addEventListener("mouseleave", () => {
  renderTooltip(null);
});

stashOverlay.addEventListener("contextmenu", (event) => {
  const target = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>("[data-stash-tile-id]") : null;

  if (!target?.dataset.stashTileId) {
    return;
  }

  event.preventDefault();
  stashUiState.selectedTileId = target.dataset.stashTileId;
  stashUiState.contextTileId = target.dataset.stashTileId;
  stashUiState.contextX = event.clientX;
  stashUiState.contextY = event.clientY;
  updateUi();
});

stashOverlay.addEventListener("keydown", (event) => {
  const target = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>("[data-paperdoll-slot]") : null;
  const slotId = target?.dataset.paperdollSlot as PaperdollSlotId | undefined;

  if (!slotId) {
    return;
  }

  if (event.key === "Enter" || event.key === " ") {
    event.preventDefault();
    focusPaperdollSlot(slotId);
  }
});

stashOverlay.addEventListener("dragover", (event) => {
  const payload = stashDragState.payload;
  if (!payload) {
    return;
  }

  const dropTarget = resolveDropTarget(event.target, payload);
  if (!previewDropTarget(dropTarget, payload)) {
    return;
  }

  event.preventDefault();
  if (event.dataTransfer) {
    event.dataTransfer.dropEffect = "move";
  }
});

stashOverlay.addEventListener("drop", (event) => {
  const payload = stashDragState.payload;
  if (!payload) {
    return;
  }

  const dropTarget = resolveDropTarget(event.target, payload);
  if (!commitDropTarget(dropTarget, payload)) {
    return;
  }

  event.preventDefault();
  stashDragState.payload = null;
  clearDragTargets();
});

stashOverlay.addEventListener("dragleave", (event) => {
  if (event.relatedTarget instanceof Node && stashOverlay.contains(event.relatedTarget)) {
    return;
  }

  clearDragTargets();
});

window.addEventListener("keydown", (event) => {
  if (stashOverlay.classList.contains("hidden") || event.repeat || event.defaultPrevented) {
    return;
  }

  const target = event.target as HTMLElement | null;
  const isEditableTarget =
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target?.isContentEditable === true;

  if (isEditableTarget || event.key.toLowerCase() !== "r" || !stashUiState.selectedTileId) {
    return;
  }

  const selectedTile = findStashTile(stashUiState.selectedTileId);

  if (!selectedTile || selectedTile.dragSource !== "rack" || !canRotateRackTile(selectedTile)) {
    return;
  }

  event.preventDefault();
  rotateRackTile(selectedTile.id);
});

