const SURVIVOR_TEST_ENEMY_FRAME_COUNT = 20;
const SURVIVOR_TEST_ENEMY_FRAME_WIDTH = 313;
const SURVIVOR_TEST_ENEMY_FRAME_HEIGHT = 207;
const SURVIVOR_TEST_CHATGPT_FRAME_COLUMNS = 5;
const SURVIVOR_TEST_CHATGPT_FRAME_ROWS = 4;
const SURVIVOR_TEST_CHATGPT_FRAME_WIDTH = 1724 / SURVIVOR_TEST_CHATGPT_FRAME_COLUMNS;
const SURVIVOR_TEST_CHATGPT_FRAME_HEIGHT = 912 / SURVIVOR_TEST_CHATGPT_FRAME_ROWS;

function getSurvivorTestTargetArtLabel(artId: SurvivorTestTargetArtId): string {
  return artId === "chatgpt-grid" ? "ChatGPT Sheet" : "Blue Variant";
}

function getSurvivorTestTargetFrameIndex(nowMs: number, targetId: SurvivorTestTargetId): number {
  return (
    Math.floor(nowMs / 120) +
    (targetId === "alpha" ? 0 : targetId === "bravo" ? 3 : targetId === "charlie" ? 6 : targetId === "delta" ? 9 : 12)
  ) % SURVIVOR_TEST_ENEMY_FRAME_COUNT;
}

function getSurvivorTestActorArtLabel(actorArtId: SurvivorTestActorArtId): string {
  return actorArtId === "chatgptimage" ? "ChatGPT Actor" : "Default Survivor";
}

