function getSurvivorTestShotProfile(weaponId: WeaponId): SurvivorTestShotProfile {
  return SURVIVOR_TEST_SHOT_PROFILES[weaponId] ?? SURVIVOR_TEST_SHOT_PROFILES.rifle;
}

function getSurvivorTestWeaponPreset(weaponId: WeaponId): SurvivorTestWeaponPreset {
  return SURVIVOR_TEST_WEAPON_PRESETS[weaponId as keyof typeof SURVIVOR_TEST_WEAPON_PRESETS] ?? SURVIVOR_TEST_WEAPON_PRESETS.rifle;
}

function getCurrentSurvivorTestWeaponPreset(): SurvivorTestWeaponPreset {
  return getSurvivorTestWeaponPreset(survivorWalkState.weaponId);
}

function getSurvivorTestRefireDelayMs(weaponId: WeaponId): number {
  switch (weaponId) {
    case "worn-ak":
      return 160;
    case "knife":
      return 180;
    case "rifle":
      return 118;
    default:
      return 120;
  }
}

let survivorTestNextShotEventId = 1;
let survivorTestLastShotEvent: SurvivorTestShotEvent | null = null;
let survivorTestLastKnifeEvent: SurvivorTestKnifeEvent | null = null;
const survivorTestImpactStates: SurvivorTestImpactState[] = Array.from({ length: 6 }, (_, index) => ({
  id: index,
  x: 0,
  y: 0,
  kind: "ground-hit",
  surfaceKind: "dirt",
  startAtMs: 0,
  untilMs: 0
}));

let survivorTestSuppressionPulseUntilMs = 0;
let survivorTestAudioContext: AudioContext | null = null;
let survivorTestNoiseBuffer: AudioBuffer | null = null;

function getSurvivorTestAudioCtor():
  | (new () => AudioContext)
  | null {
  if (typeof window === "undefined") {
    return null;
  }
  const audioCtor = window.AudioContext ?? (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  return audioCtor ?? null;
}

function ensureSurvivorTestAudioReady(): AudioContext | null {
  const AudioCtor = getSurvivorTestAudioCtor();
  if (!AudioCtor) {
    return null;
  }
  if (survivorTestAudioContext === null) {
    survivorTestAudioContext = new AudioCtor();
  }
  if (survivorTestAudioContext.state === "suspended") {
    void survivorTestAudioContext.resume().catch(() => {});
  }
  return survivorTestAudioContext;
}

function getSurvivorTestNoiseBuffer(context: AudioContext): AudioBuffer {
  if (survivorTestNoiseBuffer !== null && survivorTestNoiseBuffer.sampleRate === context.sampleRate) {
    return survivorTestNoiseBuffer;
  }
  const length = Math.max(1, Math.floor(context.sampleRate * 0.35));
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const channel = buffer.getChannelData(0);
  for (let index = 0; index < length; index += 1) {
    channel[index] = Math.random() * 2 - 1;
  }
  survivorTestNoiseBuffer = buffer;
  return buffer;
}

function playSurvivorTone(
  context: AudioContext,
  options: {
    type: OscillatorType;
    frequencyHz: number;
    startAtSeconds: number;
    durationMs: number;
    attackMs: number;
    gain: number;
    endFrequencyHz?: number;
    pan?: number;
  }
): void {
  const oscillator = context.createOscillator();
  const gainNode = context.createGain();
  const panner = context.createStereoPanner();
  oscillator.type = options.type;
  oscillator.frequency.setValueAtTime(options.frequencyHz, options.startAtSeconds);
  if (typeof options.endFrequencyHz === "number") {
    oscillator.frequency.exponentialRampToValueAtTime(
      Math.max(20, options.endFrequencyHz),
      options.startAtSeconds + options.durationMs / 1000
    );
  }
  panner.pan.setValueAtTime(options.pan ?? 0, options.startAtSeconds);
  gainNode.gain.setValueAtTime(0.0001, options.startAtSeconds);
  gainNode.gain.linearRampToValueAtTime(
    options.gain,
    options.startAtSeconds + options.attackMs / 1000
  );
  gainNode.gain.exponentialRampToValueAtTime(
    0.0001,
    options.startAtSeconds + options.durationMs / 1000
  );
  oscillator.connect(gainNode);
  gainNode.connect(panner);
  panner.connect(context.destination);
  oscillator.start(options.startAtSeconds);
  oscillator.stop(options.startAtSeconds + options.durationMs / 1000 + 0.02);
}

function playSurvivorNoiseBurst(
  context: AudioContext,
  options: {
    startAtSeconds: number;
    durationMs: number;
    gain: number;
    highpassHz?: number;
    lowpassHz?: number;
    pan?: number;
  }
): void {
  const noise = context.createBufferSource();
  noise.buffer = getSurvivorTestNoiseBuffer(context);
  const highpass = context.createBiquadFilter();
  highpass.type = "highpass";
  highpass.frequency.setValueAtTime(options.highpassHz ?? 540, options.startAtSeconds);
  const lowpass = context.createBiquadFilter();
  lowpass.type = "lowpass";
  lowpass.frequency.setValueAtTime(options.lowpassHz ?? 4200, options.startAtSeconds);
  const gainNode = context.createGain();
  const panner = context.createStereoPanner();
  panner.pan.setValueAtTime(options.pan ?? 0, options.startAtSeconds);
  gainNode.gain.setValueAtTime(0.0001, options.startAtSeconds);
  gainNode.gain.linearRampToValueAtTime(options.gain, options.startAtSeconds + 0.008);
  gainNode.gain.exponentialRampToValueAtTime(0.0001, options.startAtSeconds + options.durationMs / 1000);
  noise.connect(highpass);
  highpass.connect(lowpass);
  lowpass.connect(gainNode);
  gainNode.connect(panner);
  panner.connect(context.destination);
  noise.start(options.startAtSeconds);
  noise.stop(options.startAtSeconds + options.durationMs / 1000 + 0.03);
}

function getSurvivorStereoPan(targetX: number): number {
  return Phaser.Math.Clamp((targetX - survivorWalkState.x) * 2.8, -0.8, 0.8);
}

function playSurvivorTestShotAudio(shotEvent: SurvivorTestShotEvent): void {
  const context = ensureSurvivorTestAudioReady();
  if (!context) {
    return;
  }
  const profile = getSurvivorTestShotProfile(shotEvent.weaponId);
  const startAtSeconds = context.currentTime + 0.002;
  const pan = getSurvivorStereoPan(shotEvent.target.x);
  playSurvivorTone(context, {
    type: profile.shotBodyType,
    frequencyHz: profile.shotBodyHz,
    endFrequencyHz: Math.max(40, profile.shotBodyHz * 0.58),
    startAtSeconds,
    durationMs: Math.max(70, profile.shotTailMs),
    attackMs: 3,
    gain: profile.id === "starter" ? 0.07 : profile.id === "marksman" ? 0.11 : 0.09,
    pan
  });
  playSurvivorTone(context, {
    type: "triangle",
    frequencyHz: profile.crackHz,
    endFrequencyHz: Math.max(120, profile.crackHz * 0.64),
    startAtSeconds,
    durationMs: 44,
    attackMs: 2,
    gain: profile.crackGain,
    pan
  });
  playSurvivorTone(context, {
    type: "sine",
    frequencyHz: profile.shotTailHz,
    endFrequencyHz: Math.max(40, profile.shotTailHz * 0.7),
    startAtSeconds: startAtSeconds + 0.018,
    durationMs: profile.shotTailMs,
    attackMs: 8,
    gain: profile.id === "marksman" ? 0.048 : profile.id === "starter" ? 0.028 : 0.038,
    pan: pan * 0.65
  });
  playSurvivorNoiseBurst(context, {
    startAtSeconds,
    durationMs: profile.id === "marksman" ? 110 : 86,
    gain: profile.noiseGain,
    highpassHz: profile.id === "starter" ? 640 : 820,
    lowpassHz: profile.id === "marksman" ? 5200 : 4600,
    pan
  });

  const impactAtSeconds = startAtSeconds + Math.max(0.006, (shotEvent.travelUntilMs - shotEvent.firedAtMs) / 1000);
  if (shotEvent.surfaceKind === "soft-body") {
    playSurvivorTone(context, {
      type: "triangle",
      frequencyHz: shotEvent.impactKind === "target-down" ? 112 : 146,
      endFrequencyHz: shotEvent.impactKind === "target-down" ? 76 : 102,
      startAtSeconds: impactAtSeconds,
      durationMs: shotEvent.impactKind === "target-down" ? 140 : 92,
      attackMs: 4,
      gain: shotEvent.impactKind === "target-down" ? 0.06 : 0.042,
      pan
    });
    playSurvivorNoiseBurst(context, {
      startAtSeconds: impactAtSeconds,
      durationMs: shotEvent.impactKind === "target-down" ? 90 : 60,
      gain: 0.012,
      highpassHz: 180,
      lowpassHz: 1200,
      pan
    });
  } else {
    const surfaceImpactMap: Record<Exclude<SurvivorTestShotSurfaceKind, "soft-body">, { toneHz: number; gain: number; noiseGain: number; highpassHz: number; lowpassHz: number; durationMs: number }> = {
      dirt: { toneHz: 180, gain: 0.024, noiseGain: 0.01, highpassHz: 240, lowpassHz: 1400, durationMs: 72 },
      grass: { toneHz: 220, gain: 0.02, noiseGain: 0.008, highpassHz: 300, lowpassHz: 1800, durationMs: 64 },
      bark: { toneHz: 250, gain: 0.028, noiseGain: 0.011, highpassHz: 360, lowpassHz: 2200, durationMs: 78 },
      stone: { toneHz: 420, gain: 0.032, noiseGain: 0.012, highpassHz: 1200, lowpassHz: 5200, durationMs: 86 }
    };
    const surfaceImpact = surfaceImpactMap[shotEvent.surfaceKind];
    playSurvivorTone(context, {
      type: shotEvent.surfaceKind === "stone" ? "square" : "triangle",
      frequencyHz: surfaceImpact.toneHz,
      endFrequencyHz: Math.max(60, surfaceImpact.toneHz * 0.72),
      startAtSeconds: impactAtSeconds,
      durationMs: surfaceImpact.durationMs,
      attackMs: 2,
      gain: surfaceImpact.gain,
      pan
    });
    playSurvivorNoiseBurst(context, {
      startAtSeconds: impactAtSeconds,
      durationMs: surfaceImpact.durationMs,
      gain: surfaceImpact.noiseGain,
      highpassHz: surfaceImpact.highpassHz,
      lowpassHz: surfaceImpact.lowpassHz,
      pan
    });
  }
}

