const SURVIVOR_TEST_TREE_SURFACES = [
  { x: 0.07, y: 0.16, rx: 0.06, ry: 0.12 },
  { x: 0.195, y: 0.165, rx: 0.05, ry: 0.1 },
  { x: 0.91, y: 0.16, rx: 0.06, ry: 0.12 },
  { x: 0.79, y: 0.19, rx: 0.05, ry: 0.1 },
  { x: 0.1, y: 0.89, rx: 0.055, ry: 0.1 },
  { x: 0.89, y: 0.88, rx: 0.06, ry: 0.12 }
] as const;

const SURVIVOR_TEST_COVER_SURFACES = [
  { x: 0.39, y: 0.305, rx: 0.085, ry: 0.055 },
  { x: 0.675, y: 0.35, rx: 0.095, ry: 0.06 },
  { x: 0.565, y: 0.73, rx: 0.1, ry: 0.06 }
] as const;

const SURVIVOR_TEST_GRASS_SURFACES = [
  { x: 0.32, y: 0.225, rx: 0.09, ry: 0.055 },
  { x: 0.77, y: 0.81, rx: 0.082, ry: 0.05 },
  { x: 0.605, y: 0.52, rx: 0.065, ry: 0.046 }
] as const;

function isPointInsideEllipse(
  pointX: number,
  pointY: number,
  centerX: number,
  centerY: number,
  radiusX: number,
  radiusY: number
): boolean {
  if (radiusX <= 0 || radiusY <= 0) {
    return false;
  }
  const dx = (pointX - centerX) / radiusX;
  const dy = (pointY - centerY) / radiusY;
  return dx * dx + dy * dy <= 1;
}

function classifySurvivorTestSurfaceAt(
  pointX: number,
  pointY: number,
  hitTarget: boolean
): SurvivorTestShotSurfaceKind {
  if (hitTarget) {
    return "soft-body";
  }
  for (const surface of SURVIVOR_TEST_COVER_SURFACES) {
    if (isPointInsideEllipse(pointX, pointY, surface.x, surface.y, surface.rx, surface.ry)) {
      return "stone";
    }
  }
  for (const surface of SURVIVOR_TEST_TREE_SURFACES) {
    if (isPointInsideEllipse(pointX, pointY, surface.x, surface.y, surface.rx, surface.ry)) {
      return "bark";
    }
  }
  for (const surface of SURVIVOR_TEST_GRASS_SURFACES) {
    if (isPointInsideEllipse(pointX, pointY, surface.x, surface.y, surface.rx, surface.ry)) {
      return "grass";
    }
  }
  return "dirt";
}

function getSurvivorTestSceneMetrics(): { width: number; height: number } {
  const rect = survivorTestScene.getBoundingClientRect();
  return {
    width: Math.max(1, rect.width),
    height: Math.max(1, rect.height)
  };
}

function getSurvivorTestRayGeometry(
  originX: number,
  originY: number,
  targetX: number,
  targetY: number
): {
  angleRad: number;
  angleDeg: number;
  dx: number;
  dy: number;
  dxPx: number;
  dyPx: number;
  lengthUnits: number;
  lengthPx: number;
} {
  const metrics = getSurvivorTestSceneMetrics();
  const dx = targetX - originX;
  const dy = targetY - originY;
  const dxPx = dx * metrics.width;
  const dyPx = dy * metrics.height;
  const angleRad = Math.atan2(dyPx, dxPx);
  const angleDeg = (angleRad * 180) / Math.PI;
  return {
    angleRad,
    angleDeg,
    dx,
    dy,
    dxPx,
    dyPx,
    lengthUnits: Math.hypot(dx, dy),
    lengthPx: Math.hypot(dxPx, dyPx)
  };
}

function getSurvivorShotGeometry(): {
  aimRadians: number;
  aimDegrees: number;
  aimDistance: number;
  aimLengthPx: number;
  weaponMountOffsetX: number;
  weaponMountOffsetY: number;
  muzzleOriginOffsetX: number;
  muzzleOriginOffsetY: number;
  muzzleX: number;
  muzzleY: number;
  muzzleAimDistance: number;
  muzzleAimLengthPx: number;
} {
  const actorAim = getSurvivorTestRayGeometry(
    survivorWalkState.x,
    survivorWalkState.y,
    survivorWalkState.pointerX,
    survivorWalkState.pointerY
  );
  const aimDistance = actorAim.lengthUnits;
  const aimRadians = actorAim.angleRad;
  const aimDegrees = actorAim.angleDeg;
  const aimLengthPx = Math.max(18, actorAim.lengthPx);
  const weaponMountForwardOffsetPx = 4;
  const weaponMountLateralOffsetPx = 7;
  const muzzleBaseOffsetPx = 42;
  const muzzleLateralOffsetPx = 7;
  const weaponMountOffsetX =
    Math.cos(aimRadians) * weaponMountForwardOffsetPx - Math.sin(aimRadians) * weaponMountLateralOffsetPx;
  const weaponMountOffsetY =
    Math.sin(aimRadians) * weaponMountForwardOffsetPx + Math.cos(aimRadians) * weaponMountLateralOffsetPx;
  const muzzleOriginOffsetX =
    Math.cos(aimRadians) * muzzleBaseOffsetPx - Math.sin(aimRadians) * muzzleLateralOffsetPx;
  const muzzleOriginOffsetY =
    Math.sin(aimRadians) * muzzleBaseOffsetPx + Math.cos(aimRadians) * muzzleLateralOffsetPx;
  const metrics = getSurvivorTestSceneMetrics();
  const muzzleX = survivorWalkState.x + muzzleOriginOffsetX / metrics.width;
  const muzzleY = survivorWalkState.y + muzzleOriginOffsetY / metrics.height;
  const muzzleAim = getSurvivorTestRayGeometry(muzzleX, muzzleY, survivorWalkState.pointerX, survivorWalkState.pointerY);
  const muzzleAimDistance = muzzleAim.lengthUnits;
  const muzzleAimLengthPx = Math.max(12, muzzleAim.lengthPx);
  return {
    aimRadians,
    aimDegrees,
    aimDistance,
    aimLengthPx,
    weaponMountOffsetX,
    weaponMountOffsetY,
    muzzleOriginOffsetX,
    muzzleOriginOffsetY,
    muzzleX,
    muzzleY,
    muzzleAimDistance,
    muzzleAimLengthPx
  };
}

function getSurvivorKnifeGeometry(): {
  aimRadians: number;
  aimDegrees: number;
  contactCenterX: number;
  contactCenterY: number;
  contactCenterOffsetX: number;
  contactCenterOffsetY: number;
  reachPx: number;
  arcHalfAngleRad: number;
  slashLengthPx: number;
  slashWidthPx: number;
} {
  const aim = getSurvivorTestRayGeometry(
    survivorWalkState.x,
    survivorWalkState.y,
    survivorWalkState.pointerX,
    survivorWalkState.pointerY
  );
  const contactForwardOffsetPx = 28;
  const contactLateralOffsetPx = 4;
  const reachPx = 42;
  const arcHalfAngleRad = Phaser.Math.DegToRad(44);
  const contactCenterOffsetX =
    Math.cos(aim.angleRad) * contactForwardOffsetPx - Math.sin(aim.angleRad) * contactLateralOffsetPx;
  const contactCenterOffsetY =
    Math.sin(aim.angleRad) * contactForwardOffsetPx + Math.cos(aim.angleRad) * contactLateralOffsetPx;
  const metrics = getSurvivorTestSceneMetrics();
  return {
    aimRadians: aim.angleRad,
    aimDegrees: aim.angleDeg,
    contactCenterX: survivorWalkState.x + contactCenterOffsetX / metrics.width,
    contactCenterY: survivorWalkState.y + contactCenterOffsetY / metrics.height,
    contactCenterOffsetX,
    contactCenterOffsetY,
    reachPx,
    arcHalfAngleRad,
    slashLengthPx: 52,
    slashWidthPx: 5
  };
}

function getSurvivorTestCameraDriftPx(nowMs: number): { x: number; y: number } {
  const activeShotEvent =
    survivorTestLastShotEvent !== null && survivorTestLastShotEvent.visualUntilMs > nowMs ? survivorTestLastShotEvent : null;
  const recoilProgress =
    activeShotEvent !== null
      ? Phaser.Math.Clamp(
          (activeShotEvent.recoilUntilMs - nowMs) / Math.max(1, activeShotEvent.recoilUntilMs - activeShotEvent.firedAtMs),
          0,
          1
        )
      : 0;
  const recoilSnap = recoilProgress > 0 ? Math.sin(recoilProgress * Math.PI) * 0.42 + recoilProgress * 0.58 : 0;
  const cameraPunchPx = activeShotEvent !== null ? activeShotEvent.cameraPunchPx * recoilSnap : 0;
  const cameraKickX = Math.cos(survivorWalkState.lookAngleRad + Math.PI) * cameraPunchPx;
  const cameraKickY = Math.sin(survivorWalkState.lookAngleRad + Math.PI) * cameraPunchPx;
  return {
    x: Phaser.Math.Clamp(
      (0.5 - survivorWalkState.x) * 120 + (0.5 - survivorWalkState.pointerScreenX) * 34 + cameraKickX,
      -46,
      46
    ),
    y: Phaser.Math.Clamp(
      (0.5 - survivorWalkState.y) * 120 + (0.5 - survivorWalkState.pointerScreenY) * 34 + cameraKickY,
      -38,
      38
    )
  };
}

function syncSurvivorTestPointerWorld(nowMs: number): void {
  const rect = survivorTestScene.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) {
    survivorWalkState.pointerX = survivorWalkState.pointerScreenX;
    survivorWalkState.pointerY = survivorWalkState.pointerScreenY;
    return;
  }
  const cameraDrift = getSurvivorTestCameraDriftPx(nowMs);
  survivorWalkState.pointerX = Phaser.Math.Clamp(
    survivorWalkState.pointerScreenX - cameraDrift.x / rect.width,
    0.04,
    0.96
  );
  survivorWalkState.pointerY = Phaser.Math.Clamp(
    survivorWalkState.pointerScreenY - cameraDrift.y / rect.height,
    0.05,
    0.95
  );
}

function allocateSurvivorImpact(shotEvent: SurvivorTestShotEvent): void {
  allocateSurvivorImpactAt(
    shotEvent.firedAtMs,
    shotEvent.travelUntilMs,
    shotEvent.impactPoint,
    shotEvent.impactKind,
    shotEvent.surfaceKind
  );
}

function allocateSurvivorImpactAt(
  firedAtMs: number,
  startAtMs: number,
  impactPoint: { x: number; y: number },
  impactKind: SurvivorTestShotImpactKind,
  surfaceKind: SurvivorTestShotSurfaceKind
): void {
  const impactState =
    survivorTestImpactStates.find((entry) => entry.untilMs <= firedAtMs) ??
    survivorTestImpactStates.reduce((oldest, entry) => (entry.untilMs < oldest.untilMs ? entry : oldest), survivorTestImpactStates[0]);
  impactState.x = impactPoint.x;
  impactState.y = impactPoint.y;
  impactState.kind = impactKind;
  impactState.surfaceKind = surfaceKind;
  impactState.startAtMs = startAtMs;
  impactState.untilMs =
    startAtMs +
    (impactKind === "target-down" ? 210 : impactKind === "target-hit" ? 150 : 120);
}

function applySurvivorTestStatePreset(stateId: SurvivorTestStateId): void {
  const preset = SURVIVOR_TEST_STATE_PRESETS[stateId];
  survivorWalkState.stateId = preset.id;
  survivorWalkState.x = preset.player.x;
  survivorWalkState.y = preset.player.y;
  survivorWalkState.pointerScreenX = preset.pointer.x;
  survivorWalkState.pointerScreenY = preset.pointer.y;
  survivorWalkState.pointerX = preset.pointer.x;
  survivorWalkState.pointerY = preset.pointer.y;
  for (const target of survivorTestTargetsState) {
    const targetPreset = preset.targets[target.id];
    if (!targetPreset) {
      continue;
    }
    target.baseX = targetPreset.x;
    target.baseY = targetPreset.y;
    target.x = targetPreset.x;
    target.y = targetPreset.y;
    target.behavior = targetPreset.behavior ?? "static";
    target.travelAmplitude = targetPreset.travelAmplitude ?? 0;
    target.cycleMs = targetPreset.cycleMs ?? 2200;
    target.popVisibleMs = targetPreset.popVisibleMs ?? 0;
    target.hiddenDepth = targetPreset.hiddenDepth ?? 0.08;
    target.phaseOffsetMs = targetPreset.phaseOffsetMs ?? 0;
    target.exposed = target.behavior !== "timed-pop";
    target.motionBlend = 0;
    target.hp = target.maxHp;
    target.phase = "idle";
    target.hitReactUntilMs = 0;
    target.downUntilMs = 0;
    target.respawnAtMs = 0;
  }
}

function resetSurvivorWalkDrillMetrics(nowMs: number): void {
  survivorWalkState.shotsFired = 0;
  survivorWalkState.shotsHit = 0;
  survivorWalkState.shotsMissed = 0;
  survivorWalkState.currentStreak = 0;
  survivorWalkState.drillStartedAtMs = nowMs;
  survivorWalkState.drillCompletedAtMs = 0;
  survivorWalkState.lastClearDurationMs = 0;
}

function clearSurvivorWalkTransientEffects(): void {
  survivorTestLastShotEvent = null;
  survivorTestLastKnifeEvent = null;
  survivorTestSuppressionPulseUntilMs = 0;
  for (const impactState of survivorTestImpactStates) {
    impactState.surfaceKind = "dirt";
    impactState.startAtMs = 0;
    impactState.untilMs = 0;
  }
}

function restartCurrentSurvivorTestDrill(nowMs: number): void {
  applySurvivorTestStatePreset(survivorWalkState.stateId);
  const currentWeaponPreset = getCurrentSurvivorTestWeaponPreset();
  survivorWalkState.magazineAmmo = currentWeaponPreset.magazineSize;
  survivorWalkState.reserveAmmo = currentWeaponPreset.reserveAmmo;
  survivorWalkState.reloadUntilMs = 0;
  survivorWalkState.dryFireUntilMs = 0;
  survivorWalkState.lastShotAtMs = 0;
  survivorWalkState.moving = false;
  survivorWalkState.bobPhase = 0;
  survivorWalkState.lookAngleRad = getSurvivorTestRayGeometry(
    survivorWalkState.x,
    survivorWalkState.y,
    survivorWalkState.pointerX,
    survivorWalkState.pointerY
  ).angleRad;
  resetSurvivorWalkDrillMetrics(nowMs);
  clearSurvivorWalkTransientEffects();
}

function maybeRecordSurvivorWalkDrillClear(nowMs: number): void {
  if (survivorWalkState.drillCompletedAtMs > 0) {
    return;
  }
  if (!survivorTestTargetsState.every((target) => target.phase === "down")) {
    return;
  }
  survivorWalkState.drillCompletedAtMs = nowMs;
  survivorWalkState.lastClearDurationMs = Math.max(0, nowMs - survivorWalkState.drillStartedAtMs);
  survivorWalkState.totalClears += 1;
  if (survivorWalkState.shotsMissed === 0) {
    survivorWalkState.cleanClears += 1;
  }
  if (
    survivorWalkState.bestClearDurationMs <= 0 ||
    survivorWalkState.lastClearDurationMs < survivorWalkState.bestClearDurationMs
  ) {
    survivorWalkState.bestClearDurationMs = survivorWalkState.lastClearDurationMs;
  }
}

function applySurvivorTestWeaponPreset(weaponId: "worn-ak" | "rifle" | "knife"): void {
  const preset = SURVIVOR_TEST_WEAPON_PRESETS[weaponId];
  survivorWalkState.weaponId = preset.weaponId;
  survivorWalkState.magazineAmmo = preset.magazineSize;
  survivorWalkState.reserveAmmo = preset.reserveAmmo;
  survivorWalkState.reloadUntilMs = 0;
  survivorWalkState.dryFireUntilMs = 0;
}

function setSurvivorTestWeaponPreset(weaponId: "worn-ak" | "rifle" | "knife"): void {
  applySurvivorTestWeaponPreset(weaponId);
  restartCurrentSurvivorTestDrill(performance.now());
  updateSurvivorWalkPresentation();
}

function setSurvivorTestStatePreset(stateId: SurvivorTestStateId): void {
  applySurvivorTestStatePreset(stateId);
  restartCurrentSurvivorTestDrill(performance.now());
  updateSurvivorWalkPresentation();
}

function isSurvivorTestTargetAvailable(target: SurvivorTestTargetState, nowMs: number): boolean {
  return (
    target.phase !== "down" &&
    target.phase !== "respawning" &&
    target.respawnAtMs <= nowMs &&
    target.exposed
  );
}

function applySurvivorTestTargetHit(
  target: SurvivorTestTargetState,
  nowMs: number
): Extract<SurvivorTestShotImpactKind, "target-hit" | "target-down"> {
  target.hitReactUntilMs = nowMs + 120;
  target.hp -= 1;
  if (target.hp <= 0) {
    target.hp = 0;
    target.phase = "down";
    target.downUntilMs = nowMs + 6000;
    target.respawnAtMs = target.downUntilMs;
    return "target-down";
  }
  target.phase = "hit";
  return "target-hit";
}

function stepSurvivorTestTargets(nowMs: number): number {
  let activeTargets = 0;
  const drillLocked = survivorWalkState.drillCompletedAtMs > 0;
  for (const target of survivorTestTargetsState) {
    const motionNowMs = nowMs + target.phaseOffsetMs;
    if (target.behavior === "sweep-horizontal") {
      const sweepWave = Math.sin((motionNowMs / Math.max(900, target.cycleMs)) * Math.PI * 2);
      target.x = target.baseX + sweepWave * target.travelAmplitude;
      target.y = target.baseY;
      target.exposed = true;
      target.motionBlend = Math.abs(sweepWave);
    } else if (target.behavior === "timed-pop") {
      const cycleMs = Math.max(800, target.cycleMs);
      const visibleMs = Math.min(cycleMs - 120, Math.max(260, target.popVisibleMs));
      const cycleProgressMs = ((motionNowMs % cycleMs) + cycleMs) % cycleMs;
      const visible = cycleProgressMs <= visibleMs;
      const riseWindowMs = Math.min(180, visibleMs * 0.35);
      const settleWindowMs = Math.min(170, visibleMs * 0.28);
      let exposure = 0;
      if (visible) {
        if (cycleProgressMs < riseWindowMs) {
          exposure = Phaser.Math.Easing.Cubic.Out(cycleProgressMs / Math.max(1, riseWindowMs));
        } else if (cycleProgressMs > visibleMs - settleWindowMs) {
          const collapseT = (cycleProgressMs - (visibleMs - settleWindowMs)) / Math.max(1, settleWindowMs);
          exposure = 1 - Phaser.Math.Easing.Cubic.In(collapseT);
        } else {
          exposure = 1;
        }
      }
      target.x = target.baseX;
      target.y = target.baseY + (1 - exposure) * target.hiddenDepth;
      target.exposed = visible && exposure > 0.18;
      target.motionBlend = exposure;
    } else {
      target.x = target.baseX;
      target.y = target.baseY;
      target.exposed = true;
      target.motionBlend = 0;
    }
    if (!drillLocked && target.phase === "down" && target.downUntilMs <= nowMs) {
      target.phase = "respawning";
      target.respawnAtMs = nowMs + 1;
    }
    if (target.phase === "respawning" && target.respawnAtMs <= nowMs) {
      target.hp = target.maxHp;
      target.phase = "idle";
      target.hitReactUntilMs = 0;
      target.downUntilMs = 0;
      target.respawnAtMs = 0;
      target.exposed = target.behavior !== "timed-pop";
    } else if (target.phase === "hit" && target.hitReactUntilMs <= nowMs) {
      target.phase = "idle";
    }
    if (isSurvivorTestTargetAvailable(target, nowMs)) {
      activeTargets += 1;
    }
  }
  return activeTargets;
}

function getSurvivorTestTargetRoleLabel(kind: SurvivorTestTargetKind): string {
  if (kind === "snap") {
    return "snap";
  }
  if (kind === "deep") {
    return "deep";
  }
  return "lane";
}

function getSurvivorTestBehaviorLabel(behavior: SurvivorTestTargetBehavior): string {
  if (behavior === "sweep-horizontal") {
    return "moving";
  }
  if (behavior === "timed-pop") {
    return "pop";
  }
  return "static";
}

function formatSurvivorTestDurationMs(durationMs: number): string {
  const seconds = Math.max(0, durationMs) / 1000;
  return `${seconds.toFixed(seconds >= 10 ? 1 : 2)}s`;
}

function getSurvivorTestResultGrade(
  weaponPreset: SurvivorTestWeaponPreset,
  statePreset: SurvivorTestStatePreset
): string {
  if (survivorWalkState.drillCompletedAtMs <= 0) {
    return "Live";
  }
  const adjustedParMs = statePreset.parTimeMs * weaponPreset.gradeTimeMultiplier;
  const adjustedCleanParMs = statePreset.cleanParTimeMs * weaponPreset.gradeTimeMultiplier;
  const misses = survivorWalkState.shotsMissed;
  const clearTimeMs = survivorWalkState.lastClearDurationMs;
  if (misses === 0 && clearTimeMs <= adjustedCleanParMs) {
    return "S Clean";
  }
  if (misses <= 1 && clearTimeMs <= adjustedParMs * 0.96) {
    return "A Sharp";
  }
  if (misses <= 2 && clearTimeMs <= adjustedParMs * 1.08) {
    return "B Stable";
  }
  if (misses <= 4 && clearTimeMs <= adjustedParMs * 1.28) {
    return "C Rough";
  }
  return "D Loose";
}

function resetSurvivorWalkState(): void {
  applySurvivorTestWeaponPreset("worn-ak");
  applySurvivorTestStatePreset("close-snap");
  survivorWalkState.lookAngleRad = getSurvivorTestRayGeometry(
    survivorWalkState.x,
    survivorWalkState.y,
    survivorWalkState.pointerX,
    survivorWalkState.pointerY
  ).angleRad;
  survivorWalkState.moving = false;
  survivorWalkState.bobPhase = 0;
  survivorWalkState.pace = "combat-walk";
  survivorWalkState.aiming = true;
  survivorWalkState.lastShotAtMs = 0;
  survivorWalkState.bestStreak = 0;
  survivorWalkState.bestClearDurationMs = 0;
  survivorWalkState.totalClears = 0;
  survivorWalkState.cleanClears = 0;
  resetSurvivorWalkDrillMetrics(performance.now());
  clearSurvivorWalkTransientEffects();
}

function getSurvivorTestTargetRadiusPx(kind: SurvivorTestTargetKind): number {
  if (kind === "snap") {
    return 16;
  }
  if (kind === "deep") {
    return 22;
  }
  return 19;
}

function getSurvivorTestTargetRayHit(
  target: SurvivorTestTargetState,
  originX: number,
  originY: number,
  targetX: number,
  targetY: number
): { distancePx: number; impactPoint: { x: number; y: number } } | null {
  const metrics = getSurvivorTestSceneMetrics();
  const ax = originX * metrics.width;
  const ay = originY * metrics.height;
  const bx = targetX * metrics.width;
  const by = targetY * metrics.height;
  const cx = target.x * metrics.width;
  const cy = target.y * metrics.height;
  const radiusPx = getSurvivorTestTargetRadiusPx(target.kind);
  const dx = bx - ax;
  const dy = by - ay;
  const fx = ax - cx;
  const fy = ay - cy;
  const a = dx * dx + dy * dy;
  if (a <= 0.000001) {
    return null;
  }
  const b = 2 * (fx * dx + fy * dy);
  const c = fx * fx + fy * fy - radiusPx * radiusPx;
  const discriminant = b * b - 4 * a * c;
  if (discriminant < 0) {
    return null;
  }
  const sqrtDiscriminant = Math.sqrt(discriminant);
  const tNear = (-b - sqrtDiscriminant) / (2 * a);
  const tFar = (-b + sqrtDiscriminant) / (2 * a);
  const t =
    tNear >= 0 && tNear <= 1
      ? tNear
      : tFar >= 0 && tFar <= 1
        ? tFar
        : null;
  if (t === null) {
    return null;
  }
  const impactXPx = ax + dx * t;
  const impactYPx = ay + dy * t;
  return {
    distancePx: Math.hypot(impactXPx - ax, impactYPx - ay),
    impactPoint: {
      x: impactXPx / metrics.width,
      y: impactYPx / metrics.height
    }
  };
}

function getSurvivorTestKnifeTargetHit(
  target: SurvivorTestTargetState,
  contactCenterX: number,
  contactCenterY: number,
  aimAngleRad: number,
  reachPx: number,
  arcHalfAngleRad: number
): { distancePx: number; impactPoint: { x: number; y: number } } | null {
  const metrics = getSurvivorTestSceneMetrics();
  const contactXPx = contactCenterX * metrics.width;
  const contactYPx = contactCenterY * metrics.height;
  const targetXPx = target.x * metrics.width;
  const targetYPx = target.y * metrics.height;
  const toTargetXPx = targetXPx - contactXPx;
  const toTargetYPx = targetYPx - contactYPx;
  const distancePx = Math.hypot(toTargetXPx, toTargetYPx);
  const targetRadiusPx = getSurvivorTestTargetRadiusPx(target.kind);
  if (distancePx > reachPx + targetRadiusPx) {
    return null;
  }
  const angleToTarget = Math.atan2(toTargetYPx, toTargetXPx);
  const angleDelta = Math.abs(Phaser.Math.Angle.Wrap(angleToTarget - aimAngleRad));
  if (angleDelta > arcHalfAngleRad) {
    return null;
  }
  const clampedDistancePx = Math.max(0, distancePx - targetRadiusPx * 0.6);
  const impactXPx = contactXPx + Math.cos(aimAngleRad) * clampedDistancePx;
  const impactYPx = contactYPx + Math.sin(aimAngleRad) * clampedDistancePx;
  return {
    distancePx,
    impactPoint: {
      x: impactXPx / metrics.width,
      y: impactYPx / metrics.height
    }
  };
}

function getSurvivorTestKnifeEventHit(
  target: SurvivorTestTargetState,
  event: SurvivorTestKnifeEvent
): { distancePx: number; impactPoint: { x: number; y: number } } | null {
  return getSurvivorTestKnifeTargetHit(
    target,
    event.contactCenter.x,
    event.contactCenter.y,
    event.aimAngleRad,
    event.reachPx,
    event.arcHalfAngleRad
  );
}

function getSurvivorKnifePreview(nowMs: number): {
  targetId: SurvivorTestTargetId | null;
  inRange: boolean;
  nearRange: boolean;
} {
  const geometry = getSurvivorKnifeGeometry();
  const metrics = getSurvivorTestSceneMetrics();
  let nearestDistancePx = Number.POSITIVE_INFINITY;
  let targetId: SurvivorTestTargetId | null = null;
  for (const target of survivorTestTargetsState) {
    if (!isSurvivorTestTargetAvailable(target, nowMs)) {
      continue;
    }
    const hit = getSurvivorTestKnifeTargetHit(
      target,
      geometry.contactCenterX,
      geometry.contactCenterY,
      geometry.aimRadians,
      geometry.reachPx,
      geometry.arcHalfAngleRad
    );
    const distancePx = Math.hypot(
      target.x * metrics.width - geometry.contactCenterX * metrics.width,
      target.y * metrics.height - geometry.contactCenterY * metrics.height
    );
    if (distancePx < nearestDistancePx) {
      nearestDistancePx = distancePx;
      targetId = target.id;
    }
    if (hit) {
      return {
        targetId: target.id,
        inRange: true,
        nearRange: false
      };
    }
  }
  return {
    targetId,
    inRange: false,
    nearRange: nearestDistancePx <= geometry.reachPx + 18
  };
}

function resolveSurvivorKnifeEvent(event: SurvivorTestKnifeEvent, nowMs: number): void {
  const metrics = getSurvivorTestSceneMetrics();
  if (event.resolvedAtMs > 0) {
    return;
  }

  let bestTarget: SurvivorTestTargetState | null = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  let bestHitPoint: { x: number; y: number } | null = null;

  for (const target of survivorTestTargetsState) {
    if (!isSurvivorTestTargetAvailable(target, nowMs)) {
      continue;
    }
    const hit = getSurvivorTestKnifeEventHit(target, event);
    if (hit && hit.distancePx < bestDistance) {
      bestTarget = target;
      bestDistance = hit.distancePx;
      bestHitPoint = hit.impactPoint;
    }
  }

  event.resolvedAtMs = nowMs;
  if (bestTarget) {
    survivorWalkState.shotsHit += 1;
    survivorWalkState.currentStreak += 1;
    survivorWalkState.bestStreak = Math.max(survivorWalkState.bestStreak, survivorWalkState.currentStreak);
    event.hitTargetId = bestTarget.id;
    event.impactPoint = bestHitPoint ?? { x: bestTarget.x, y: bestTarget.y };
    const impactKind = applySurvivorTestTargetHit(bestTarget, nowMs);
    event.result = impactKind;
    allocateSurvivorImpactAt(nowMs, nowMs, event.impactPoint, impactKind, "soft-body");
    maybeRecordSurvivorWalkDrillClear(nowMs);
    return;
  }

  survivorWalkState.shotsMissed += 1;
  survivorWalkState.currentStreak = 0;
  event.result = "miss";
  event.impactPoint = {
    x: event.contactCenter.x + (Math.cos(event.aimAngleRad) * event.reachPx) / metrics.width,
    y: event.contactCenter.y + (Math.sin(event.aimAngleRad) * event.reachPx) / metrics.height
  };
  allocateSurvivorImpactAt(
    nowMs,
    nowMs,
    event.impactPoint,
    "ground-hit",
    classifySurvivorTestSurfaceAt(event.impactPoint.x, event.impactPoint.y, false)
  );
}

function stepSurvivorKnifeEvent(nowMs: number): void {
  if (!survivorTestLastKnifeEvent) {
    return;
  }
  if (
    survivorTestLastKnifeEvent.resolvedAtMs <= 0 &&
    nowMs >= survivorTestLastKnifeEvent.windupUntilMs &&
    nowMs <= survivorTestLastKnifeEvent.activeUntilMs
  ) {
    resolveSurvivorKnifeEvent(survivorTestLastKnifeEvent, nowMs);
  }
  if (survivorTestLastKnifeEvent.resolvedAtMs <= 0 && nowMs > survivorTestLastKnifeEvent.activeUntilMs) {
    survivorWalkState.shotsMissed += 1;
    survivorWalkState.currentStreak = 0;
    survivorTestLastKnifeEvent.result = "miss";
    survivorTestLastKnifeEvent.resolvedAtMs = nowMs;
  }
  if (survivorTestLastKnifeEvent.resolvedAtMs > 0 && !survivorTestLastKnifeEvent.audioResolved) {
    playSurvivorTestKnifeResolveAudio(survivorTestLastKnifeEvent);
    survivorTestLastKnifeEvent.audioResolved = true;
  }
  if (survivorTestLastKnifeEvent.visualUntilMs <= nowMs) {
    survivorTestLastKnifeEvent = null;
  }
}

function fireSurvivorWalkShot(nowMs: number): void {
  if (survivorWalkState.reloadUntilMs > nowMs) {
    return;
  }
  if (survivorWalkState.weaponId !== "knife" && survivorWalkState.magazineAmmo <= 0) {
    if (nowMs - survivorWalkState.dryFireUntilMs > 120) {
      survivorWalkState.dryFireUntilMs = nowMs + 80;
      playSurvivorTestDryFireAudio();
    }
    return;
  }
  const previousShotAtMs = survivorWalkState.lastShotAtMs;
  if (nowMs - previousShotAtMs < getSurvivorTestRefireDelayMs(survivorWalkState.weaponId)) {
    return;
  }

  const geometry = getSurvivorShotGeometry();
  if (geometry.aimDistance <= 0.001) {
    return;
  }

  survivorWalkState.lastShotAtMs = nowMs;
  survivorWalkState.shotsFired += 1;
  if (survivorWalkState.weaponId === "knife") {
    const knifeGeometry = getSurvivorKnifeGeometry();
    survivorTestLastShotEvent = null;
    survivorTestLastKnifeEvent = {
      id: survivorTestNextShotEventId++,
      startedAtMs: nowMs,
      windupUntilMs: nowMs + 64,
      activeUntilMs: nowMs + 116,
      recoveryUntilMs: nowMs + 220,
      visualUntilMs: nowMs + 260,
      origin: { x: survivorWalkState.x, y: survivorWalkState.y },
      contactCenter: {
        x: knifeGeometry.contactCenterX,
        y: knifeGeometry.contactCenterY
      },
      aimAngleRad: knifeGeometry.aimRadians,
      reachPx: knifeGeometry.reachPx,
      arcHalfAngleRad: knifeGeometry.arcHalfAngleRad,
      slashLengthPx: knifeGeometry.slashLengthPx,
      slashWidthPx: knifeGeometry.slashWidthPx,
      result: "pending",
      hitTargetId: null,
      impactPoint: null,
      resolvedAtMs: 0,
      audioResolved: false
    };
    playSurvivorTestKnifeSwingAudio(survivorTestLastKnifeEvent);
    return;
  }
  survivorWalkState.magazineAmmo = Math.max(0, survivorWalkState.magazineAmmo - 1);

  const ax = geometry.muzzleX;
  const ay = geometry.muzzleY;
  const bx = survivorWalkState.pointerX;
  const by = survivorWalkState.pointerY;

  let bestTarget: SurvivorTestTargetState | null = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  let bestHitPoint: { x: number; y: number } | null = null;
  const shotRay = getSurvivorTestRayGeometry(ax, ay, bx, by);

  for (const target of survivorTestTargetsState) {
    if (!isSurvivorTestTargetAvailable(target, nowMs)) {
      continue;
    }
    const hit = getSurvivorTestTargetRayHit(target, ax, ay, bx, by);
    if (hit && hit.distancePx < bestDistance) {
      bestTarget = target;
      bestDistance = hit.distancePx;
      bestHitPoint = hit.impactPoint;
    }
  }

  let impactPoint = { x: bx, y: by };
  let impactKind: SurvivorTestShotImpactKind = "ground-hit";
  let hitTargetId: SurvivorTestTargetId | null = null;

  if (bestTarget) {
    survivorWalkState.shotsHit += 1;
    survivorWalkState.currentStreak += 1;
    survivorWalkState.bestStreak = Math.max(survivorWalkState.bestStreak, survivorWalkState.currentStreak);
    impactPoint = bestHitPoint ?? { x: bestTarget.x, y: bestTarget.y };
    hitTargetId = bestTarget.id;
    impactKind = applySurvivorTestTargetHit(bestTarget, nowMs);
    maybeRecordSurvivorWalkDrillClear(nowMs);
  } else {
    survivorWalkState.shotsMissed += 1;
    survivorWalkState.currentStreak = 0;
  }

  const shotProfile = getSurvivorTestShotProfile(survivorWalkState.weaponId);
  const surfaceKind = classifySurvivorTestSurfaceAt(impactPoint.x, impactPoint.y, bestTarget !== null);
  const shotCadenceMs = previousShotAtMs > 0 ? nowMs - previousShotAtMs : 999;
  const cadencePenaltyRatio = Phaser.Math.Clamp((260 - Math.min(260, shotCadenceMs)) / 260, 0, 1);
  const paceRecoilMultiplier =
    survivorWalkState.pace === "steady" ? 0.64 : survivorWalkState.pace === "sprint" ? 1.28 : 1;
  const recoilKickPx =
    (shotProfile.recoilKickPx + shotProfile.cadencePenaltyPx * cadencePenaltyRatio) * paceRecoilMultiplier;
  const weaponKickPx =
    (shotProfile.weaponKickPx + shotProfile.cadencePenaltyPx * cadencePenaltyRatio * 1.18) * paceRecoilMultiplier;
  const cameraPunchPx =
    (shotProfile.cameraPunchPx + shotProfile.cadencePenaltyPx * cadencePenaltyRatio * 0.86) *
    (survivorWalkState.pace === "steady" ? 0.72 : survivorWalkState.pace === "sprint" ? 1.12 : 1);
  const shotDistancePx = Math.max(12, getSurvivorTestRayGeometry(ax, ay, impactPoint.x, impactPoint.y).lengthPx);
  const travelDurationMs = Phaser.Math.Clamp(shotDistancePx / shotProfile.projectileSpeedPxPerMs, 10, 90);
  const shotEvent: SurvivorTestShotEvent = {
    id: survivorTestNextShotEventId++,
    shooterId: "player",
    weaponId: shotProfile.weaponId,
    firedAtMs: nowMs,
    visualUntilMs: nowMs + travelDurationMs + 70,
    muzzleFlashUntilMs: nowMs + 54,
    nearStreakUntilMs: nowMs + 48,
    recoilUntilMs: nowMs + shotProfile.recoilDurationMs,
    travelUntilMs: nowMs + travelDurationMs,
    origin: { x: survivorWalkState.x, y: survivorWalkState.y },
    muzzle: {
      x: geometry.muzzleX,
      y: geometry.muzzleY
    },
    target: { x: bx, y: by },
    impactPoint,
    aimAngleRad: geometry.aimRadians,
    projectileSpeed: shotProfile.projectileSpeedPxPerMs,
    suppressionClass: "rifle",
    profileId: shotProfile.id,
    tracerLengthPx: Math.max(shotProfile.tracerLengthMinPx, shotRay.lengthPx * shotProfile.tracerLengthScale),
    tracerWidthPx: shotProfile.tracerWidthPx,
    nearStreakLengthPx: shotProfile.nearStreakLengthPx,
    nearStreakWidthPx: shotProfile.nearStreakWidthPx,
    projectileHeadSizePx: shotProfile.projectileHeadSizePx,
    tracerCore: shotProfile.tracerCore,
    tracerFade: shotProfile.tracerFade,
    tracerGlow: shotProfile.tracerGlow,
    projectileHeadGlow: shotProfile.projectileHeadGlow,
    muzzleFlashScale: shotProfile.muzzleFlashScale,
    baseRecoilKickPx: shotProfile.recoilKickPx,
    weaponKickPx,
    cameraPunchPx,
    recoilDurationMs: shotProfile.recoilDurationMs,
    cadencePenaltyPx: shotProfile.cadencePenaltyPx,
    recoilKickPx,
    hit: bestTarget !== null,
    impactKind,
    surfaceKind,
    hitTargetId,
    muzzleSmokeUntilMs: nowMs + shotProfile.muzzleSmokeDurationMs,
    nearHitSuppressionUntilMs:
      !bestTarget && Math.hypot(impactPoint.x - ax, impactPoint.y - ay) <= 0.18 ? nowMs + 150 : 0
  };

  survivorTestLastShotEvent = shotEvent;
  survivorTestSuppressionPulseUntilMs = Math.max(survivorTestSuppressionPulseUntilMs, shotEvent.nearHitSuppressionUntilMs);
  allocateSurvivorImpact(shotEvent);
  playSurvivorTestShotAudio(shotEvent);
}

function startSurvivorWalkReload(nowMs: number): void {
  if (survivorWalkState.weaponId === "knife") {
    return;
  }
  const preset = getCurrentSurvivorTestWeaponPreset();
  if (
    survivorWalkState.reloadUntilMs > nowMs ||
    survivorWalkState.magazineAmmo >= preset.magazineSize ||
    survivorWalkState.reserveAmmo <= 0
  ) {
    return;
  }
  const profile = getSurvivorTestShotProfile(survivorWalkState.weaponId);
  survivorWalkState.reloadUntilMs = nowMs + profile.reloadDurationMs;
  playSurvivorTestReloadAudio();
}

function getSpritePaintImages(setId: SpritePaintAnimationSet): HTMLImageElement[] {
  return setId === "move" ? survivorMoveRifleImages : survivorIdleRifleImages;
}

function getCurrentSpritePaintImages(): HTMLImageElement[] {
  return getSpritePaintImages(spritePaintState.animationSet);
}

function getCurrentSpritePaintImage(): HTMLImageElement | null {
  const images = getCurrentSpritePaintImages();
  if (images.length === 0) {
    return null;
  }
  return images[Math.max(0, Math.min(images.length - 1, spritePaintState.frameIndex))] ?? null;
}

function getSpritePaintLayerCanvas(layerId: SpritePaintCanvasLayerId): HTMLCanvasElement | null {
  return layerId === "clone"
    ? spritePaintState.cloneLayerCanvas
    : layerId === "armband"
      ? spritePaintState.armbandLayerCanvas
      : spritePaintState.markingsLayerCanvas;
}

function getSpritePaintFrameLocalLayerCanvas(
  setId: SpritePaintAnimationSet,
  frameIndex: number,
  layerId: SpritePaintCanvasLayerId,
  createIfMissing = false
): HTMLCanvasElement | null {
  const setMap = spritePaintState.frameLocalLayerCanvases[setId];
  let bundle = setMap.get(frameIndex);
  if (!bundle && createIfMissing) {
    bundle = {};
    setMap.set(frameIndex, bundle);
  }
  const existing = bundle?.[layerId] ?? null;
  if (existing || !createIfMissing || !ensureSpritePaintBuffers()) {
    return existing;
  }
  const canvas = document.createElement("canvas");
  canvas.width = spritePaintState.frameWidth;
  canvas.height = spritePaintState.frameHeight;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.imageSmoothingEnabled = false;
  }
  bundle![layerId] = canvas;
  return canvas;
}

function getCurrentSpritePaintTargetLayerCanvas(createIfMissing = false): HTMLCanvasElement | null {
  const layerId = spritePaintState.project.layers[spritePaintState.project.activeLayerId].canvasLayerId;
  if (spritePaintState.editMode === "frame-local") {
    return getSpritePaintFrameLocalLayerCanvas(
      spritePaintState.animationSet,
      spritePaintState.frameIndex,
      layerId,
      createIfMissing
    );
  }
  return getSpritePaintLayerCanvas(layerId);
}

function syncSpritePaintProjectState(): void {
  const colorLabel = getSpritePaintColorLabel(spritePaintState.selectedColor);
  spritePaintState.project.focusedAnimationSet = spritePaintState.animationSet;
  spritePaintState.project.activeLayerId = getSpritePaintLayerIdForTool(spritePaintState.tool);
  spritePaintState.project.editMode = spritePaintState.editMode;
  spritePaintState.project.label = `Enemy Variant ${colorLabel.toUpperCase()}`;
  spritePaintState.project.id = `enemy-variant-${colorLabel}-${spritePaintState.project.createdAt.replace(/[:.]/g, "-")}`;
  spritePaintState.project.metadata.armbandColor = spritePaintState.selectedColor;
  spritePaintState.project.metadata.teamRead = `${colorLabel} armband`;
  spritePaintState.project.updatedAt = new Date().toISOString();
}

function getSpritePaintProjectDescriptor() {
  syncSpritePaintProjectState();
  return {
    id: spritePaintState.project.id,
    label: spritePaintState.project.label,
    baseAnimationSourceId: spritePaintState.project.baseAnimationSourceId,
    focusedAnimationSet: spritePaintState.project.focusedAnimationSet,
    activeLayerId: spritePaintState.project.activeLayerId,
    createdAt: spritePaintState.project.createdAt,
    updatedAt: spritePaintState.project.updatedAt,
    metadata: spritePaintState.project.metadata,
    layers: Object.values(spritePaintState.project.layers).map((layer) => ({
      id: layer.id,
      label: layer.label,
      canvasLayerId: layer.canvasLayerId,
      enabled: layer.enabled,
      frameOverrideCounts: {
        idle:
          layer.frameOverrides.idle?.length ??
          Array.from(spritePaintState.frameLocalLayerCanvases.idle.entries()).filter(([, bundle]) => Boolean(bundle[layer.canvasLayerId])).length,
        move:
          layer.frameOverrides.move?.length ??
          Array.from(spritePaintState.frameLocalLayerCanvases.move.entries()).filter(([, bundle]) => Boolean(bundle[layer.canvasLayerId])).length
      }
    }))
  };
}

function ensureSpritePaintBuffers(): boolean {
  const firstImage = survivorIdleRifleImages[0] ?? survivorMoveRifleImages[0] ?? null;
  if (!firstImage || !firstImage.complete || firstImage.naturalWidth <= 0 || firstImage.naturalHeight <= 0) {
    return false;
  }
  if (
    spritePaintState.buffersReady &&
    spritePaintState.frameWidth === firstImage.naturalWidth &&
    spritePaintState.frameHeight === firstImage.naturalHeight &&
    spritePaintState.cloneLayerCanvas &&
    spritePaintState.armbandLayerCanvas &&
    spritePaintState.markingsLayerCanvas
  ) {
    return true;
  }
  spritePaintState.frameWidth = firstImage.naturalWidth;
  spritePaintState.frameHeight = firstImage.naturalHeight;
  spritePaintState.cloneLayerCanvas = document.createElement("canvas");
  spritePaintState.cloneLayerCanvas.width = firstImage.naturalWidth;
  spritePaintState.cloneLayerCanvas.height = firstImage.naturalHeight;
  spritePaintState.armbandLayerCanvas = document.createElement("canvas");
  spritePaintState.armbandLayerCanvas.width = firstImage.naturalWidth;
  spritePaintState.armbandLayerCanvas.height = firstImage.naturalHeight;
  spritePaintState.markingsLayerCanvas = document.createElement("canvas");
  spritePaintState.markingsLayerCanvas.width = firstImage.naturalWidth;
  spritePaintState.markingsLayerCanvas.height = firstImage.naturalHeight;
  const cloneCtx = spritePaintState.cloneLayerCanvas.getContext("2d");
  const armbandCtx = spritePaintState.armbandLayerCanvas.getContext("2d");
  const markingsCtx = spritePaintState.markingsLayerCanvas.getContext("2d");
  if (cloneCtx) {
    cloneCtx.imageSmoothingEnabled = false;
  }
  if (armbandCtx) {
    armbandCtx.imageSmoothingEnabled = false;
  }
  if (markingsCtx) {
    markingsCtx.imageSmoothingEnabled = false;
  }
  spritePaintState.buffersReady = true;
  spritePaintState.cloneSampleX = Math.round(firstImage.naturalWidth * 0.58);
  spritePaintState.cloneSampleY = Math.round(firstImage.naturalHeight * 0.52);
  return true;
}

function clearSpritePaintLayer(layer: SpritePaintCanvasLayerId): void {
  if (!ensureSpritePaintBuffers()) {
    return;
  }
  const canvas =
    spritePaintState.editMode === "frame-local"
      ? getSpritePaintFrameLocalLayerCanvas(spritePaintState.animationSet, spritePaintState.frameIndex, layer)
      : getSpritePaintLayerCanvas(layer);
  const ctx = canvas?.getContext("2d");
  if (!ctx || !canvas) {
    return;
  }
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

function getSpritePaintLocalSnapshot(
  setId: SpritePaintAnimationSet,
  frameIndex: number,
  layerId: SpritePaintCanvasLayerId
): ImageData | null {
  const canvas = getSpritePaintFrameLocalLayerCanvas(setId, frameIndex, layerId);
  const ctx = canvas?.getContext("2d");
  if (!ctx || !canvas) {
    return null;
  }
  return ctx.getImageData(0, 0, canvas.width, canvas.height);
}

function pushSpritePaintUndoSnapshot(): void {
  if (
    !ensureSpritePaintBuffers() ||
    !spritePaintState.cloneLayerCanvas ||
    !spritePaintState.armbandLayerCanvas ||
    !spritePaintState.markingsLayerCanvas
  ) {
    return;
  }
  const cloneCtx = spritePaintState.cloneLayerCanvas.getContext("2d");
  const armbandCtx = spritePaintState.armbandLayerCanvas.getContext("2d");
  const markingsCtx = spritePaintState.markingsLayerCanvas.getContext("2d");
  if (!cloneCtx || !armbandCtx || !markingsCtx) {
    return;
  }
  spritePaintState.undoStack.push({
    cloneLayer: cloneCtx.getImageData(
      0,
      0,
      spritePaintState.cloneLayerCanvas.width,
      spritePaintState.cloneLayerCanvas.height
    ),
    armbandLayer: armbandCtx.getImageData(
      0,
      0,
      spritePaintState.armbandLayerCanvas.width,
      spritePaintState.armbandLayerCanvas.height
    ),
    markingsLayer: markingsCtx.getImageData(
      0,
      0,
      spritePaintState.markingsLayerCanvas.width,
      spritePaintState.markingsLayerCanvas.height
    ),
    localCloneLayer: getSpritePaintLocalSnapshot(spritePaintState.animationSet, spritePaintState.frameIndex, "clone"),
    localArmbandLayer: getSpritePaintLocalSnapshot(spritePaintState.animationSet, spritePaintState.frameIndex, "armband"),
    localMarkingsLayer: getSpritePaintLocalSnapshot(spritePaintState.animationSet, spritePaintState.frameIndex, "markings")
  });
  if (spritePaintState.undoStack.length > SPRITE_PAINT_UNDO_LIMIT) {
    spritePaintState.undoStack.splice(0, spritePaintState.undoStack.length - SPRITE_PAINT_UNDO_LIMIT);
  }
}

function undoSpritePaintStep(): void {
  if (
    !ensureSpritePaintBuffers() ||
    !spritePaintState.cloneLayerCanvas ||
    !spritePaintState.armbandLayerCanvas ||
    !spritePaintState.markingsLayerCanvas
  ) {
    return;
  }
  const snapshot = spritePaintState.undoStack.pop();
  if (!snapshot) {
    return;
  }
  const cloneCtx = spritePaintState.cloneLayerCanvas.getContext("2d");
  const armbandCtx = spritePaintState.armbandLayerCanvas.getContext("2d");
  const markingsCtx = spritePaintState.markingsLayerCanvas.getContext("2d");
  if (!cloneCtx || !armbandCtx || !markingsCtx) {
    return;
  }
  cloneCtx.putImageData(snapshot.cloneLayer, 0, 0);
  armbandCtx.putImageData(snapshot.armbandLayer, 0, 0);
  markingsCtx.putImageData(snapshot.markingsLayer, 0, 0);
  const localLayers: Array<[SpritePaintCanvasLayerId, ImageData | null]> = [
    ["clone", snapshot.localCloneLayer],
    ["armband", snapshot.localArmbandLayer],
    ["markings", snapshot.localMarkingsLayer]
  ];
  for (const [layerId, imageData] of localLayers) {
    const localCanvas = getSpritePaintFrameLocalLayerCanvas(
      spritePaintState.animationSet,
      spritePaintState.frameIndex,
      layerId,
      imageData !== null
    );
    const localCtx = localCanvas?.getContext("2d");
    if (!localCtx || !localCanvas) {
      continue;
    }
    localCtx.clearRect(0, 0, localCanvas.width, localCanvas.height);
    if (imageData) {
      localCtx.putImageData(imageData, 0, 0);
    }
  }
}

function getSpritePaintCanvasPoint(event: PointerEvent): { x: number; y: number } | null {
  const rect = spritePaintCanvas.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0 || !ensureSpritePaintBuffers()) {
    return null;
  }
  return {
    x: Phaser.Math.Clamp(
      Math.round(((event.clientX - rect.left) / rect.width) * spritePaintState.frameWidth),
      0,
      Math.max(0, spritePaintState.frameWidth - 1)
    ),
    y: Phaser.Math.Clamp(
      Math.round(((event.clientY - rect.top) / rect.height) * spritePaintState.frameHeight),
      0,
      Math.max(0, spritePaintState.frameHeight - 1)
    )
  };
}

function drawSpritePaintComposite(
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  width: number,
  height: number,
  options: {
    showGuide: boolean;
    transparentBackground?: boolean;
    animationSet?: SpritePaintAnimationSet;
    frameIndex?: number;
  }
): void {
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, width, height);
  if (!options.transparentBackground) {
    ctx.fillStyle = "#0b1118";
    ctx.fillRect(0, 0, width, height);
  }
  ctx.drawImage(image, 0, 0, width, height);
  if (spritePaintState.cloneLayerCanvas) {
    ctx.drawImage(spritePaintState.cloneLayerCanvas, 0, 0, width, height);
  }
  if (spritePaintState.armbandLayerCanvas) {
    ctx.drawImage(spritePaintState.armbandLayerCanvas, 0, 0, width, height);
  }
  if (spritePaintState.markingsLayerCanvas) {
    ctx.drawImage(spritePaintState.markingsLayerCanvas, 0, 0, width, height);
  }
  const setId = options.animationSet ?? spritePaintState.animationSet;
  const frameIndex = options.frameIndex ?? spritePaintState.frameIndex;
  const localClone = getSpritePaintFrameLocalLayerCanvas(setId, frameIndex, "clone");
  const localArmband = getSpritePaintFrameLocalLayerCanvas(setId, frameIndex, "armband");
  const localMarkings = getSpritePaintFrameLocalLayerCanvas(setId, frameIndex, "markings");
  if (localClone) {
    ctx.drawImage(localClone, 0, 0, width, height);
  }
  if (localArmband) {
    ctx.drawImage(localArmband, 0, 0, width, height);
  }
  if (localMarkings) {
    ctx.drawImage(localMarkings, 0, 0, width, height);
  }
  if (options.showGuide) {
    ctx.strokeStyle = "rgba(125, 211, 252, 0.82)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(
      spritePaintState.cloneSampleX,
      spritePaintState.cloneSampleY,
      Math.max(3, spritePaintState.brushRadiusPx * 0.5),
      0,
      Math.PI * 2
    );
    ctx.stroke();
    if (spritePaintState.hovering) {
      ctx.strokeStyle =
        spritePaintState.tool === "armband"
          ? spritePaintState.selectedColor
          : spritePaintState.tool === "erase"
            ? "rgba(248, 113, 113, 0.92)"
            : "rgba(255, 255, 255, 0.84)";
      ctx.beginPath();
      ctx.arc(spritePaintState.pointerX, spritePaintState.pointerY, spritePaintState.brushRadiusPx, 0, Math.PI * 2);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawSpritePaintCompositeWithoutGuides(
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  width: number,
  height: number,
  animationSet?: SpritePaintAnimationSet,
  frameIndex?: number
): void {
  drawSpritePaintComposite(ctx, image, width, height, {
    showGuide: false,
    transparentBackground: true,
    animationSet,
    frameIndex
  });
}

function getSpritePaintExportBaseName(): string {
  syncSpritePaintProjectState();
  return spritePaintState.project.id;
}

function downloadSpritePaintFile(filename: string, href: string): void {
  const link = document.createElement("a");
  link.href = href;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

function buildSpritePaintSheetCanvas(setId: SpritePaintAnimationSet): HTMLCanvasElement | null {
  const images = getSpritePaintImages(setId);
  if (!ensureSpritePaintBuffers() || images.length === 0) {
    return null;
  }
  const frameWidth = spritePaintState.frameWidth;
  const frameHeight = spritePaintState.frameHeight;
  if (frameWidth <= 0 || frameHeight <= 0) {
    return null;
  }
  const sheet = document.createElement("canvas");
  sheet.width = frameWidth * images.length;
  sheet.height = frameHeight;
  const ctx = sheet.getContext("2d");
  if (!ctx) {
    return null;
  }
  ctx.imageSmoothingEnabled = false;
  for (let index = 0; index < images.length; index += 1) {
    const image = images[index];
    if (!image || !image.complete || image.naturalWidth <= 0) {
      continue;
    }
    ctx.save();
    ctx.translate(index * frameWidth, 0);
    drawSpritePaintCompositeWithoutGuides(ctx, image, frameWidth, frameHeight, setId, index);
    ctx.restore();
  }
  return sheet;
}

function exportSpritePaintVariant(): void {
  const idleSheet = buildSpritePaintSheetCanvas("idle");
  const moveSheet = buildSpritePaintSheetCanvas("move");
  if (!idleSheet || !moveSheet) {
    return;
  }
  const baseName = getSpritePaintExportBaseName();
  const idleName = `${baseName}-idle.png`;
  const moveName = `${baseName}-move.png`;
  const manifestName = `${baseName}.json`;
  const manifest = {
    ...getSpritePaintProjectDescriptor(),
    exportedAt: new Date().toISOString(),
    source: "sprite-paint-lab",
    frameWidth: spritePaintState.frameWidth,
    frameHeight: spritePaintState.frameHeight,
    fps: spritePaintState.fps,
    sheets: {
      idle: {
        file: idleName,
        frames: survivorIdleRifleImages.length
      },
      move: {
        file: moveName,
        frames: survivorMoveRifleImages.length
      }
    }
  };
  downloadSpritePaintFile(idleName, idleSheet.toDataURL("image/png"));
  downloadSpritePaintFile(moveName, moveSheet.toDataURL("image/png"));
  const manifestUrl = URL.createObjectURL(
    new Blob([JSON.stringify(manifest, null, 2)], { type: "application/json" })
  );
  downloadSpritePaintFile(manifestName, manifestUrl);
  window.setTimeout(() => URL.revokeObjectURL(manifestUrl), 1000);
}

function stampSpritePaintClone(
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  x: number,
  y: number
): void {
  const radius = spritePaintState.brushRadiusPx;
  const sampleX = Phaser.Math.Clamp(x + spritePaintState.cloneOffsetX, 0, image.naturalWidth - 1);
  const sampleY = Phaser.Math.Clamp(y + spritePaintState.cloneOffsetY, 0, image.naturalHeight - 1);
  const size = radius * 2;
  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.clip();
  ctx.globalAlpha = 0.96;
  ctx.drawImage(
    image,
    Math.max(0, sampleX - radius),
    Math.max(0, sampleY - radius),
    Math.min(size, image.naturalWidth),
    Math.min(size, image.naturalHeight),
    x - radius,
    y - radius,
    size,
    size
  );
  ctx.restore();
}

function stampSpritePaintArmband(ctx: CanvasRenderingContext2D, x: number, y: number): void {
  ctx.save();
  ctx.fillStyle = spritePaintState.selectedColor;
  ctx.globalAlpha = 0.86;
  ctx.beginPath();
  ctx.arc(x, y, spritePaintState.brushRadiusPx, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function stampSpritePaintErase(ctx: CanvasRenderingContext2D, x: number, y: number): void {
  ctx.save();
  ctx.globalCompositeOperation = "destination-out";
  ctx.beginPath();
  ctx.arc(x, y, spritePaintState.brushRadiusPx + 1, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function paintSpriteStroke(fromX: number, fromY: number, toX: number, toY: number): void {
  if (!ensureSpritePaintBuffers()) {
    return;
  }
  const image = getCurrentSpritePaintImage();
  const targetCanvas = getCurrentSpritePaintTargetLayerCanvas(true);
  const targetCtx = targetCanvas?.getContext("2d");
  if (!image || !targetCtx) {
    return;
  }
  const distance = Math.hypot(toX - fromX, toY - fromY);
  const stepCount = Math.max(1, Math.ceil(distance / Math.max(1.5, spritePaintState.brushRadiusPx * 0.35)));
  for (let index = 0; index <= stepCount; index += 1) {
    const t = index / stepCount;
    const x = Phaser.Math.Linear(fromX, toX, t);
    const y = Phaser.Math.Linear(fromY, toY, t);
    if (spritePaintState.tool === "clone") {
      stampSpritePaintClone(targetCtx, image, x, y);
    } else if (spritePaintState.tool === "armband" || spritePaintState.project.activeLayerId === "markings") {
      stampSpritePaintArmband(targetCtx, x, y);
    } else {
      stampSpritePaintErase(targetCtx, x, y);
    }
  }
  const activeLayer = spritePaintState.project.layers[spritePaintState.project.activeLayerId];
  if (spritePaintState.editMode === "frame-local") {
    const frameOverrides = activeLayer.frameOverrides[spritePaintState.animationSet] ?? [];
    if (!frameOverrides.includes(spritePaintState.frameIndex)) {
      activeLayer.frameOverrides[spritePaintState.animationSet] = [...frameOverrides, spritePaintState.frameIndex].sort((a, b) => a - b);
    }
  }
  syncSpritePaintProjectState();
}

function renderSpritePaintLab(nowMs: number): void {
  const currentImages = getCurrentSpritePaintImages();
  const currentImage = getCurrentSpritePaintImage();
  if (!ensureSpritePaintBuffers() || !currentImage || !currentImage.complete || currentImage.naturalWidth <= 0) {
    setTextIfChanged(spritePaintStatus, "Loading frames");
    return;
  }
  if (spritePaintState.playing && nowMs - spritePaintState.lastPreviewStepMs >= 1000 / spritePaintState.fps) {
    spritePaintState.previewFrameIndex =
      (spritePaintState.previewFrameIndex + 1) % Math.max(1, currentImages.length);
    spritePaintState.lastPreviewStepMs = nowMs;
  }
  const previewImage =
    currentImages[Math.max(0, Math.min(currentImages.length - 1, spritePaintState.previewFrameIndex))] ?? currentImage;
  const paintCtx = spritePaintCanvas.getContext("2d");
  const previewCtx = spritePaintPreviewCanvas.getContext("2d");
  if (!paintCtx || !previewCtx) {
    return;
  }
  drawSpritePaintComposite(
    paintCtx,
    currentImage,
    spritePaintCanvas.width,
    spritePaintCanvas.height,
    { showGuide: true, animationSet: spritePaintState.animationSet, frameIndex: spritePaintState.frameIndex }
  );
  drawSpritePaintComposite(
    previewCtx,
    previewImage,
    spritePaintPreviewCanvas.width,
    spritePaintPreviewCanvas.height,
    { showGuide: false, animationSet: spritePaintState.animationSet, frameIndex: spritePaintState.previewFrameIndex }
  );
  setTextIfChanged(
    spritePaintStatus,
    spritePaintState.tool === "clone"
      ? "Clone texture live"
      : spritePaintState.tool === "armband"
        ? "Armband paint live"
        : "Erase live"
  );
  setTextIfChanged(spritePaintSample, `${spritePaintState.cloneSampleX}, ${spritePaintState.cloneSampleY}`);
  setTextIfChanged(
    spritePaintFrameRead,
    `${spritePaintState.frameIndex + 1} / ${Math.max(1, currentImages.length)}`
  );
  setTextIfChanged(
    spritePaintLayerRead,
    spritePaintState.project.layers[spritePaintState.project.activeLayerId].label
  );
  setTextIfChanged(
    spritePaintModeRead,
    spritePaintState.editMode === "frame-local" ? "Frame Local" : "Shared"
  );
  setTextIfChanged(spritePaintBrushRead, `${spritePaintState.brushRadiusPx} px`);
  setTextIfChanged(
    spritePaintUndoRead,
    spritePaintState.undoStack.length === 1 ? "1 step" : `${spritePaintState.undoStack.length} steps`
  );
  setTextIfChanged(
    spritePaintReadout,
    `${spritePaintState.project.label} | ${spritePaintState.project.metadata.teamRead} | layer ${spritePaintState.project.layers[spritePaintState.project.activeLayerId].label}. ${
      spritePaintState.animationSet === "move" ? "Move" : "Idle"
    } set active on source ${spritePaintState.project.baseAnimationSourceId}. ${
      spritePaintState.tool === "clone"
        ? "Clone steals texture from the current base sprite without touching the default frame."
        : spritePaintState.tool === "armband"
          ? "Armband paint rides on a separate color layer so enemy/unit marking experiments stay reversible."
          : "Erase cuts back to the untouched default by clearing only the overlay layers."
    } ${
      spritePaintState.editMode === "frame-local"
        ? "Paint Each Frame is on, so every frame gets its own clean paint pass. Step forward and paint the next stripe without erasing the last one."
        : "Shared mode is on, so the stripe carries across the whole animation set."
    } Save Variant exports reusable idle/move sheets plus a manifest for later enemy use.`
  );
  for (const button of spritePaintSetButtons) {
    button.classList.toggle("survivor-test-toolbar-button-active", button.dataset.spritePaintSet === spritePaintState.animationSet);
  }
  for (const button of spritePaintToolButtons) {
    button.classList.toggle("survivor-test-toolbar-button-active", button.dataset.spritePaintTool === spritePaintState.tool);
  }
  for (const button of spritePaintColorButtons) {
    button.classList.toggle("sprite-paint-lab-swatch-active", button.dataset.spritePaintColor === spritePaintState.selectedColor);
  }
  spritePaintFrameLocalToggle.checked = spritePaintState.editMode === "frame-local";
  spritePaintPlayToggle.classList.toggle("survivor-test-toolbar-button-active", !spritePaintState.playing);
  spritePaintUndoButton.classList.toggle("survivor-test-toolbar-button-active", spritePaintState.undoStack.length > 0);
  setTextIfChanged(spritePaintPlayToggle, spritePaintState.playing ? "Pause" : "Play");
}

interface StashDragState {
  kind: StashDragKind;
  source: StashDragSource;
  tileId: string;
  weaponId?: WeaponId;
  resource?: PrepResource;
  equipmentSlotId?: EquipmentSlotId;
  storageSurfaceId?: StorageSurfaceId;
}

interface RackHoverState {
  tileId: string;
  columnStart: number;
  rowStart: number;
  rotated: boolean;
  valid: boolean;
  action: "move" | "swap" | "invalid";
  displacedTileId?: string;
}

type StashDropTarget =
  | {
      kind: "bench";
      element: HTMLElement;
    }
  | {
      kind: "rack-return";
      element: HTMLElement;
    }
  | {
      kind: "rack-cell";
      element: HTMLElement;
      cell: HTMLElement;
      columnStart: number;
      rowStart: number;
    }
  | {
      kind: "prep";
      element: HTMLElement;
      resource: PrepResource;
    }
  | {
      kind: "paperdoll";
      element: HTMLElement;
      slotId: PaperdollSlotId;
    }
  | {
      kind: "equipment";
      element: HTMLElement;
      slotId: EquipmentSlotId;
    }
  | {
      kind: "storage";
      element: HTMLElement;
      surfaceId: StorageSurfaceId;
      columnStart: number;
      rowStart: number;
    }
  | {
      kind: "quick-slot";
      element: HTMLElement;
      slotId: QuickSlotId;
    };

const stashDragState = {
  payload: null as StashDragState | null
};

const manualDragState = {
  payload: null as StashDragState | null,
  pointerId: null as number | null,
  startX: 0,
  startY: 0,
  active: false,
  suppressClick: false
};

const stashUiState = {
  selectedTileId: null as string | null,
  contextTileId: null as string | null,
  contextX: 0,
  contextY: 0,
  activeTopTab: "gear" as TopTabId,
  activeGearWorkbenchTab: "loadout" as GearWorkbenchTabId,
  activeCommandTab: "forecast" as CommandTabId,
  focusedPaperdollSlot: "weapon" as PaperdollSlotId,
  openContainerTileId: null as string | null,
  brokerTaggedTileIds: new Set<string>(),
  soldRackTileIds: new Set<string>(),
  rackPlacements: new Map<string, RackPlacement>(),
  rackHoverPlacement: null as RackHoverState | null,
  hiddenRackTileIds: new Set<string>(),
  equippedItems: {} as Partial<Record<EquipmentSlotId, StashTileDefinition>>,
  storageItems: {
    "tactical-rig": [] as StashTileDefinition[],
    pockets: [] as StashTileDefinition[],
    backpack: [] as StashTileDefinition[],
    pouch: [] as StashTileDefinition[]
  },
  storagePlacements: {
    "tactical-rig": new Map<string, RackPlacement>(),
    pockets: new Map<string, RackPlacement>(),
    backpack: new Map<string, RackPlacement>(),
    pouch: new Map<string, RackPlacement>()
  } as Record<StorageSurfaceId, Map<string, RackPlacement>>,
  quickSlotAssignments: {} as Partial<Record<QuickSlotId, string>>,
  rackSearchQuery: "",
  rackFilter: "all" as StashFilterId,
  realizedBrokerCredits: 0,
  realizedBrokerItems: 0
};

let currentBenchTiles: StashTileDefinition[] = [];
let currentRackTiles: StashTileDefinition[] = [];

const debugParams = new URLSearchParams(window.location.search);
const debugTelemetryEnabled = debugParams.get("debugTelemetry") === "1";

function clearDragTargets(): void {
  for (const element of document.querySelectorAll<HTMLElement>("[data-drop-active]")) {
    delete element.dataset.dropActive;
  }

  for (const slotHint of document.querySelectorAll<HTMLElement>("[data-paperdoll-slot-hint]")) {
    const defaultHint = slotHint.dataset.paperdollHintDefault;
    if (defaultHint) {
      slotHint.textContent = defaultHint;
    }
  }

  clearRackDropPreviewClasses();

  stashUiState.rackHoverPlacement = null;
}

function clearRackDropPreviewClasses(): void {
  for (const cell of document.querySelectorAll<HTMLElement>(".stash-rack-cell-drop-valid, .stash-rack-cell-drop-invalid, .stash-rack-cell-drop-swap")) {
    cell.classList.remove("stash-rack-cell-drop-valid", "stash-rack-cell-drop-invalid", "stash-rack-cell-drop-swap");
  }
}

function applyDropTarget(target: HTMLElement | null): void {
  clearDragTargets();

  if (target) {
    target.dataset.dropActive = "true";
  }
}

function resolveDropTarget(target: EventTarget | null, payload: StashDragState | null): StashDropTarget | null {
  if (!(target instanceof HTMLElement) || !payload) {
    return null;
  }

  const equipmentDropzone = target.closest<HTMLElement>("[data-equipment-dropzone]");
  const equipmentSlotId = equipmentDropzone?.dataset.equipmentDropzone as EquipmentSlotId | undefined;
  if (equipmentDropzone && equipmentSlotId) {
    return {
      kind: "equipment",
      element: equipmentDropzone,
      slotId: equipmentSlotId
    };
  }

  const storageDropCell = target.closest<HTMLElement>("[data-storage-drop-cell]");
  const storageSurfaceId = storageDropCell?.dataset.storageSurface as StorageSurfaceId | undefined;
  const storageColumn = Number(storageDropCell?.dataset.storageColumn ?? "0");
  const storageRow = Number(storageDropCell?.dataset.storageRow ?? "0");
  if (storageDropCell && storageSurfaceId && storageColumn > 0 && storageRow > 0) {
    return {
      kind: "storage",
      element: storageDropCell.closest<HTMLElement>("[data-storage-surface-panel]") ?? storageDropCell,
      surfaceId: storageSurfaceId,
      columnStart: storageColumn,
      rowStart: storageRow
    };
  }

  const quickSlotDropzone = target.closest<HTMLElement>("[data-quick-slot-dropzone]");
  const quickSlotId = quickSlotDropzone?.dataset.quickSlotDropzone as QuickSlotId | undefined;
  if (quickSlotDropzone && quickSlotId) {
    return {
      kind: "quick-slot",
      element: quickSlotDropzone,
      slotId: quickSlotId
    };
  }

  const paperdollDropzone = target.closest<HTMLElement>("[data-paperdoll-dropzone]");
  const paperdollSlotId = paperdollDropzone?.dataset.paperdollDropzone as PaperdollSlotId | undefined;
  if (paperdollDropzone && paperdollSlotId) {
    return {
      kind: "paperdoll",
      element: paperdollDropzone,
      slotId: paperdollSlotId
    };
  }

  const prepDropzone = target.closest<HTMLElement>("[data-prep-dropzone]");
  const prepResource = prepDropzone?.dataset.prepDropzone as PrepResource | undefined;
  if (prepDropzone && prepResource) {
    return {
      kind: "prep",
      element: prepDropzone,
      resource: prepResource
    };
  }

  const benchDropzone = target.closest<HTMLElement>("[data-stash-bench]");
  if (benchDropzone) {
    return {
      kind: "bench",
      element: benchDropzone
    };
  }

  const rackCell = target.closest<HTMLElement>("[data-rack-drop-cell]");
  const rackColumn = Number(rackCell?.dataset.rackColumn ?? "0");
  const rackRow = Number(rackCell?.dataset.rackRow ?? "0");
  if (rackCell && rackColumn > 0 && rackRow > 0) {
    return {
      kind: "rack-cell",
      element: stashRackValue,
      cell: rackCell,
      columnStart: rackColumn,
      rowStart: rackRow
    };
  }

  const rackDropzone = target.closest<HTMLElement>("[data-stash-rack]");
  if (rackDropzone) {
    return {
      kind: "rack-return",
      element: rackDropzone
    };
  }

  return null;
}

function previewDropTarget(target: StashDropTarget | null, payload: StashDragState): boolean {
  clearDragTargets();

  if (!target) {
    return false;
  }

  if (target.kind === "paperdoll") {
    const hintValue = target.element.querySelector<HTMLElement>("[data-paperdoll-slot-hint]");
    const rejectHint = getPaperdollRejectHint(target.slotId, payload);
    if (hintValue && rejectHint) {
      hintValue.textContent = rejectHint;
    }
  }

  switch (target.kind) {
    case "bench":
      if (payload.kind !== "weapon") {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "rack-return":
      if (payload.source === "rack") {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "rack-cell":
      if (payload.source !== "rack") {
        return false;
      }
      setRackHoverPlacement(payload.tileId, target.columnStart, target.rowStart);
      previewRackDropCell(target.cell, stashUiState.rackHoverPlacement?.action ?? "invalid");
      return true;
    case "prep":
      if (payload.kind !== "resource" || payload.source !== "rack" || payload.resource !== target.resource) {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "paperdoll":
      if (!canPaperdollAcceptDrop(target.slotId, payload)) {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "equipment":
      if (!canEquipmentAcceptDrop(target.slotId, payload)) {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "storage":
      if (!canStorageAcceptDrop(target.surfaceId, payload)) {
        return false;
      }
      applyDropTarget(target.element);
      return true;
    case "quick-slot":
      if (!canQuickSlotAcceptDrop(target.slotId, payload)) {
        return false;
      }
      applyDropTarget(target.element);
      return true;
  }
}

function commitDropTarget(target: StashDropTarget | null, payload: StashDragState): boolean {
  if (!target) {
    return false;
  }

  switch (target.kind) {
    case "bench":
      if (payload.kind !== "weapon") {
        return false;
      }
      handleBenchDrop(payload);
      return true;
    case "rack-return":
      if (payload.source === "rack") {
        return false;
      }
      handleRackDrop(payload);
      return true;
    case "rack-cell":
      if (payload.source !== "rack" || !stashUiState.rackHoverPlacement?.valid) {
        return false;
      }
      moveRackTile(payload.tileId, target.columnStart, target.rowStart);
      return true;
    case "prep":
      if (payload.kind !== "resource" || payload.source !== "rack" || payload.resource !== target.resource) {
        return false;
      }
      handlePrepDrop(target.resource, payload);
      return true;
    case "paperdoll":
      if (!canPaperdollAcceptDrop(target.slotId, payload)) {
        return false;
      }
      handlePaperdollDrop(target.slotId, payload);
      return true;
    case "equipment":
      if (!canEquipmentAcceptDrop(target.slotId, payload)) {
        return false;
      }
      handleEquipmentDrop(target.slotId, payload);
      return true;
    case "storage":
      if (!canStorageAcceptDrop(target.surfaceId, payload)) {
        return false;
      }
      handleStorageDrop(target.surfaceId, target.columnStart, target.rowStart, payload);
      return true;
    case "quick-slot":
      if (!canQuickSlotAcceptDrop(target.slotId, payload)) {
        return false;
      }
      assignQuickSlot(target.slotId, payload);
      return true;
  }
}

function clearManualDragState(): void {
  manualDragState.payload = null;
  manualDragState.pointerId = null;
  manualDragState.startX = 0;
  manualDragState.startY = 0;
  manualDragState.active = false;
}

function parseStashDragPayload(element: HTMLElement | null): StashDragState | null {
  if (!element) {
    return null;
  }

  const kind = element.dataset.dragKind as StashDragState["kind"] | undefined;
  const source = element.dataset.dragSource as StashDragState["source"] | undefined;
  const tileId = element.dataset.dragTileId;

  if (!kind || !source || !tileId) {
    return null;
  }

  if (kind === "weapon") {
    const weaponId = element.dataset.dragWeapon as WeaponId | undefined;
    return weaponId
      ? {
          kind,
          source,
          tileId,
          weaponId,
          equipmentSlotId: element.dataset.dragEquipmentSlot as EquipmentSlotId | undefined,
          storageSurfaceId: element.dataset.dragStorageSurface as StorageSurfaceId | undefined
        }
      : null;
  }

  if (kind === "item") {
    return {
      kind,
      source,
      tileId,
      equipmentSlotId: element.dataset.dragEquipmentSlot as EquipmentSlotId | undefined,
      storageSurfaceId: element.dataset.dragStorageSurface as StorageSurfaceId | undefined
    };
  }

  const resource = element.dataset.dragResource as PrepResource | undefined;
  return resource
    ? {
        kind,
        source,
        tileId,
        resource,
        equipmentSlotId: element.dataset.dragEquipmentSlot as EquipmentSlotId | undefined,
        storageSurfaceId: element.dataset.dragStorageSurface as StorageSurfaceId | undefined
      }
    : null;
}

function handleBenchDrop(payload: StashDragState): void {
  if (payload.kind !== "weapon" || !payload.weaponId) {
    return;
  }

  stashUiState.activeGearWorkbenchTab = "loadout";
  selectWeapon(payload.weaponId);
}

function handleRackDrop(payload: StashDragState): void {
  if (payload.source === "equipment") {
    const tile = detachMovableTile(payload.tileId);

    if (!tile) {
      return;
    }

    if (payload.equipmentSlotId === "on-sling" && tile.weaponId) {
      selectWeapon("none");
      return;
    }

    stashUiState.hiddenRackTileIds.delete(tile.id);
    updateUi();
    return;
  }

  if (payload.source === "container") {
    detachMovableTile(payload.tileId);
    stashUiState.hiddenRackTileIds.delete(payload.tileId);
    updateUi();
    return;
  }

  if (payload.source !== "bench") {
    return;
  }

  if (payload.kind === "weapon") {
    selectWeapon("none");
    return;
  }

  if (payload.kind !== "resource" || !payload.resource) {
    return;
  }

  raidController.adjustPrepLoadout(payload.resource, -1);
  updateUi();
}

function getPaperdollRejectHint(slotId: PaperdollSlotId, payload: StashDragState | null): string | null {
  if (!payload || payload.source !== "rack") {
    return null;
  }

  if (payload.kind === "item") {
    return "Stash-only item. This cannot be worn.";
  }

  if (slotId === "weapon") {
    return payload.kind === "resource" ? "Only primary weapons fit here." : null;
  }

  if (slotId === "medkits") {
    if (payload.kind === "weapon") {
      return "Only field dressings fit here.";
    }

    return payload.resource === "ammoPacks" ? "Ammo packs cannot go into the dressing slot." : null;
  }

  if (slotId === "ammo") {
    if (payload.kind === "weapon") {
      return "Only ammo packs fit here.";
    }

    return payload.resource === "medkits" ? "Field dressings cannot go into the ammo slot." : null;
  }

  return "This slot is planning data, not wearable gear.";
}

function getDragTile(payload: StashDragState): StashTileDefinition | null {
  if (payload.source === "rack") {
    return currentRackTiles.find((tile) => tile.id === payload.tileId) ?? null;
  }

  if (payload.source === "bench") {
    return currentBenchTiles.find((tile) => tile.id === payload.tileId) ?? null;
  }

  if (payload.source === "equipment") {
    return findEquipmentTileById(payload.tileId) ?? getEquipmentTile("on-sling", raidController.state.selectedWeapon);
  }

  const storageTile = findStorageTileById(payload.tileId);
  return storageTile?.tile ?? null;
}

function canStorageAcceptDrop(surfaceId: StorageSurfaceId, payload: StashDragState | null): boolean {
  if (!payload || payload.kind === "resource") {
    return false;
  }

  if (!isStorageSurfaceEnabled(surfaceId, raidController.state.selectedWeapon)) {
    return false;
  }

  const tile = getDragTile(payload);
  return tile ? canTileEnterStorageSurface(surfaceId, tile) : false;
}

function canEquipmentAcceptDrop(slotId: EquipmentSlotId, payload: StashDragState | null): boolean {
  if (!payload) {
    return false;
  }

  if (slotId === "pockets") {
    return false;
  }

  if (slotId === "on-sling") {
    return payload.kind === "weapon";
  }

  const tile = getDragTile(payload);
  return tile ? canEquipTileInSlot(slotId, tile) : false;
}

function handleEquipmentDrop(slotId: EquipmentSlotId, payload: StashDragState): void {
  if (!canEquipmentAcceptDrop(slotId, payload)) {
    return;
  }

  const sourceSlotId = payload.source === "equipment" ? payload.equipmentSlotId ?? findEquippedSlotByTileId(payload.tileId) : null;
  const previousTile = slotId === "on-sling" ? getEquipmentTile("on-sling", raidController.state.selectedWeapon) : stashUiState.equippedItems[slotId];

  if (sourceSlotId === slotId) {
    return;
  }

  const tile = detachMovableTile(payload.tileId);

  if (!tile) {
    return;
  }

  const normalizedTile =
    (slotId === "on-sling" || slotId === "on-back") && tile.weaponId
      ? createEquippedWeaponTile(slotId, tile.weaponId, tile.id)
      : tile;

  if (previousTile && sourceSlotId && sourceSlotId !== slotId && canEquipTileInSlot(sourceSlotId, previousTile)) {
    stashUiState.equippedItems[sourceSlotId] =
      (sourceSlotId === "on-sling" || sourceSlotId === "on-back") && previousTile.weaponId
        ? createEquippedWeaponTile(sourceSlotId, previousTile.weaponId, previousTile.id)
        : previousTile;
  } else if (previousTile) {
    stashUiState.hiddenRackTileIds.delete(previousTile.id);
  }

  if (slotId === "on-sling" && normalizedTile.weaponId) {
    selectWeapon(normalizedTile.weaponId);
    stashUiState.activeGearWorkbenchTab = "loadout";
    updateUi();
    return;
  }

  stashUiState.equippedItems[slotId] = normalizedTile;

  if (slotId === "on-sling" || sourceSlotId === "on-sling") {
    syncSelectedWeaponFromEquipment();
  }

  stashUiState.activeGearWorkbenchTab = "loadout";
  updateUi();
}

function handleStorageDrop(surfaceId: StorageSurfaceId, columnStart: number, rowStart: number, payload: StashDragState): void {
  if (!canStorageAcceptDrop(surfaceId, payload)) {
    return;
  }

  const sourceSlotId = payload.source === "equipment" ? payload.equipmentSlotId ?? findEquippedSlotByTileId(payload.tileId) : null;
  const tile = detachMovableTile(payload.tileId);

  if (!tile) {
    return;
  }

  const surface = STORAGE_SURFACES[surfaceId];
  const definition = getInventoryItemDefinition(getTileInventoryItemId(tile.variant, tile.weaponId));
  const placement: RackPlacement = {
    columnStart,
    rowStart,
    rotated: false
  };
  const footprint = getItemFootprint(definition, placement.rotated);
  const occupants = stashUiState.storageItems[surfaceId]
    .map((entry) => toRackOccupant(entry))
    .filter((entry): entry is GridOccupant => entry !== null);
  const validation = validateGridPlacement(surface, occupants, {
    id: tile.id,
    width: footprint.width,
    height: footprint.height,
    placement
  });

  if (!validation.ok) {
    if (payload.source === "rack") {
      stashUiState.hiddenRackTileIds.delete(tile.id);
    } else if (payload.source === "equipment" && payload.equipmentSlotId) {
      stashUiState.equippedItems[payload.equipmentSlotId] = tile;
      if (payload.equipmentSlotId === "on-sling") {
        syncSelectedWeaponFromEquipment();
      }
    } else if (payload.source === "container" && payload.storageSurfaceId) {
      stashUiState.storageItems[payload.storageSurfaceId].push(tile);
      stashUiState.storagePlacements[payload.storageSurfaceId].set(tile.id, getTileBasePlacement(tile));
    }
    return;
  }

  stashUiState.storageItems[surfaceId].push(tile);
  stashUiState.storagePlacements[surfaceId].set(tile.id, placement);

  if (sourceSlotId === "on-sling") {
    syncSelectedWeaponFromEquipment();
  }

  stashUiState.activeGearWorkbenchTab = "storage";
  updateUi();
}

function setRackHoverPlacement(tileId: string, columnStart: number, rowStart: number): void {
  const tile = currentRackTiles.find((entry) => entry.id === tileId);

  if (!tile) {
    stashUiState.rackHoverPlacement = null;
    return;
  }

  const rotated = stashUiState.rackPlacements.get(tileId)?.rotated ?? tile.rotated ?? false;
  const resolution = resolveRackMove(currentRackTiles, tileId, columnStart, rowStart, rotated);
  stashUiState.rackHoverPlacement = {
    tileId,
    columnStart,
    rowStart,
    rotated,
    valid: resolution.valid,
    action: resolution.action,
    displacedTileId: resolution.displacedTileId
  };
}

function previewRackDropCell(target: HTMLElement, action: RackHoverState["action"]): void {
  clearRackDropPreviewClasses();

  const hoverPlacement = stashUiState.rackHoverPlacement;
  const rackCell = target.closest<HTMLElement>("[data-rack-drop-cell]");

  if (!hoverPlacement || !rackCell) {
    return;
  }

  const tile = currentRackTiles.find((entry) => entry.id === hoverPlacement.tileId);

  if (!tile) {
    return;
  }

  const { width, height } = getRackFootprint(tile, hoverPlacement.rotated);

  for (let row = hoverPlacement.rowStart; row < hoverPlacement.rowStart + height; row += 1) {
    for (let column = hoverPlacement.columnStart; column < hoverPlacement.columnStart + width; column += 1) {
      const previewCell = stashRackValue.querySelector<HTMLElement>(
        `[data-rack-column="${column}"][data-rack-row="${row}"]`
      );

      if (!previewCell) {
        continue;
      }

      if (action === "move") {
        previewCell.classList.add("stash-rack-cell-drop-valid");
      } else if (action === "swap") {
        previewCell.classList.add("stash-rack-cell-drop-swap");
      } else {
        previewCell.classList.add("stash-rack-cell-drop-invalid");
      }
    }
  }
}

function moveRackTile(tileId: string, columnStart: number, rowStart: number): void {
  const tile = currentRackTiles.find((entry) => entry.id === tileId);

  if (!tile) {
    return;
  }

  const rotated = stashUiState.rackPlacements.get(tileId)?.rotated ?? tile.rotated ?? false;
  const resolution = resolveRackMove(currentRackTiles, tileId, columnStart, rowStart, rotated);

  if (!resolution.valid) {
    return;
  }

  stashUiState.rackPlacements.set(tileId, { columnStart, rowStart, rotated });

  if (resolution.action === "swap" && resolution.displacedTileId) {
    const displacedTile = currentRackTiles.find((entry) => entry.id === resolution.displacedTileId);
    const currentPlacement = getRackPlacementForTile(tile);

    if (displacedTile && currentPlacement) {
      stashUiState.rackPlacements.set(displacedTile.id, {
        columnStart: currentPlacement.columnStart,
        rowStart: currentPlacement.rowStart,
        rotated: displacedTile.rotated ?? false
      });
    }
  }

  stashUiState.selectedTileId = tileId;
  stashUiState.rackHoverPlacement = null;
  updateUi();
}

function rotateRackTile(tileId: string): void {
  const tile = currentRackTiles.find((entry) => entry.id === tileId);

  if (!tile || !canRotateRackTile(tile)) {
    return;
  }

  const currentPlacement = stashUiState.rackPlacements.get(tileId) ?? {
    columnStart: tile.rackColumnStart ?? 1,
    rowStart: tile.rackRowStart ?? 1,
    rotated: tile.rotated ?? false
  };
  const rotated = !currentPlacement.rotated;

  if (!canPlaceRackTileAtPosition(currentRackTiles, tileId, currentPlacement.columnStart, currentPlacement.rowStart, rotated)) {
    return;
  }

  stashUiState.rackPlacements.set(tileId, {
    columnStart: currentPlacement.columnStart,
    rowStart: currentPlacement.rowStart,
    rotated
  });
  stashUiState.selectedTileId = tileId;
  stashUiState.rackHoverPlacement = null;
  updateUi();
}

function handlePrepDrop(resource: PrepResource, payload: StashDragState): void {
  if (payload.kind !== "resource" || payload.source !== "rack" || payload.resource !== resource) {
    return;
  }

  raidController.adjustPrepLoadout(resource, 1);
  updateUi();
}

function canAssignTileToQuickSlot(tile: StashTileDefinition): boolean {
  if (tile.dragKind === "resource" || tile.dragKind === "weapon") {
    return true;
  }

  const definition = getInventoryItemDefinition(getTileInventoryItemId(tile.variant, tile.weaponId));
  return definition.category !== "gear" && definition.category !== "container";
}

function canQuickSlotAcceptDrop(_slotId: QuickSlotId, payload: StashDragState | null): boolean {
  if (!payload) {
    return false;
  }

  const tile = getDragTile(payload);
  return tile ? canAssignTileToQuickSlot(tile) : false;
}

function assignQuickSlot(slotId: QuickSlotId, payload: StashDragState): void {
  if (!canQuickSlotAcceptDrop(slotId, payload)) {
    return;
  }

  stashUiState.quickSlotAssignments[slotId] = payload.tileId;
  updateUi();
}

function clearQuickSlotAssignment(slotId: QuickSlotId): void {
  delete stashUiState.quickSlotAssignments[slotId];
  updateUi();
}

function getNextOpenQuickSlotId(): QuickSlotId {
  return QUICK_SLOT_IDS.find((slotId) => !stashUiState.quickSlotAssignments[slotId]) ?? "4";
}

function cleanupQuickSlotAssignments(): void {
  for (const slotId of QUICK_SLOT_IDS) {
    const tileId = stashUiState.quickSlotAssignments[slotId];

    if (!tileId) {
      continue;
    }

    const tile = findStashTile(tileId);

    if (!tile || !canAssignTileToQuickSlot(tile)) {
      delete stashUiState.quickSlotAssignments[slotId];
    }
  }
}

function getQuickSlotPresentation(slotId: QuickSlotId, selectedWeapon: WeaponId, prepLoadout: SupplyStock): QuickSlotPresentation {
  const assignedTileId = stashUiState.quickSlotAssignments[slotId];
  const assignedTile = assignedTileId ? findStashTile(assignedTileId) : null;

  if (assignedTile && canAssignTileToQuickSlot(assignedTile)) {
    return {
      label: assignedTile.label,
      meta: assignedTile.meta,
      tone: assignedTile.tone,
      source: assignedTile.dragSource === "rack" ? "stash" : assignedTile.dragSource ?? "stash",
      assignedTileId,
      removable: true
    };
  }

  if (slotId === "1" && selectedWeapon !== "none") {
    return {
      label: WEAPONS[selectedWeapon].name,
      meta: "live sling weapon",
      tone: "weapon",
      source: "default"
    };
  }

  if (slotId === "2" && prepLoadout.medkits > 0) {
    return {
      label: `${prepLoadout.medkits} Dressings`,
      meta: "field sustain",
      tone: "supply",
      source: "default"
    };
  }

  if (slotId === "3" && prepLoadout.ammoPacks > 0) {
    return {
      label: `${prepLoadout.ammoPacks} Ammo Pack${prepLoadout.ammoPacks === 1 ? "" : "s"}`,
      meta: "reserve rounds",
      tone: "supply",
      source: "default"
    };
  }

  return {
    label: "Empty",
    meta: "drag usable gear here",
    tone: "support",
    source: "open"
  };
}

function renderQuickSlot(slotId: QuickSlotId, selectedWeapon: WeaponId, prepLoadout: SupplyStock): string {
  const presentation = getQuickSlotPresentation(slotId, selectedWeapon, prepLoadout);
  const filled = presentation.label !== "Empty";

  return `
    <div
      class="stash-quick-slot${filled ? " stash-quick-slot-filled" : ""}${presentation.removable ? " stash-quick-slot-custom" : ""} stash-quick-slot-tone-${presentation.tone}"
      data-quick-slot-dropzone="${slotId}"
      title="Quick slot ${slotId}: ${presentation.label}"
    >
      <div class="stash-quick-slot-head">
        <span>${slotId}</span>
        <em>${presentation.source}</em>
      </div>
      <strong>${presentation.label}</strong>
      <small>${presentation.meta}</small>
      ${
        presentation.removable
          ? `<button class="stash-quick-slot-clear" type="button" data-quick-slot-clear="${slotId}">Clear</button>`
          : ""
      }
    </div>
  `;
}

function canPaperdollAcceptDrop(slotId: PaperdollSlotId, payload: StashDragState | null): boolean {
  if (!payload) {
    return false;
  }

  if (slotId === "weapon") {
    return payload.kind === "weapon";
  }

  if (slotId === "medkits") {
    return payload.kind === "resource" && payload.source === "rack" && payload.resource === "medkits";
  }

  if (slotId === "ammo") {
    return payload.kind === "resource" && payload.source === "rack" && payload.resource === "ammoPacks";
  }

  return false;
}

function handlePaperdollDrop(slotId: PaperdollSlotId, payload: StashDragState): void {
  if (!canPaperdollAcceptDrop(slotId, payload)) {
    return;
  }

  if (slotId === "weapon" && payload.kind === "weapon" && payload.weaponId) {
    stashUiState.activeGearWorkbenchTab = "loadout";
    selectWeapon(payload.weaponId);
    stashUiState.focusedPaperdollSlot = "weapon";
    updateUi();
    return;
  }

  if (slotId === "medkits" && payload.kind === "resource" && payload.resource === "medkits") {
    raidController.adjustPrepLoadout("medkits", 1);
    stashUiState.activeGearWorkbenchTab = "storage";
    stashUiState.focusedPaperdollSlot = "medkits";
    updateUi();
    return;
  }

  if (slotId === "ammo" && payload.kind === "resource" && payload.resource === "ammoPacks") {
    raidController.adjustPrepLoadout("ammoPacks", 1);
    stashUiState.activeGearWorkbenchTab = "storage";
    stashUiState.focusedPaperdollSlot = "ammo";
    updateUi();
  }
}

function getAllStashTiles(): StashTileDefinition[] {
  const equippedTiles = Object.values(stashUiState.equippedItems).filter((tile): tile is StashTileDefinition => Boolean(tile));
  const storageTiles = (Object.keys(stashUiState.storageItems) as StorageSurfaceId[]).flatMap((surfaceId) => getStorageSurfaceTiles(surfaceId));
  return [...currentBenchTiles, ...currentRackTiles, ...equippedTiles, ...storageTiles];
}

function findStashTile(tileId: string): StashTileDefinition | null {
  return getAllStashTiles().find((tile) => tile.id === tileId) ?? null;
}

function isRecoveredFieldWeaponTile(tile: StashTileDefinition): boolean {
  return tile.id.startsWith("rack-field-capture-") || tile.id.startsWith("rack-captured-weapon-");
}

function getUnsoldCapturedWeapon(summary: RaidSummary | null): NonNullable<RaidSummary["capturedWeapon"]> | null {
  if (!summary?.capturedWeapon) {
    return null;
  }

  const capturedWeapon = summary.capturedWeapon;
  const rackTileId = `rack-captured-weapon-${capturedWeapon.weaponId}`;
  const reserveTileId = `rack-field-capture-${capturedWeapon.weaponId}`;

  if (stashUiState.soldRackTileIds.has(rackTileId) || stashUiState.soldRackTileIds.has(reserveTileId)) {
    return null;
  }

  return capturedWeapon;
}

function getStashTileSellValue(tile: StashTileDefinition): number {
  if (isRecoveredFieldWeaponTile(tile)) {
    const capturedWeapon = getUnsoldCapturedWeapon(raidController.state.lastRaidSummary);
    if (capturedWeapon && capturedWeapon.weaponId === tile.weaponId) {
      return capturedWeapon.salvageValue;
    }
  }

  const definition = getInventoryItemDefinition(getTileInventoryItemId(tile.variant, tile.weaponId));
  return Math.max(0, definition.value);
}

function canSellStashTile(tile: StashTileDefinition): boolean {
  if (tile.dragSource !== "rack") {
    return false;
  }

  if (isRecoveredFieldWeaponTile(tile)) {
    return getStashTileSellValue(tile) > 0;
  }

  return getNormalizedStashCategory(tile) === "broker-haul" && stashUiState.brokerTaggedTileIds.has(tile.id);
}

function sellStashTile(tile: StashTileDefinition): void {
  if (!canSellStashTile(tile)) {
    return;
  }

  const sellValue = getStashTileSellValue(tile);
  if (sellValue <= 0) {
    return;
  }

  if (isRecoveredFieldWeaponTile(tile) && tile.weaponId) {
    stashUiState.soldRackTileIds.add(`rack-captured-weapon-${tile.weaponId}`);
    stashUiState.soldRackTileIds.add(`rack-field-capture-${tile.weaponId}`);
  } else {
    stashUiState.soldRackTileIds.add(tile.id);
  }
  stashUiState.brokerTaggedTileIds.delete(tile.id);
  stashUiState.rackPlacements.delete(tile.id);

  if (stashUiState.selectedTileId === tile.id) {
    stashUiState.selectedTileId = null;
  }

  if (stashUiState.contextTileId === tile.id) {
    stashUiState.contextTileId = null;
  }

  if (stashUiState.openContainerTileId === tile.id) {
    stashUiState.openContainerTileId = null;
  }

  raidController.state.stashCredits += sellValue;
  stashUiState.realizedBrokerCredits += sellValue;
  stashUiState.realizedBrokerItems += 1;
  raidController.state.message = isRecoveredFieldWeaponTile(tile)
    ? `${tile.label} was brokered for ${sellValue} credits. The wall is lighter, but the stash can fund the next push instead of hoarding one more trophy.`
    : `${tile.label} was cashed out for ${sellValue} credits. The broker weight is off the wall and back into deployable money.`;
  updateUi();
}

