const game = new Phaser.Game({
  type: Phaser.AUTO,
  parent: "game-root",
  width: window.innerWidth,
  height: window.innerHeight,
  backgroundColor: "#020617",
  scene: [RaidScene],
  scale: {
    mode: Phaser.Scale.RESIZE,
    autoCenter: Phaser.Scale.CENTER_BOTH
  }
});

function getActiveRaidScene(): RaidScene | null {
  const scene = game.scene.getScene("raid-scene");
  return scene instanceof RaidScene ? scene : null;
}

function getRaidWorldPointFromClient(clientX: number, clientY: number): { x: number; y: number } | null {
  if (raidController.state.phase !== "raid") {
    return null;
  }

  const raidScene = getActiveRaidScene();
  const canvas = game.canvas;
  if (!raidScene || !canvas) {
    return null;
  }

  const bounds = canvas.getBoundingClientRect();
  const screenX = clientX - bounds.left;
  const screenY = clientY - bounds.top;
  const worldPoint = raidScene.cameras.main.getWorldPoint(screenX, screenY);
  return { x: worldPoint.x, y: worldPoint.y };
}

function normalizePlacementAngleRadians(angle: number): number {
  const fullTurn = Math.PI * 2;
  return ((angle % fullTurn) + fullTurn) % fullTurn;
}

function formatPlacementAngle(angle: number): string {
  return `${Math.round((normalizePlacementAngleRadians(angle) * 180) / Math.PI)} deg`;
}

function syncOfficerBuildPlacementPreview(position: { x: number; y: number } | null = officerToolsState.previewWorld): void {
  if (officerToolsState.placementMode === null) {
    officerToolsState.previewWorld = null;
    townWarController.clearBuildPlacementPreview();
    return;
  }

  officerToolsState.previewWorld = position;
  townWarController.setBuildPlacementPreview({
    kind: officerToolsState.placementMode,
    faction: getOfficerCamp(townWarController.getSnapshot()),
    position,
    facingAngleRadians: officerToolsState.placementMode === "trench" || officerToolsState.placementMode === "dugout" ? officerToolsState.placementAngleRadians : 0,
    valid: position !== null
  });
}

function cancelOfficerPlacement(message = "Placement cancelled."): void {
  officerToolsState.placementMode = null;
  officerToolsState.lastAction = message;
  syncOfficerBuildPlacementPreview(null);
  renderOfficerTools();
}

function isEditableEventTarget(target: EventTarget | null): boolean {
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    (target instanceof HTMLElement && target.isContentEditable)
  );
}

window.addEventListener("resize", () => {
  game.scale.resize(window.innerWidth, window.innerHeight);
});

window.addEventListener(
  "keydown",
  (event) => {
    if (isEditableEventTarget(event.target)) {
      return;
    }

    if (event.key === "Escape" && officerToolsState.placementMode !== null) {
      cancelOfficerPlacement("Placement cancelled.");
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    if (frontDoorState.menuOpen && frontDoorState.panel === "survivor-test") {
      ensureSurvivorTestAudioReady();
      const key = event.key.toLowerCase();
      if (
        key === "w" ||
        key === "a" ||
        key === "s" ||
        key === "d" ||
        key.startsWith("arrow") ||
        key === "shift" ||
        key === "control"
      ) {
        survivorWalkKeys.add(key);
        event.preventDefault();
      } else if (key === "1") {
        setSurvivorTestWeaponPreset("worn-ak");
        event.preventDefault();
      } else if (key === "2") {
        setSurvivorTestWeaponPreset("rifle");
        event.preventDefault();
      } else if (key === "3") {
        setSurvivorTestWeaponPreset("knife");
        event.preventDefault();
      } else if (key === "f1") {
        setSurvivorTestStatePreset("close-snap");
        event.preventDefault();
      } else if (key === "f2") {
        setSurvivorTestStatePreset("long-lane");
        event.preventDefault();
      } else if (key === "q" || key === "r") {
        startSurvivorWalkReload(performance.now());
        updateSurvivorWalkPresentation();
        event.preventDefault();
      } else if (key === " ") {
        restartCurrentSurvivorTestDrill(performance.now());
        updateSurvivorWalkPresentation();
        event.preventDefault();
      } else if (key === "t") {
        resetSurvivorWalkState();
        updateSurvivorWalkPresentation();
        event.preventDefault();
      }
    } else if (frontDoorState.menuOpen && frontDoorState.panel === "gulag-duel") {
      ensureSurvivorTestAudioReady();
      const key = event.key.toLowerCase();
      if (
        key === "w" ||
        key === "a" ||
        key === "s" ||
        key === "d" ||
        key.startsWith("arrow") ||
        key === "shift" ||
        key === "control"
      ) {
        gulagDuelKeys.add(key);
        event.preventDefault();
      } else if (key === "1") {
        setGulagDuelDifficulty("easy");
        event.preventDefault();
      } else if (key === "2") {
        setGulagDuelDifficulty("standard");
        event.preventDefault();
      } else if (key === "3") {
        setGulagDuelDifficulty("hard");
        event.preventDefault();
      } else if (key === "q" || key === "r") {
        startGulagDuelReload(performance.now());
        updateGulagDuelPresentation();
        event.preventDefault();
      } else if (key === "t") {
        resetGulagDuelState();
        updateGulagDuelPresentation();
        event.preventDefault();
      }
    }
  },
  true
);

window.addEventListener(
  "keyup",
  (event) => {
    const key = event.key.toLowerCase();
    if (
      key === "w" ||
      key === "a" ||
      key === "s" ||
      key === "d" ||
      key.startsWith("arrow") ||
      key === "shift" ||
      key === "control"
    ) {
      survivorWalkKeys.delete(key);
      gulagDuelKeys.delete(key);
    }
  },
  true
);

