function stageDebugFrontlineAftermathShowcase(): void {
  if (raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const routedIncident = raidController.state.frontlineIncidents.find((incident) => incident.kind === "firefight");
  const reclaimedIncident = raidController.state.frontlineIncidents.find(
    (incident) => incident.kind === "firefight" && incident.id !== routedIncident?.id
  );
  const reclaimSupport = raidController.state.frontlineSupports.find((support) => support.kind === "fireteam");
  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );

  if (activeSector) {
    activeSector.control = "contested";
    activeSector.pressure = 66;
    activeSector.fortification = 48;
    activeSector.scars = 61;
    activeSector.routeModifierTitle = "Shaky reclaimed pocket";
    activeSector.routeModifierSummary =
      "The line is only half-stitched together. Expect extra route friction, but the pocket can still be stabilized with one clean raid.";
    activeSector.enemyReduction = 0;
    activeSector.extractionHoldMultiplier = 1.08;
    activeSector.noiseMultiplier = 1.08;
    activeSector.activeEvent = `${activeSector.routeName} is still reading as mixed reclaimed and wiped ground after the last push.`;
    activeSector.watch = "Friendlies are sitting on part of the scar, but Blue still has enough broken cover to contest the lane.";
  }

  if (routedIncident) {
    routedIncident.status = "routed";
    routedIncident.contactTimer = 0;
    routedIncident.strength = Math.min(routedIncident.strength, 1);
    routedIncident.territoryState = "lost";
    routedIncident.territoryNote = "Blue still owns this broken pocket and the lane reads as wiped ground.";
    routedIncident.note = `${routedIncident.label} was overrun and left a dead strip behind it.`;
  }

  if (reclaimedIncident) {
    reclaimedIncident.status = "routed";
    reclaimedIncident.contactTimer = 0.8;
    reclaimedIncident.strength = Math.min(reclaimedIncident.strength, 1);
    reclaimedIncident.territoryState = "reclaimed";
    reclaimedIncident.territoryNote = "Friendly rifles stepped back into the scar and turned it into reclaimed ground.";
    reclaimedIncident.note = `${reclaimedIncident.label} broke, but friendlies pushed onto the pocket before it fully slipped.`;
  }

  if (reclaimSupport && reclaimedIncident) {
    reclaimSupport.status = "covering";
    reclaimSupport.contactTimer = 1.2;
    reclaimSupport.position = {
      x: reclaimedIncident.position.x - 34,
      y: reclaimedIncident.position.y + 18
    };
    reclaimSupport.target = { ...reclaimedIncident.position };
    reclaimSupport.note = `${reclaimSupport.label} is sitting on reclaimed ground and keeping the lane from slipping again.`;
  }

  if (reclaimedIncident) {
    raidController.state.focusedFrontlineIncidentId = reclaimedIncident.id;
    raidController.state.player.position = {
      x: reclaimedIncident.position.x - 140,
      y: reclaimedIncident.position.y + 90
    };
  }

  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

function stageDebugBreachShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("sundered-run");
  }

  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );

  if (activeSector) {
    activeSector.control = "lost";
    activeSector.pressure = 74;
    activeSector.fortification = 58;
    activeSector.scars = 82;
    activeSector.routeModifierTitle = "Wiped scar lane";
    activeSector.routeModifierSummary =
      "Blue still owns the broken pocket. Expect harder blockades, one bad breach lane, and more noise if you cut it open.";
    activeSector.enemyReduction = 0;
    activeSector.extractionHoldMultiplier = 1.18;
    activeSector.noiseMultiplier = 1.16;
    activeSector.activeEvent = `${activeSector.routeName} is reading as a wiped lane with only one workable breach cut.`;
    activeSector.watch = "The breach lane is the cleanest way forward, but the whole line will hear it.";
  }

  if (raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const breachObstacle = raidController.state.obstacles.find((obstacle) => obstacle.breach && !obstacle.breach.breached);
  const breachDoorway = breachObstacle
    ? getClosestObstacleDoorway(breachObstacle, {
        x: breachObstacle.x + breachObstacle.width / 2,
        y: breachObstacle.y + breachObstacle.height / 2
      })
    : null;

  if (!breachObstacle?.breach || !breachDoorway) {
    updateUi();
    return;
  }

  const breachPoint = getObstacleBreachPoint(breachObstacle);
  if (!breachPoint) {
    updateUi();
    return;
  }

  raidController.state.player.position = {
    x: breachPoint.x - 34,
    y: breachPoint.y + 18
  };
  raidController.state.player.facing = { x: 1, y: 0 };
  raidController.state.activeObstacleBreach = {
    obstacleId: breachObstacle.id,
    duration: breachObstacle.breach.duration,
    timer: Math.max(0.9, breachObstacle.breach.duration * 0.92)
  };
  raidController.state.message = `${breachObstacle.breach.label} is staged. Hold the cut and expect the lane to light up.`;
  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

function stageDebugBreachPushShowcase(): void {
  stageDebugBreachShowcase();

  if (raidController.state.phase !== "raid") {
    return;
  }

  const breachObstacle = raidController.state.obstacles.find((obstacle) => obstacle.breach && !obstacle.breach.breached);
  const breachDoorway = breachObstacle
    ? getClosestObstacleDoorway(breachObstacle, {
        x: breachObstacle.x + breachObstacle.width / 2,
        y: breachObstacle.y + breachObstacle.height / 2
      })
    : null;

  if (!breachObstacle?.breach || !breachDoorway) {
    updateUi();
    return;
  }

  const breach = breachObstacle.breach;

  breachObstacle.doorways = breachObstacle.doorways?.map((doorway) =>
    doorway === breachDoorway
      ? {
          ...doorway,
          width: Math.max(doorway.width, breach.widenedDoorwayWidth),
          depth: Math.max(doorway.depth ?? 0, breach.widenedDoorwayWidth * 0.72)
        }
      : doorway
  );
  breachObstacle.breach = {
    ...breach,
    breached: true
  };
  breachObstacle.label = `${breachObstacle.breach.label} // open lane`;
  raidController.state.activeObstacleBreach = null;
  raidController.state.focusedFrontlineIncidentId = null;
  raidController.state.player.position = {
    x: breachObstacle.x + breachObstacle.width * 0.4,
    y: breachObstacle.y + breachObstacle.height + 56
  };
  raidController.queueFrontlineSupportOrder("breach-push");
  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

function stageDebugRoomClearShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("sundered-run");
  }

  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );

  if (activeSector) {
    activeSector.control = "lost";
    activeSector.pressure = 79;
    activeSector.fortification = 64;
    activeSector.scars = 86;
    activeSector.routeModifierTitle = "Authored three-room clear stack";
    activeSector.routeModifierSummary =
      "The route now stages an authored breach mouth plus three linked interior rooms so one cut pays off into a real room-by-room takeover instead of a single doorway stop.";
    activeSector.enemyReduction = 0;
    activeSector.extractionHoldMultiplier = 1.2;
    activeSector.noiseMultiplier = 1.18;
    activeSector.activeEvent = `${activeSector.routeName} is stacked with authored breach mouths leading into a three-room interior push.`;
    activeSector.watch = "Cut the outer mouth, clear the first room, then keep pushing through the back rooms before the route collapses onto you.";
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const breachObstacles = raidController.state.obstacles.filter(
    (obstacle) =>
      obstacle.breach &&
      !obstacle.breach.breached &&
      (
        (obstacle.label ?? "").startsWith("Frontline breach mouth") ||
        obstacle.breach.label.endsWith(".1") ||
        obstacle.breach.label.endsWith(".2") ||
        obstacle.breach.label.endsWith(".3")
      )
  );
  const outerBreach = breachObstacles.find((obstacle) => (obstacle.label ?? "").startsWith("Frontline breach mouth")) ?? breachObstacles[0];
  const roomHold = breachObstacles.find((obstacle) => obstacle.breach?.label.endsWith(".1")) ?? breachObstacles[1];
  const followThroughRoom = breachObstacles.find((obstacle) => obstacle.breach?.label.endsWith(".2")) ?? breachObstacles[2];
  const deepStashRoom = breachObstacles.find((obstacle) => obstacle.breach?.label.endsWith(".3")) ?? breachObstacles[3];
  const outerDoorway = outerBreach ? getClosestObstacleDoorway(outerBreach, { x: outerBreach.x + outerBreach.width / 2, y: outerBreach.y + outerBreach.height / 2 }) : null;
  const roomDoorway = roomHold ? getClosestObstacleDoorway(roomHold, { x: roomHold.x + roomHold.width / 2, y: roomHold.y + roomHold.height / 2 }) : null;
  const followThroughDoorway = followThroughRoom ? getClosestObstacleDoorway(followThroughRoom, { x: followThroughRoom.x + followThroughRoom.width / 2, y: followThroughRoom.y + followThroughRoom.height / 2 }) : null;
  const deepStashDoorway = deepStashRoom ? getClosestObstacleDoorway(deepStashRoom, { x: deepStashRoom.x + deepStashRoom.width / 2, y: deepStashRoom.y + deepStashRoom.height / 2 }) : null;
  const roomHoldBreach = roomHold?.breach;
  const followThroughBreach = followThroughRoom?.breach;
  const deepStashBreach = deepStashRoom?.breach;
  const roomIdentity = getFrontlineRoomIdentityProfile(raidController.state.activeRouteId, 0);

  if (
    !outerBreach?.breach ||
    !outerDoorway ||
    !roomHold ||
    !roomDoorway ||
    !roomHoldBreach ||
    !followThroughRoom ||
    !followThroughDoorway ||
    !followThroughBreach ||
    !deepStashRoom ||
    !deepStashDoorway ||
    !deepStashBreach
  ) {
    updateUi();
    return;
  }

  const outerBreachProfile = outerBreach.breach!;
  const widenedDoorwayWidth = outerBreachProfile.widenedDoorwayWidth ?? (outerDoorway?.width ?? 0);
  outerBreach.doorways = (outerBreach.doorways ?? []).map((doorway, doorwayIndex) =>
    doorwayIndex === 0
      ? {
          ...doorway,
          width: Math.max(doorway.width, widenedDoorwayWidth),
          depth: Math.max(doorway.depth ?? 0, widenedDoorwayWidth * 0.72)
        }
      : doorway
  );
  outerBreach.breach = {
    ...outerBreachProfile,
    breached: true
  };
  outerBreach.label = `${outerBreachProfile.label} // open mouth`;
  raidController.state.activeObstacleBreach = null;
  raidController.state.focusedFrontlineIncidentId = null;
  raidController.state.player.position = {
    x: roomHold.x + roomHold.width * 0.28,
    y: roomHold.y + roomHold.height * 0.54
  };
  raidController.state.player.facing =
    roomDoorway.side === "left"
      ? { x: -1, y: 0 }
      : roomDoorway.side === "right"
        ? { x: 1, y: 0 }
        : roomDoorway.side === "top"
          ? { x: 0, y: -1 }
          : { x: 0, y: 1 };
  raidController.state.activeObstacleBreach = {
    obstacleId: roomHold.id,
    duration: roomHoldBreach.duration,
    timer: Math.max(0.8, roomHoldBreach.duration * 0.82)
  };
  roomHold.doorways = (roomHold.doorways ?? []).map((doorway) =>
    doorway === roomDoorway
      ? {
          ...doorway,
          width: Math.max(doorway.width, roomHoldBreach.widenedDoorwayWidth),
          depth: Math.max(doorway.depth ?? 0, roomHoldBreach.widenedDoorwayWidth * 0.72)
        }
      : doorway
  );
  roomHold.breach = {
    ...roomHoldBreach,
    breached: true
  };
  roomHold.label = roomIdentity.roomCaptureLabel;
  followThroughRoom.doorways = (followThroughRoom.doorways ?? []).map((doorway) =>
    doorway === followThroughDoorway
      ? {
          ...doorway,
          width: Math.max(doorway.width, followThroughBreach.widenedDoorwayWidth),
          depth: Math.max(doorway.depth ?? 0, followThroughBreach.widenedDoorwayWidth * 0.72)
        }
      : doorway
  );
  followThroughRoom.breach = {
    ...followThroughBreach,
    breached: true
  };
  followThroughRoom.label = roomIdentity.followThroughCaptureLabel;
  deepStashRoom.doorways = (deepStashRoom.doorways ?? []).map((doorway) =>
    doorway === deepStashDoorway
      ? {
          ...doorway,
          width: Math.max(doorway.width, deepStashBreach.widenedDoorwayWidth),
          depth: Math.max(doorway.depth ?? 0, deepStashBreach.widenedDoorwayWidth * 0.72)
        }
      : doorway
  );
  deepStashRoom.breach = {
    ...deepStashBreach,
    breached: true
  };
  deepStashRoom.label = roomIdentity.deepCaptureLabel;
  const followThroughDoorwayCenter = getDoorwayCenterPoint(followThroughRoom, followThroughDoorway);
  const followThroughShowcaseHold = {
    x: Phaser.Math.Clamp(
      Phaser.Math.Linear(followThroughDoorwayCenter.x, followThroughRoom.x + followThroughRoom.width / 2, 0.82),
      followThroughRoom.x + 22,
      followThroughRoom.x + followThroughRoom.width - 22
    ),
    y: Phaser.Math.Clamp(
      Phaser.Math.Linear(followThroughDoorwayCenter.y, followThroughRoom.y + followThroughRoom.height / 2, 0.82),
      followThroughRoom.y + 22,
      followThroughRoom.y + followThroughRoom.height - 22
    )
  };
  raidController.state.activeObstacleBreach = null;
  raidController.state.player.position = followThroughShowcaseHold;
  raidController.state.player.facing = Phaser.Math.Distance.Between(
    followThroughShowcaseHold.x,
    followThroughShowcaseHold.y,
    deepStashRoom.x + deepStashRoom.width / 2,
    deepStashRoom.y + deepStashRoom.height / 2
  ) > 0
    ? {
        x:
          (deepStashRoom.x + deepStashRoom.width / 2 - followThroughShowcaseHold.x) /
          Phaser.Math.Distance.Between(
            followThroughShowcaseHold.x,
            followThroughShowcaseHold.y,
            deepStashRoom.x + deepStashRoom.width / 2,
            deepStashRoom.y + deepStashRoom.height / 2
          ),
        y:
          (deepStashRoom.y + deepStashRoom.height / 2 - followThroughShowcaseHold.y) /
          Phaser.Math.Distance.Between(
            followThroughShowcaseHold.x,
            followThroughShowcaseHold.y,
            deepStashRoom.x + deepStashRoom.width / 2,
            deepStashRoom.y + deepStashRoom.height / 2
          )
      }
    : { x: 1, y: 0 };
  raidController.state.player.frontlineMomentumTimer = 14;
  raidController.state.player.frontlineMomentumDuration = 14;
  raidController.state.player.frontlineMomentumLabel = roomIdentity.deepCaptureLabel;
  raidController.state.player.frontlineMomentumSummary =
    `${roomIdentity.roomCaptureLabel}, ${roomIdentity.followThroughCaptureLabel}, and ${roomIdentity.deepCaptureLabel} are live while the stack stays yours.`;
  raidController.state.player.frontlineMomentumSpreadMultiplier = 0.8;
  raidController.state.player.frontlineMomentumMoveMultiplier = 1.08;
  raidController.state.player.health = raidController.state.player.maxHealth;
  raidController.state.player.medkits = Math.max(raidController.state.player.medkits, 2);

  const roomLockerPosition = {
    x: roomHold.x + roomHold.width * 0.66,
    y: roomHold.y + roomHold.height * 0.62
  };
  const followThroughCachePosition = {
    x: followThroughRoom.x + followThroughRoom.width * 0.68,
    y: followThroughRoom.y + followThroughRoom.height * 0.42
  };
  const deepStashCachePosition = {
    x: deepStashRoom.x + deepStashRoom.width * 0.58,
    y: deepStashRoom.y + deepStashRoom.height * 0.54
  };
  raidController.state.supplyCaches = raidController.state.supplyCaches.filter(
    (cache) =>
      Phaser.Math.Distance.Between(cache.position.x, cache.position.y, roomLockerPosition.x, roomLockerPosition.y) > 72 &&
      Phaser.Math.Distance.Between(cache.position.x, cache.position.y, followThroughCachePosition.x, followThroughCachePosition.y) > 72 &&
      Phaser.Math.Distance.Between(cache.position.x, cache.position.y, deepStashCachePosition.x, deepStashCachePosition.y) > 72
  );
  raidController.state.supplyCaches.push({
    id: raidController.state.supplyCaches.reduce((highest, cache) => Math.max(highest, cache.id), 0) + 1,
    position: roomLockerPosition,
    kind: "locker",
    label: roomIdentity.roomCacheLabel,
    demandCategory: roomIdentity.roomDemand,
    searched: false,
    searchDuration: 1.35,
    rewardCredits: 120,
    medkitReward: 1,
    ammoReward: 16,
    stashReward: { medkits: 1, ammoPacks: 1 },
    opportunityId: null,
    opportunitySummary: null,
    frontlineDrop: true,
    frontlineDropSourceLabel: "Open room hold 1.1"
  });
  raidController.state.supplyCaches.push({
    id: raidController.state.supplyCaches.reduce((highest, cache) => Math.max(highest, cache.id), 0) + 1,
    position: followThroughCachePosition,
    kind: "ammo",
    label: roomIdentity.followThroughCacheLabel,
    demandCategory: roomIdentity.followThroughDemand,
    searched: false,
    searchDuration: 1.45,
    rewardCredits: 155,
    medkitReward: 1,
    ammoReward: 24,
    stashReward: { medkits: 1, ammoPacks: 2 },
    opportunityId: null,
    opportunitySummary: null,
    frontlineDrop: true,
    frontlineDropSourceLabel: "Open room hold 1.2"
  });
  raidController.state.supplyCaches.push({
    id: raidController.state.supplyCaches.reduce((highest, cache) => Math.max(highest, cache.id), 0) + 1,
    position: deepStashCachePosition,
    kind: "locker",
    label: roomIdentity.deepCacheLabel,
    demandCategory: roomIdentity.deepDemand,
    searched: false,
    searchDuration: 1.55,
    rewardCredits: 190,
    medkitReward: 2,
    ammoReward: 32,
    stashReward: { medkits: 2, ammoPacks: 2 },
    opportunityId: null,
    opportunitySummary: null,
    frontlineDrop: true,
    frontlineDropSourceLabel: "Open room hold 1.3"
  });

  const nearbyEnemies = raidController.state.enemies
    .slice()
    .sort(
      (left, right) =>
        Phaser.Math.Distance.Between(left.position.x, left.position.y, roomHold.x + roomHold.width / 2, roomHold.y + roomHold.height / 2) -
        Phaser.Math.Distance.Between(right.position.x, right.position.y, roomHold.x + roomHold.width / 2, roomHold.y + roomHold.height / 2)
    )
    .slice(0, 7);

  nearbyEnemies.forEach((enemy, index) => {
    const stagedArchetypeId =
      index < 2
        ? roomIdentity.defenderArchetypeId
        : index === 2
          ? roomIdentity.followThroughDefenderArchetypeId
          : index === 3
            ? roomIdentity.deepDefenderArchetypeId
            : index === 4
              ? roomIdentity.reserveDefenderArchetypeId
              : index === 5
                ? roomIdentity.followThroughReserveDefenderArchetypeId
                : roomIdentity.deepReserveDefenderArchetypeId;
    const roomDepth = index < 2 ? 1 : index === 2 ? 2 : 3;
    const roomSlotIndex = index < 2 ? index : index === 2 ? 0 : index === 3 ? 0 : index === 4 ? 1 : index === 5 ? 1 : 2;
    const reserveEnemy = index >= 4;
    const stagedLoadout = getFrontlineRoomCombatantLoadout(stagedArchetypeId, roomDepth, roomSlotIndex, reserveEnemy);
    enemy.alert = true;
    enemy.archetypeId = stagedArchetypeId;
    enemy.weaponId = stagedLoadout.weaponId;
    enemy.tapeId = stagedLoadout.tapeId;
    enemy.awareness = "engaged";
    enemy.position =
      index < 2
        ? {
            x: roomHold.x + roomHold.width * (0.66 + index * 0.12),
            y: roomHold.y + roomHold.height * (0.24 + index * 0.38)
          }
        : index === 2
          ? {
              x: followThroughRoom.x + followThroughRoom.width * 0.82,
              y: followThroughRoom.y + followThroughRoom.height * 0.22
            }
          : index === 3
            ? {
              x: deepStashRoom.x + deepStashRoom.width * 0.52,
              y: deepStashRoom.y + deepStashRoom.height * 0.56
              }
            : index === 4
              ? {
                  x: roomHold.x + roomHold.width * 0.28,
                  y: roomHold.y + roomHold.height * 0.72
                }
              : index === 5
                ? {
                    x: followThroughRoom.x + followThroughRoom.width * 0.34,
                    y: followThroughRoom.y + followThroughRoom.height * 0.28
                  }
                : {
                    x: deepStashRoom.x + deepStashRoom.width * 0.7,
                    y: deepStashRoom.y + deepStashRoom.height * 0.32
                  };
    const immediatePlayerDistance = Phaser.Math.Distance.Between(
      enemy.position.x,
      enemy.position.y,
      raidController.state.player.position.x,
      raidController.state.player.position.y
    );
    enemy.facing =
      index < 2
        ? { x: -0.98, y: 0.16 }
        : immediatePlayerDistance > 0
          ? {
              x: (raidController.state.player.position.x - enemy.position.x) / immediatePlayerDistance,
              y: (raidController.state.player.position.y - enemy.position.y) / immediatePlayerDistance
            }
          : { x: -1, y: 0 };
    enemy.investigateTarget =
      index < 2
        ? { x: roomHold.x + roomHold.width * 0.48, y: roomHold.y + roomHold.height * 0.52 }
        : index === 2
          ? { x: deepStashRoom.x + deepStashRoom.width * 0.44, y: deepStashRoom.y + deepStashRoom.height * 0.48 }
          : { ...raidController.state.player.position };
    enemy.investigateTimer = index < 2 ? 3.4 : index === 2 ? 1.6 : 2.8;
    enemy.cooldown = Math.max(enemy.cooldown, stagedLoadout.weaponId === "shotgun" ? 0.46 : index === 2 ? 1.05 : index < 2 ? 0.82 : 0.55);
  });

  raidController.state.frontlineSupports.forEach((support, index) => {
    if (support.kind !== "fireteam") {
      return;
    }

    const coverX =
      index === 0
        ? roomHold.x + roomHold.width * 0.34
        : index === 1
          ? followThroughRoom.x + followThroughRoom.width * 0.34
          : deepStashRoom.x + deepStashRoom.width * 0.34;
    const coverY =
      index === 0
        ? roomHold.y + roomHold.height * 0.36
        : index === 1
          ? followThroughRoom.y + followThroughRoom.height * 0.58
          : deepStashRoom.y + deepStashRoom.height * 0.52;
    support.anchor = { x: coverX, y: coverY };
    support.target = { x: coverX, y: coverY };
    support.status = index === 0 ? "covering" : "holding";
    support.contactTimer = Math.max(support.contactTimer, index === 0 ? 1.6 : 1.2);
    support.pushTimer = Math.max(support.pushTimer, index === 0 ? 1.5 : index === 1 ? 1.15 : 1);
    support.breachFootholdTimer = Math.max(support.breachFootholdTimer, 6.8);
    support.breachFootholdObstacleId = index === 0 ? roomHold.id : index === 1 ? followThroughRoom.id : deepStashRoom.id;
    support.footholdLabel = index === 0 ? "Captured breach room" : index === 1 ? "Follow-through foothold" : "Deep stash foothold";
    support.footholdSummary =
      index === 0
        ? "The opened room now pays out as a live foothold with exposed loot and chained room-side cover."
        : index === 1
          ? "The second room turns the breach into real depth, with a deeper cache and a back-angle firing line."
          : "The third room finally cashes out as a deep stash pull, with a rear-angle hold and the highest-value interior loot.";
    support.note =
      index === 0
        ? `${support.label} is inside the captured room, pinning the next angle from hard cover while the locker gets stripped.`
        : index === 1
          ? `${support.label} is inside the follow-through room, holding the deeper angle so the chain reads like gained interior ground.`
          : `${support.label} is inside the deep stash room, locking the rear angle so the stack reads like a full interior takeover.`;
  });

  const additionalInteriorEnemy = raidController.state.enemies
    .slice()
    .sort(
      (left, right) =>
        Phaser.Math.Distance.Between(
          left.position.x,
          left.position.y,
          followThroughRoom.x + followThroughRoom.width / 2,
          followThroughRoom.y + followThroughRoom.height / 2
        ) -
        Phaser.Math.Distance.Between(
          right.position.x,
          right.position.y,
          followThroughRoom.x + followThroughRoom.width / 2,
          followThroughRoom.y + followThroughRoom.height / 2
        )
    )[3];

  if (additionalInteriorEnemy) {
    additionalInteriorEnemy.archetypeId = roomIdentity.deepDefenderArchetypeId;
    additionalInteriorEnemy.squadRole = "deep-rifle";
    const additionalLoadout = getFrontlineRoomCombatantLoadout(roomIdentity.deepDefenderArchetypeId, 3, 1);
    additionalInteriorEnemy.weaponId = additionalLoadout.weaponId;
    additionalInteriorEnemy.tapeId = additionalLoadout.tapeId;
    additionalInteriorEnemy.alert = true;
    additionalInteriorEnemy.awareness = "engaged";
    additionalInteriorEnemy.position = {
      x: deepStashRoom.x + deepStashRoom.width * 0.34,
      y: deepStashRoom.y + deepStashRoom.height * 0.34
    };
    additionalInteriorEnemy.facing = { x: -0.9, y: 0.16 };
    additionalInteriorEnemy.investigateTarget = { ...raidController.state.player.position };
    additionalInteriorEnemy.investigateTimer = 3.2;
  }
  raidController.state.enemies
    .filter((enemy) => enemy.squadRole === "deep-rifle")
    .sort(
      (left, right) =>
        Phaser.Math.Distance.Between(left.position.x, left.position.y, deepStashRoom.x + deepStashRoom.width / 2, deepStashRoom.y + deepStashRoom.height / 2) -
        Phaser.Math.Distance.Between(right.position.x, right.position.y, deepStashRoom.x + deepStashRoom.width / 2, deepStashRoom.y + deepStashRoom.height / 2)
    )
    .slice(0, 3)
    .forEach((enemy) => {
      enemy.casualtyState = "downed";
      enemy.health = 0;
      enemy.bleedoutTimer = Math.max(enemy.bleedoutTimer, 12);
      enemy.stabilized = false;
    });
  raidController.state.enemies
    .filter(
      (enemy) =>
        enemy.casualtyState !== "downed" &&
        enemy.casualtyState !== "dead" &&
        (enemy.squadRole === "anchor-rifle" || enemy.squadRole === "deep-rifle" || enemy.squadRole === "support-gunner")
    )
    .forEach((enemy, index) => {
      enemy.alert = true;
      enemy.awareness = "engaged";
      enemy.investigateTarget = { ...raidController.state.player.position };
      enemy.investigateTimer = Math.max(enemy.investigateTimer, 3);
      enemy.compressionTimer = Math.max(enemy.compressionTimer, enemy.squadRole === "deep-rifle" ? 3.8 : enemy.squadRole === "support-gunner" ? 3.2 : 2.6);
      enemy.compressionState = index < 2 ? "compressed" : "compressing";
    });

  raidController.state.currentDialogueEvent = {
    id: "debug-room-clear-contact",
    kind: "contact",
    locationLabel: roomIdentity.authoredSetLabel,
    extractLabel: raidController.state.extractZones[0]?.label ?? "Freight peel",
    breachLabel: roomIdentity.followThroughCaptureLabel,
    intensity: "high",
    dominantTapeId: "blue",
    playerCritical: false,
    greedPressure: 0.24,
    memoryTags: ["sector-held"]
  };
  raidController.state.recentDialogueEvents = [raidController.state.currentDialogueEvent];
  raidController.state.currentHostileDialogueEvent = {
    id: "debug-room-clear-hostile-compress",
    kind: "contact",
    locationLabel: roomIdentity.authoredSetLabel,
    extractLabel: raidController.state.extractZones[0]?.label ?? "Freight peel",
    breachLabel: roomIdentity.deepCaptureLabel,
    intensity: "medium",
    dominantTapeId: "blue",
    playerCritical: false,
    greedPressure: 0.18,
    memoryTags: ["sector-held"]
  };
  raidController.state.recentHostileDialogueEvents = [raidController.state.currentHostileDialogueEvent];
  raidController.state.squadComms = {
    speaker: "Sable",
    role: "Entry lead",
    voiceTag: "Close pressure",
    tone: "critical",
    channel: "Boys net",
    line: "Lane gun is cut. Room one is ours, but they compressed deeper and room two is still live."
  };
  raidController.state.squadLog = [
    {
      id: 1,
      speaker: "Sable",
      role: "Entry lead",
      voiceTag: "Close pressure",
      tone: "critical",
      channel: "Boys net",
      line: "Lane gun is cut. Room one is ours, but they compressed deeper and room two is still live.",
      stamp: "Room clear"
    }
  ];
  raidController.state.hostileComms = {
    speaker: "Blue Sergeant",
    role: "Line regulars",
    tapeId: "blue",
    tone: "warning",
    channel: "Blue Net",
    line: "Settle deeper. Back room still live. Make them clear every doorway."
  };
  raidController.state.hostileLog = [
    {
      id: 1,
      speaker: "Blue Sergeant",
      role: "Line regulars",
      tapeId: "blue",
      tone: "warning",
      channel: "Blue Net",
      line: "Settle deeper. Back room still live. Make them clear every doorway.",
      stamp: "Room clear"
    }
  ];

  raidController.state.message =
    `${roomIdentity.authoredSetLabel} staged: ${roomIdentity.roomCaptureLabel}, ${roomIdentity.followThroughCaptureLabel}, and ${roomIdentity.deepCaptureLabel} are open, the surviving defenders have compressed inward, and room two is softer but still not solved.`;
  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

function stageDebugFrontlineSupplyShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("sundered-run");
    raidController.setSelectedWeapon("rifle");
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );
  const convoyIncident = raidController.state.frontlineIncidents.find((incident) => incident.kind === "convoy" && !incident.resolved);
  const casualtyIncident = raidController.state.frontlineIncidents.find((incident) => incident.kind === "casualty" && !incident.resolved);
  const convoySupport = raidController.state.frontlineSupports.find((support) => support.kind === "convoy");
  const recoverySupport = raidController.state.frontlineSupports.find((support) => support.kind === "recovery");
  const escortSupport =
    raidController.state.frontlineSupports.find((support) => support.kind === "fireteam" && support.playerEscort) ??
    raidController.state.frontlineSupports.find((support) => support.kind === "fireteam") ??
    null;
  const firefightIncident =
    raidController.state.frontlineIncidents.find((incident) => incident.kind === "firefight" && !incident.resolved) ?? null;

  if (activeSector) {
    activeSector.control = "contested";
    activeSector.pressure = 79;
    activeSector.scars = 83;
    activeSector.routeModifierTitle = "Relief convoy kill lane";
    activeSector.routeModifierSummary =
      "A relief truck is hung in the burned corridor with loose ammo, smoke, and a stripping window, so the route reads like a real logistics ambush instead of one abstract support icon.";
    activeSector.activeEvent =
      `${activeSector.routeName} is carrying one stalled relief truck, one loose pallet, and a half-screened strip window while the boys try to keep the kill lane from hardening again.`;
    activeSector.watch = "Strip the relief haul fast, use the ammo surge, and leave before the corridor closes back into a burned convoy graveyard.";
  }

  if (convoyIncident) {
    convoyIncident.status = "engaged";
    convoyIncident.resolved = false;
    convoyIncident.contactTimer = 1.4;
    convoyIncident.resupplyTimer = 0.95;
    convoyIncident.actionVerb = "strip";
    convoyIncident.opportunityLabel = "Strip the relief haul before the kill lane seals";
    convoyIncident.interactDuration = 1.8;
    convoyIncident.note =
      `${convoyIncident.label} is pinned in the burned corridor, one truck is hanging open, and a loose relief pallet is still close enough to strip under fire.`;
    convoyIncident.strength = Math.max(convoyIncident.strength, 4);
  }

  if (casualtyIncident) {
    casualtyIncident.status = "extracting";
    casualtyIncident.contactTimer = 0.9;
    casualtyIncident.resupplyTimer = 0.8;
    casualtyIncident.note = `${casualtyIncident.label} is dragging farther off the road while the convoy strip carries the real pressure in this corridor.`;
  }

  if (firefightIncident) {
    firefightIncident.status = "collapsing";
    firefightIncident.contactTimer = Math.max(firefightIncident.contactTimer, 1.15);
    firefightIncident.note =
      `${firefightIncident.label} is still spitting over the road cut, keeping the relief truck window tense instead of safe.`;
  }

  if (convoySupport && convoyIncident) {
    convoySupport.position = {
      x: convoyIncident.position.x - 52,
      y: convoyIncident.position.y + 24
    };
    convoySupport.target = { ...convoyIncident.position };
    convoySupport.status = "covering";
    convoySupport.contactTimer = Math.max(convoySupport.contactTimer, 1.1);
    convoySupport.resupplyTimer = 0.9;
    convoySupport.resupplyTargetId = raidController.state.frontlineSupports.find((support) => support.kind === "fireteam")?.id ?? null;
    convoySupport.note = `${convoySupport.label} is screening the hung relief truck while the loose pallet and open doors stay readable from the lane.`;
  }

  if (recoverySupport && casualtyIncident) {
    recoverySupport.position = {
      x: casualtyIncident.position.x - 54,
      y: casualtyIncident.position.y + 22
    };
    recoverySupport.target = { ...casualtyIncident.position };
    recoverySupport.status = "holding";
    recoverySupport.resupplyTimer = 0.8;
    recoverySupport.note = `${recoverySupport.label} is carrying aid forward and the satchel drop is still stealable.`;
  }

  if (escortSupport && convoyIncident) {
    escortSupport.position = {
      x: convoyIncident.position.x + 66,
      y: convoyIncident.position.y - 30
    };
    escortSupport.target = {
      x: convoyIncident.position.x + 132,
      y: convoyIncident.position.y - 56
    };
    escortSupport.status = "covering";
    escortSupport.contactTimer = Math.max(escortSupport.contactTimer, 1.25);
    escortSupport.breachFootholdTimer = Math.max(escortSupport.breachFootholdTimer, 1.8);
    escortSupport.footholdLabel = "Relief cut screen";
    escortSupport.footholdSummary =
      "The boys are screening the stalled truck and loose crate so the convoy strip reads like a real under-fire logistics steal instead of a detached pickup.";
    escortSupport.note = `${escortSupport.label} is covering the truck lane and calling the loose pallet while rounds keep crossing the road cut.`;
  }

  if (convoyIncident) {
    const reliefCrateLabel = `${convoyIncident.label} Relief Crate`;
    const existingReliefCrate = raidController.state.supplyCaches.find((cache) => cache.label === reliefCrateLabel);
    if (!existingReliefCrate) {
      raidController.state.supplyCaches.push({
        id: raidController.state.supplyCaches.reduce((highest, cache) => Math.max(highest, cache.id), 0) + 1,
        position: {
          x: convoyIncident.position.x + 34,
          y: convoyIncident.position.y + 18
        },
        kind: "ammo",
        label: reliefCrateLabel,
        demandCategory: "munitions",
        searched: false,
        searchDuration: 1.35,
        rewardCredits: 95,
        medkitReward: 0,
        ammoReward: 26,
        stashReward: { medkits: 0, ammoPacks: 1 },
        opportunityId: null,
        opportunitySummary: null,
        frontlineDrop: true,
        frontlineDropSourceLabel: convoyIncident.label
      });
    }
  }

  if (casualtyIncident) {
    const aidSatchelLabel = `${casualtyIncident.label} Aid Satchel`;
    const existingAidSatchel = raidController.state.supplyCaches.find((cache) => cache.label === aidSatchelLabel);
    if (!existingAidSatchel) {
      raidController.state.supplyCaches.push({
        id: raidController.state.supplyCaches.reduce((highest, cache) => Math.max(highest, cache.id), 0) + 1,
        position: {
          x: casualtyIncident.position.x - 30,
          y: casualtyIncident.position.y + 20
        },
        kind: "medical",
        label: aidSatchelLabel,
        demandCategory: "medical",
        searched: false,
        searchDuration: 1.35,
        rewardCredits: 55,
        medkitReward: 1,
        ammoReward: 0,
        stashReward: { medkits: 1, ammoPacks: 0 },
        opportunityId: null,
        opportunitySummary: null,
        frontlineDrop: true,
        frontlineDropSourceLabel: casualtyIncident.label
      });
    }
  }

  if (convoyIncident) {
    raidController.state.focusedFrontlineIncidentId = convoyIncident.id;
    raidController.state.player.position = {
      x: convoyIncident.position.x - 102,
      y: convoyIncident.position.y + 58
    };
    raidController.state.player.facing = { x: 0.94, y: -0.24 };
    raidController.state.activeFrontlineIncidentAction = {
      incidentId: convoyIncident.id,
      duration: convoyIncident.interactDuration,
      timer: Math.max(0.7, convoyIncident.interactDuration * 0.52),
      verb: "strip"
    };
  }

  raidController.state.soundPressure = Math.max(raidController.state.soundPressure, 0.92);
  raidController.state.noiseResponseLevel = Math.max(raidController.state.noiseResponseLevel, 1);
  raidController.state.player.frontlineMomentumTimer = 14;
  raidController.state.player.frontlineMomentumDuration = 14;
  raidController.state.player.frontlineMomentumLabel = "Supply surge";
  raidController.state.player.frontlineMomentumSummary = "The hung relief truck just opened one sharp ammo-fed shove window.";
  raidController.state.player.frontlineMomentumSpreadMultiplier = 0.86;
  raidController.state.player.frontlineMomentumMoveMultiplier = 1.1;
  raidController.state.message =
    "Frontline supply staged: the relief truck is hung open in the kill lane, the strip window is live, and the next shove is being fed off stolen ammo.";

  raidHudState.tacticalDrawerOpen = false;
  updateUi();
}

