function stageDebugExpandedFrontlineShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("crosswind-docks");
  }

  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );

  if (activeSector) {
    activeSector.control = "contested";
    activeSector.pressure = 84;
    activeSector.fortification = 54;
    activeSector.scars = 81;
    activeSector.routeModifierTitle = "Expanded district frontage";
    activeSector.routeModifierSummary =
      "More pockets are live at once, with the fight stretched across the district so the route reads like a broader live frontline instead of one narrow authored lane.";
    activeSector.enemyReduction = 0;
    activeSector.extractionHoldMultiplier = 1.22;
    activeSector.noiseMultiplier = 1.18;
    activeSector.activeEvent = `${activeSector.routeName} is running with a longer visible frontage, extra fallback pockets, and more live bodies spread across the district.`;
    activeSector.watch = "Three added pockets are hot, the far lane is no longer quiet, and the route now reads as a multi-block push.";
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const route = raidController.getActiveRoute();
  const firefights = raidController.state.frontlineIncidents.filter((incident) => incident.kind === "firefight");
  const fireteams = raidController.state.frontlineSupports.filter((support) => support.kind === "fireteam");
  const supportSeed = raidController.state.frontlineSupports.reduce(
    (highest, entry) => Math.max(highest, entry.id),
    0
  );
  const incidentSeed = raidController.state.frontlineIncidents.reduce(
    (highest, entry) => Math.max(highest, entry.id),
    0
  );
  const extraIncidentTemplates = firefights.slice(0, 5).map((incident, index) => ({
    ...incident,
    id: incidentSeed + index + 1,
      position: {
        x: incident.position.x + 1560 + index * 720,
        y: incident.position.y + (index % 2 === 0 ? -620 : 560)
      },
      anchor: {
        x: incident.anchor.x + 1560 + index * 720,
        y: incident.anchor.y + (index % 2 === 0 ? -620 : 560)
      },
      target: {
        x: incident.target.x + 1560 + index * 720,
        y: incident.target.y + (index % 2 === 0 ? -620 : 560)
      },
    label: `${incident.label} flank ${index + 2}`,
    note: `${incident.label} has a farther contact lane stretching the frontline wider.`,
    strength: Math.max(incident.strength, 7),
    status: "engaged" as const,
    territoryState: "breaking" as const,
    territoryNote: `${incident.label} flank ${index + 2} is still reading hot from a wider push.`
  }));
  const extraSupportTemplates = fireteams.slice(0, 5).map((support, index) => ({
    ...support,
    id: supportSeed + index + 1,
      position: {
        x: support.position.x + 1480 + index * 680,
        y: support.position.y + (index % 2 === 0 ? 440 : -440)
      },
      anchor: {
        x: support.anchor.x + 1480 + index * 680,
        y: support.anchor.y + (index % 2 === 0 ? 440 : -440)
      },
      target: {
        x: support.target.x + 1480 + index * 680,
        y: support.target.y + (index % 2 === 0 ? 440 : -440)
      },
    label: `${support.label} flank ${index + 2}`,
    note: `${support.label} has a second lane covering the wider district frontage.`,
    strength: Math.max(support.strength, 6),
    status: "covering" as const
  }));

  raidController.state.frontlineIncidents.push(...extraIncidentTemplates);
  raidController.state.frontlineSupports.push(...extraSupportTemplates);

  firefights.forEach((incident, index) => {
    incident.position = {
      x: incident.position.x + index * 420,
      y: incident.position.y + (index % 2 === 0 ? -160 : 160)
    };
    incident.anchor = {
      x: incident.anchor.x + index * 420,
      y: incident.anchor.y + (index % 2 === 0 ? -160 : 160)
    };
    incident.target = {
      x: incident.target.x + index * 420,
      y: incident.target.y + (index % 2 === 0 ? -160 : 160)
    };
    incident.status = index >= 1 ? "engaged" : incident.status;
    incident.contactTimer = Math.max(incident.contactTimer, 0.8 + (index % 3) * 0.35);
    incident.strength = Math.max(incident.strength, index >= 4 ? 7 : 6);
    incident.territoryState = index >= 4 ? "breaking" : index === 0 ? "reclaimed" : incident.territoryState;
    incident.territoryNote =
      index >= 4
        ? `${incident.label} is still burning and keeps the added frontage visibly contested.`
        : incident.territoryState === "reclaimed"
          ? `${incident.label} has friendlies on the scar, but the neighboring pockets are still active.`
          : incident.territoryNote;
  });

  raidController.state.frontlineSupports.forEach((support, index) => {
    if (support.kind === "fireteam") {
      support.position = {
        x: support.position.x + index * 380,
        y: support.position.y + (index % 2 === 0 ? -148 : 148)
      };
      support.anchor = {
        x: support.anchor.x + index * 380,
        y: support.anchor.y + (index % 2 === 0 ? -148 : 148)
      };
      support.target = {
        x: support.target.x + index * 380,
        y: support.target.y + (index % 2 === 0 ? -148 : 148)
      };
      support.status = index >= 1 ? "covering" : "holding";
      support.contactTimer = Math.max(support.contactTimer, 0.7 + (index % 3) * 0.25);
      support.pushTimer = index >= 2 ? Math.max(support.pushTimer, 0.9) : support.pushTimer;
      support.strength = Math.max(support.strength, index >= 3 ? 6 : 5);
      support.note =
        index >= 2
          ? `${support.label} is helping hold one of the added route pockets so the district reads like a real layered push.`
          : support.note;
      return;
    }

    support.status = "moving";
    support.contactTimer = Math.max(support.contactTimer, 0.35);
  });

  const focusIncident = firefights[Math.min(4, firefights.length - 1)] ?? firefights[0] ?? null;
  if (focusIncident) {
    raidController.state.focusedFrontlineIncidentId = focusIncident.id;
    raidController.state.player.position = {
      x: focusIncident.position.x - 180,
      y: focusIncident.position.y + 110
    };
  }

  const russianBodies = raidController.state.frontlineSupports.reduce((sum, support) => sum + support.strength, 0) + 1;
  const ukrainianBodies = raidController.state.frontlineIncidents.reduce((sum, incident) => sum + incident.strength, 0);
  raidController.state.message = `Expanded frontage live: ${route.combatPockets.length} pockets, ${raidController.state.frontlineSupports.filter((support) => support.kind === "fireteam").length} friendly teams, and ${russianBodies + ukrainianBodies} visible frontline bodies are active across the district.`;
  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

