function stageDebugWarBeatFocusShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("crosswind-docks");
    raidController.setSelectedWeapon("smg");
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );
  const convoy = raidController.state.frontlineIncidents.find((incident) => incident.kind === "convoy") ?? null;
  const casualty = raidController.state.frontlineIncidents.find((incident) => incident.kind === "casualty") ?? null;
  const firefight = raidController.state.frontlineIncidents.find((incident) => incident.kind === "firefight") ?? null;

  if (activeSector) {
    activeSector.control = "contested";
    activeSector.pressure = 77;
    activeSector.scars = 72;
    activeSector.routeModifierTitle = "Living war beats";
    activeSector.routeModifierSummary =
      "Convoys, casualty drags, and breaking scar pockets are all asking for attention at once, so the route reads like a wider living front instead of one abstract firefight.";
    activeSector.activeEvent = `${activeSector.routeName} is spitting simultaneous relief, casualty, and scar calls over the same district push.`;
    activeSector.watch = "Pick the war beat worth bending the boys around, then leave before the lane pays you back.";
  }

  if (convoy) {
    convoy.status = "extracting";
    convoy.resolved = false;
    convoy.opportunityLabel = "Strip the relief crate";
    convoy.note = `${convoy.label} is trying to slide a taped relief crate through the lane while Blue eyes stay on the scar pocket.`;
    convoy.strength = Math.max(convoy.strength, 4);
  }

  if (casualty) {
    casualty.status = "sweeping";
    casualty.resolved = false;
    casualty.opportunityLabel = "Recover the wounded bag";
    casualty.note = `${casualty.label} is dragging wounded through the gutter and leaves a medical satchel if you cut the lane cleanly.`;
    casualty.strength = Math.max(casualty.strength, 3);
  }

  if (firefight) {
    firefight.status = "collapsing";
    firefight.resolved = false;
    firefight.territoryState = "breaking";
    firefight.markerState = "raising";
    firefight.actionVerb = "plant";
    firefight.opportunityLabel = "Plant the route flag";
    firefight.markerNote = "The boys can still lock this scar before it slips back over to Blue.";
    firefight.territoryNote = `${firefight.label} is hanging in the balance and still needs one more shove to stay yours.`;
    firefight.note = `${firefight.label} is half-held and still pulling eyes off the nearby convoy lane.`;
    firefight.strength = Math.max(firefight.strength, 5);
  }

  const focusedIncident = convoy ?? casualty ?? firefight;
  if (focusedIncident) {
    raidController.state.focusedFrontlineIncidentId = focusedIncident.id;
    raidController.state.player.position = {
      x: focusedIncident.position.x - 96,
      y: focusedIncident.position.y + 64
    };
  }

  raidController.state.activeFrontlineIncidentAction = null;
  raidController.state.frontlineIncidentExtractRelief = 0;
  raidController.state.soundPressure = Math.max(raidController.state.soundPressure, 0.64);
  raidController.state.noiseResponseLevel = Math.max(raidController.state.noiseResponseLevel, 1);
  raidController.state.message =
    "War beat focus staged: a relief convoy, casualty drag, and breaking scar are all live, with the convoy pulled into the primary HUD focus.";
  raidHudState.tacticalDrawerOpen = false;
  updateUi();
}

