function stageDebugExtractPressureShowcase(mode: "clean" | "collapse" = "collapse"): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("broken-signal");
    raidController.setSelectedWeapon("rifle");
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const route = raidController.getActiveRoute();
  const fallbackExtract = route.extractOptions[1] ?? route.extractOptions[0];

  if (!fallbackExtract) {
    updateUi();
    return;
  }

  raidController.state.intelSites = raidController.state.intelSites.map((site) => ({
    ...site,
    secured: true
  }));
  raidController.state.extractionReady = true;
  raidController.state.activeExtractId = fallbackExtract.id;
  raidController.state.extractZone = {
    position: { ...fallbackExtract.position },
    radius: fallbackExtract.radius
  };
  raidController.state.extractionHoldDuration = mode === "clean" ? 2.5 : 3.1;
  raidController.state.extractionHoldTimer = 0;
  raidController.state.extractionContested = false;
  raidController.state.extractionContesters = 0;
  raidController.state.extractionWaveTriggered = false;
  raidController.state.carriedValue = mode === "clean" ? 226 : 312;
  raidController.state.carriedManifest = {
    intel: 1,
    medical: mode === "clean" ? 0 : 1,
    munitions: mode === "clean" ? 1 : 0,
    hardware: 1
  };
  raidController.state.carriedSupplies = {
    medkits: 1,
    ammoPacks: mode === "clean" ? 1 : 2
  };
  raidController.state.soundPressure = Math.max(raidController.state.soundPressure, mode === "clean" ? 0.24 : 0.92);
  raidController.state.noiseResponseLevel = Math.max(raidController.state.noiseResponseLevel, mode === "clean" ? 0.18 : 0.86);
  raidController.state.player.position = {
    x: fallbackExtract.position.x - fallbackExtract.radius * (mode === "clean" ? 2.18 : 0.38),
    y: fallbackExtract.position.y + fallbackExtract.radius * (mode === "clean" ? 0.22 : 0.12)
  };
  raidController.state.player.facing = { x: 0.98, y: -0.14 };
  raidController.state.player.health = Math.min(raidController.state.player.maxHealth, mode === "clean" ? 78 : 64);
  raidController.state.player.medkits = Math.max(raidController.state.player.medkits, 1);
  raidController.state.player.frontlineMomentumLabel = mode === "clean" ? "Disciplined early peel" : "Queued fallback pull";
  raidController.state.player.frontlineMomentumSummary =
    mode === "clean"
      ? "The route already paid. One early peel stays cleaner than a late crash fight."
      : "The raid is already profitable, multiple pulls are open, and one crash wave is seconds out.";
  raidController.state.pendingReinforcements =
    mode === "clean"
      ? [
          {
            id: 9003,
            source: "noise-response",
            label: "Outer relay sweep",
            briefing: "A wide sweep is starting to turn, but it has not committed to the peel yet.",
            position: {
              x: fallbackExtract.position.x + fallbackExtract.radius * 1.6,
              y: fallbackExtract.position.y - fallbackExtract.radius * 0.82
            },
            archetypeId: "rifleman",
            timer: 18.6,
            duration: 18.6,
            targetPosition: { ...fallbackExtract.position }
          }
        ]
      : [
          {
            id: 9001,
            source: "extraction-wave",
            label: "Relay crash team",
            briefing: "Fresh hostiles are collapsing on the beacon lane.",
            position: {
              x: fallbackExtract.position.x + fallbackExtract.radius * 1.28,
              y: fallbackExtract.position.y - fallbackExtract.radius * 0.46
            },
            archetypeId: "rusher",
            timer: 1.6,
            duration: 1.6,
            targetPosition: { ...fallbackExtract.position }
          },
          {
            id: 9002,
            source: "noise-response",
            label: "North sweep",
            briefing: "A wider sweep is rotating in behind the hold.",
            position: {
              x: fallbackExtract.position.x - fallbackExtract.radius * 1.36,
              y: fallbackExtract.position.y - fallbackExtract.radius * 0.72
            },
            archetypeId: "rifleman",
            timer: 2.8,
            duration: 2.8,
            targetPosition: { ...fallbackExtract.position }
          }
        ];

  const activeSector = raidController.state.frontlineSectors.find((sector) => sector.routeId === route.id) ?? null;
  if (activeSector) {
    if (mode === "clean") {
      activeSector.control = "held";
      activeSector.pressure = 28;
      activeSector.fortification = 58;
      activeSector.scars = 22;
      activeSector.routeModifierTitle = "Disciplined peel lane";
      activeSector.routeModifierSummary =
        "Relay Hamlet is temporarily under control, so the route can prove one clean peel before the district reheats.";
      activeSector.enemyReduction = 0.12;
      activeSector.extractionHoldMultiplier = 0.92;
      activeSector.noiseMultiplier = 0.88;
      activeSector.activeEvent = "Spur screen is still ahead of the wider sweep.";
      activeSector.supportNeed = "Use the clean window and do not spend it on another pocket.";
      activeSector.watch = "Bank the route now and leave before the district gets another vote.";
      activeSector.lastOutcome = "Relay Hamlet is riding one temporary clean pull.";
      activeSector.lastRaidResult = "success";
      activeSector.fallenSquadBodies = [];
      activeSector.fallenEnemyBodies = [];
    } else {
      activeSector.control = "contested";
      activeSector.pressure = Math.max(activeSector.pressure, 63);
      activeSector.routeModifierTitle = "Collapse peel lane";
      activeSector.routeModifierSummary =
        "Relay Hamlet is already bending back over the peel, so the staged exit should read hotter and less screenable.";
      activeSector.activeEvent = "Crash teams and relay reserve are both feeding the pull.";
      activeSector.supportNeed = "Hard-commit the peel before the route closes fully.";
      activeSector.watch = "The district is already clawing back over the chosen pull.";
      activeSector.lastOutcome = "Relay Hamlet is paying, but the peel is already turning into a crash fight.";
      activeSector.lastRaidResult = "failed";
    }
  }

  const extractPressureAnchors =
    mode === "clean"
      ? [
          {
            x: fallbackExtract.position.x + fallbackExtract.radius * 3.18,
            y: fallbackExtract.position.y - fallbackExtract.radius * 1.12
          },
          {
            x: fallbackExtract.position.x - fallbackExtract.radius * 3.02,
            y: fallbackExtract.position.y + fallbackExtract.radius * 1.34
          },
          {
            x: fallbackExtract.position.x + fallbackExtract.radius * 3.62,
            y: fallbackExtract.position.y - fallbackExtract.radius * 0.84
          }
        ]
      : [
          {
            x: fallbackExtract.position.x + fallbackExtract.radius * 0.28,
            y: fallbackExtract.position.y - fallbackExtract.radius * 0.2
          },
          {
            x: fallbackExtract.position.x - fallbackExtract.radius * 0.18,
            y: fallbackExtract.position.y + fallbackExtract.radius * 0.34
          },
          {
            x: fallbackExtract.position.x + fallbackExtract.radius * 0.92,
            y: fallbackExtract.position.y - fallbackExtract.radius * 0.1
          }
        ];

  raidController.state.enemies = raidController.state.enemies.map((enemy, index) => {
    const anchor = extractPressureAnchors[index] ?? {
      x:
        fallbackExtract.position.x +
        fallbackExtract.radius * (mode === "clean" ? 3.24 : 1.72) +
        (index - extractPressureAnchors.length) * 28,
      y:
        fallbackExtract.position.y -
        fallbackExtract.radius * (mode === "clean" ? 0.96 : 0) +
        -64 +
        ((index - extractPressureAnchors.length) % 3) * 52
    };

    return {
      ...enemy,
      position: { ...anchor },
      anchor: { ...anchor },
      target: { ...fallbackExtract.position },
      investigateTarget: { ...fallbackExtract.position },
      investigateTimer: 2.1 + index * 0.18,
      awareness: "engaged",
      alert: true,
      navigationStallTime: 0,
      cooldown: Math.max(enemy.cooldown, index < 2 ? (mode === "clean" ? 0.74 : 0.55) : mode === "clean" ? 0.94 : 0.82),
      pressureType: index < 2 ? (mode === "clean" ? enemy.pressureType : "suppressed") : enemy.pressureType,
      pressureTimer: index < 2 ? (mode === "clean" ? 0.16 : 0.7) : enemy.pressureTimer,
      panicTimer: 0
    };
  });

  raidController.state.frontlineSupports.forEach((support, index) => {
    if (support.kind !== "fireteam") {
      return;
    }

    support.status = index === 0 ? "covering" : "holding";
    if (!support.playerEscort) {
      support.label =
        mode === "clean"
          ? index === 0
            ? "Spur screen"
            : "Dish cut"
          : index === 0
            ? "Lada screen"
            : "Moskvitch cut";
    }
    support.position = {
      x: fallbackExtract.position.x - fallbackExtract.radius * (0.86 + index * 0.12),
      y: fallbackExtract.position.y + (index % 2 === 0 ? 72 : -68)
    };
    support.anchor = { ...support.position };
    support.target = { ...fallbackExtract.position };
    support.contactTimer = Math.max(support.contactTimer, 0.88);
    support.pushTimer = Math.max(support.pushTimer, 0.72);
    support.note =
      mode === "clean"
        ? index === 0
          ? `${support.label} is already parked on the cleaner lip so the early peel reads disciplined instead of timid.`
          : `${support.label} is sitting deeper on the relay side so the alternative late route still looks worse than the current disciplined pull.`
        : index === 0
          ? `${support.label} is already parked on the left lip so the pull reads like a hasty civilian convoy peel, not a solo sprint.`
          : `${support.label} is cutting the back trail like a beat-up escort car while the ring stays contested.`;
  });

  const stagedRecoverySupport =
    raidController.state.frontlineSupports.find((support) => support.kind === "recovery") ??
    raidController.state.frontlineSupports.find((support) => support.kind === "convoy") ??
    null;
  if (stagedRecoverySupport) {
    stagedRecoverySupport.label =
      stagedRecoverySupport.kind === "recovery"
        ? mode === "clean"
          ? "Quiet bag pull"
          : "Ladder casualty pull"
        : mode === "clean"
          ? "Spur van"
          : "Signal van";
    stagedRecoverySupport.status = "holding";
    stagedRecoverySupport.position = {
      x: fallbackExtract.position.x - fallbackExtract.radius * 0.58,
      y: fallbackExtract.position.y + fallbackExtract.radius * 0.66
    };
    stagedRecoverySupport.anchor = { ...stagedRecoverySupport.position };
    stagedRecoverySupport.target = { ...fallbackExtract.position };
    stagedRecoverySupport.note =
      stagedRecoverySupport.kind === "recovery"
        ? mode === "clean"
          ? `${stagedRecoverySupport.label} is already feeding the chosen pull so the disciplined lane can end the run before recovery turns urgent.`
          : `${stagedRecoverySupport.label} is already feeding the chosen pull so haul and black bags peel on the same lane.`
        : mode === "clean"
          ? `${stagedRecoverySupport.label} is already bending onto ${fallbackExtract.label.toLowerCase()} so the board can show a calm peel lane against hotter alternatives.`
          : `${stagedRecoverySupport.label} is already bending onto ${fallbackExtract.label.toLowerCase()} with a live signal mast and dirt-road pickup space.`;
  }

  const stagedFallbackIncident =
    raidController.state.frontlineIncidents.find(
      (incident) =>
        !incident.resolved &&
        (incident.kind === "convoy" || incident.kind === "casualty") &&
        Phaser.Math.Distance.Between(
          incident.position.x,
          incident.position.y,
          fallbackExtract.position.x,
          fallbackExtract.position.y
        ) <= fallbackExtract.radius + 220
    ) ?? null;
  if (stagedFallbackIncident) {
    stagedFallbackIncident.label =
      stagedFallbackIncident.kind === "convoy"
        ? mode === "clean"
          ? "Spur fallback"
          : "Signal van"
        : mode === "clean"
          ? "Quiet peel truck"
          : "Logi truck peel";
    stagedFallbackIncident.status = mode === "clean" ? "secured" : "extracting";
    stagedFallbackIncident.note =
      stagedFallbackIncident.kind === "convoy"
        ? mode === "clean"
          ? `${stagedFallbackIncident.label} is already posted near ${fallbackExtract.label.toLowerCase()} so the comparison board can sell why that peel is still disciplined.`
          : `${stagedFallbackIncident.label} is already feeding fallback traffic toward ${fallbackExtract.label.toLowerCase()} before the hard beacon call lands.`
        : mode === "clean"
          ? `${stagedFallbackIncident.label} is already peeling tags and loose haul toward ${fallbackExtract.label.toLowerCase()} while the route is still under control.`
          : `${stagedFallbackIncident.label} is already peeling tags, ammo, and loose haul toward ${fallbackExtract.label.toLowerCase()}.`;
    stagedFallbackIncident.position = {
      x: fallbackExtract.position.x - fallbackExtract.radius * 0.92,
      y: fallbackExtract.position.y - fallbackExtract.radius * 0.34
    };
    stagedFallbackIncident.target = { ...fallbackExtract.position };
  }

  raidController.state.squadComms =
    mode === "clean"
      ? {
          speaker: "Yara",
          role: "Breacher",
          voiceTag: "Dry medic",
          tone: "extract",
          channel: "Clean Peel",
          line: "We have enough. Spur is still clean, screen is in place, and the long lane has not heard us yet."
        }
      : {
          speaker: "Yara",
          role: "Breacher",
          voiceTag: "Dry medic",
          tone: "extract",
          channel: "Extract Split",
          line: "Haul is worth it. Lada screen left, ladder pull low, signal van on the beacon."
        };
  raidController.state.squadLog =
    mode === "clean"
      ? [
          {
            id: 7001,
            speaker: "Yara",
            role: "Breacher",
            voiceTag: "Dry medic",
            tone: "extract",
            channel: "Clean Peel",
            line: "We have enough. Spur is still clean, screen is in place, and the long lane has not heard us yet.",
            stamp: "Net"
          },
          {
            id: 7002,
            speaker: "Rook",
            role: "Rifleman",
            voiceTag: "Steady hand",
            tone: "steady",
            channel: "Spur Hold",
            line: "Cut the disciplined lane now and the crash team never gets a real shot at us.",
            stamp: "Hold"
          }
        ]
      : [
          {
            id: 7001,
            speaker: "Yara",
            role: "Breacher",
            voiceTag: "Dry medic",
            tone: "extract",
            channel: "Extract Split",
            line: "Haul is worth it. Lada screen left, ladder pull low, signal van on the beacon.",
            stamp: "Net"
          },
          {
            id: 7002,
            speaker: "Rook",
            role: "Rifleman",
            voiceTag: "Steady hand",
            tone: "extract",
            channel: "Crash Building",
            line: "Moskvitch cut is set. Give me two seconds and we peel with the van.",
            stamp: "Hold"
          }
        ];
  raidController.state.squadMates = raidController.state.squadMates.map((mate, index) => ({
    ...mate,
    condition: mode === "clean" ? (index === 0 ? "heated" : "steady") : index === 0 ? "critical" : "heated",
    readiness: mode === "clean" ? (index === 0 ? 0.72 : index === 1 ? 0.81 : 0.78) : index === 0 ? 0.44 : index === 1 ? 0.58 : 0.63,
    assignment:
      mode === "clean"
        ? index === 0
          ? "Holding the cleaner spur"
          : index === 1
            ? "Watching the long relay lane"
            : "Packing the haul for a calm peel"
        : index === 0
          ? "Cutting into the extract ring"
          : index === 1
            ? "Bracing the reinforcement lane"
            : "Packing the haul for pullout"
  }));
  raidController.state.message =
    mode === "clean"
      ? "Clean extract staged: the route already paid, the far spur is still readable, and the comparison board should show why an early disciplined peel beats the hotter alternatives."
      : "Extract pressure staged: the pull now reads like a civilian-car peel with a ladder recovery lane and signal van support already bending onto exfil.";

  raidHudState.tacticalDrawerOpen = true;
  updateUi();
}

