function stageDebugTrenchAssaultShowcase(): void {
  if (raidController.state.phase === "stash") {
    raidController.setActiveRoute("crosswind-docks");
    raidController.setSelectedWeapon("rifle");
    raidController.setSelectedTacticalService("signal-jammer");
  }

  if (raidController.state.phase === "stash" && raidController.canStartRaid()) {
    raidController.startRaid(raidController.state.selectedWeapon);
  }

  if (raidController.state.phase !== "raid") {
    return;
  }

  const route = raidController.getActiveRoute();
  const trenchPocket = route.combatPockets[1] ?? route.combatPockets[0];
  const activeSector = raidController.state.frontlineSectors.find(
    (sector) => sector.routeId === raidController.state.activeRouteId
  );
  const firefightIncident =
    raidController.state.frontlineIncidents.find((incident) => incident.kind === "firefight" && !incident.resolved) ??
    raidController.state.frontlineIncidents[0] ??
    null;
  const escortSupport =
    raidController.state.frontlineSupports.find((support) => support.playerEscort && support.kind === "fireteam") ??
    raidController.state.frontlineSupports.find((support) => support.kind === "fireteam") ??
    null;
  const recoverySupport = raidController.state.frontlineSupports.find((support) => support.kind === "recovery") ?? null;

  if (!trenchPocket || !firefightIncident) {
    updateUi();
    return;
  }

  const pushOrigin = {
    x: trenchPocket.position.x - trenchPocket.radius * 1.22,
    y: trenchPocket.position.y + 18
  };
  const suppressTarget = {
    x: trenchPocket.position.x - 12,
    y: trenchPocket.position.y - 28
  };
  const fragTarget = {
    x: trenchPocket.position.x + 42,
    y: trenchPocket.position.y + 26
  };
  const recoveryAnchor = {
    x: pushOrigin.x - 112,
    y: pushOrigin.y + 56
  };

  if (activeSector) {
    activeSector.control = "contested";
    activeSector.pressure = 76;
    activeSector.scars = 61;
    activeSector.routeModifierTitle = "Pier trench bite";
    activeSector.routeModifierSummary =
      "The lower pier trench now reads as a real assault problem: one lip, one bend, and one short grenade window before Blue retakes the lane.";
    activeSector.activeEvent =
      "Crosswind's lower pier is pinned into a trench-lip fight where the boys need cover on the bend, a cooked frag over the wall, and a fast vault before the next pocket joins.";
    activeSector.watch = "Break the lip, hold the bend, then roll the squad into the trench before the pier wakes up again.";
  }

  raidController.state.player.position = { ...pushOrigin };
  raidController.state.player.facing = { x: 0.98, y: -0.08 };
  raidController.state.player.health = Math.min(raidController.state.player.maxHealth, 71);
  raidController.state.player.medkits = Math.max(raidController.state.player.medkits, 1);
  raidController.state.player.grenades = 1;
  raidController.state.player.reserveAmmo = Math.max(raidController.state.player.reserveAmmo, 72);
  raidController.state.player.frontlineMomentumLabel = "Trench shove";
  raidController.state.player.frontlineMomentumSummary = "PKM cover and one fast vault are live if the lip breaks now.";
  raidController.state.player.frontlineMomentumDuration = 11;
  raidController.state.player.frontlineMomentumTimer = 7.4;
  raidController.setAimTarget(suppressTarget);
  raidController.state.soundPressure = Math.max(raidController.state.soundPressure, 1.12);
  raidController.state.noiseResponseLevel = Math.max(raidController.state.noiseResponseLevel, 1);
  raidController.state.focusedFrontlineIncidentId = firefightIncident.id;
  syncStagedSquadCombatantsToAnchors();

  firefightIncident.label = "Pier trench lip";
  firefightIncident.status = "engaged";
  firefightIncident.position = {
    x: trenchPocket.position.x + 78,
    y: trenchPocket.position.y + 12
  };
  firefightIncident.anchor = { ...firefightIncident.position };
  firefightIncident.target = { ...pushOrigin };
  firefightIncident.opportunityLabel = "Suppress the lip and frag the bend";
  firefightIncident.note =
    "Blue is holding the lower pier trench behind one live lip and a short hooked bend, so the lane only opens if belt-fed cover and a cooked frag land inside the same shove.";
  firefightIncident.resolvedNote =
    "The lower pier lip is broken, the bend is yours, and Crosswind finally reads like a trench assault instead of another flat pocket exchange.";
  firefightIncident.strength = Math.max(firefightIncident.strength, 5);
  firefightIncident.grenadeStock = Math.max(firefightIncident.grenadeStock, 1);
  firefightIncident.grenadeCooldown = 0;
  firefightIncident.contactTimer = Math.max(firefightIncident.contactTimer, 1.2);
  firefightIncident.pushTimer = Math.max(firefightIncident.pushTimer, 0.85);

  raidController.state.enemies = raidController.state.enemies.slice(0, 4).map((enemy, index) => {
    const laneOffset = index * 34;
    const trenchY = trenchPocket.position.y + (index % 2 === 0 ? -18 : 26);
    return {
      ...enemy,
      position: {
        x: trenchPocket.position.x + 28 + laneOffset,
        y: trenchY
      },
      anchor: {
        x: trenchPocket.position.x + 42 + laneOffset,
        y: trenchY
      },
      target: { ...pushOrigin },
      facing: { x: -1, y: index % 2 === 0 ? 0.06 : -0.02 },
      alert: true,
      awareness: "engaged",
      investigateTarget: { ...pushOrigin },
      investigateTimer: 2.2 + index * 0.25,
      cooldown: Math.max(enemy.cooldown, 0.44),
      pressureTimer: 0,
      panicTimer: 0
    };
  });

  if (escortSupport) {
    escortSupport.weaponId = "pkm";
    escortSupport.position = {
      x: pushOrigin.x - 42,
      y: pushOrigin.y - 36
    };
    escortSupport.anchor = { ...escortSupport.position };
    escortSupport.target = { ...suppressTarget };
    escortSupport.facing = { x: 1, y: -0.04 };
    escortSupport.status = "covering";
    escortSupport.footholdLabel = "Pier lip support";
    escortSupport.footholdSummary =
      "The boys are belt-feeding the trench lip so the player can throw over the bend and actually own the crossing.";
    escortSupport.note =
      `${escortSupport.label} is stapled to the pier concrete with a PKM belt up, turning the first trench lip into a cover-buy instead of a flat DPS race.`;
    escortSupport.contactTimer = Math.max(escortSupport.contactTimer, 1.15);
    escortSupport.pushTimer = Math.max(escortSupport.pushTimer, 0.95);
    escortSupport.grenadeStock = Math.max(escortSupport.grenadeStock, 1);
    escortSupport.grenadeCooldown = 0;
  }

  if (recoverySupport) {
    recoverySupport.position = { ...recoveryAnchor };
    recoverySupport.anchor = { ...recoveryAnchor };
    recoverySupport.target = {
      x: trenchPocket.position.x - 54,
      y: trenchPocket.position.y + 48
    };
    recoverySupport.status = "holding";
    recoverySupport.note =
      `${recoverySupport.label} is tucked behind the pier cut with dressings and spare mags, ready to turn the trench into a casualty pull if the shove stalls.`;
    recoverySupport.contactTimer = Math.max(recoverySupport.contactTimer, 0.8);
  }

  raidController.state.squadMates = raidController.state.squadMates.map((squadMate, index) => {
    if (index === 0) {
      return {
        ...squadMate,
        weaponId: "pkm",
        assignment: "Pinning the pier lip so the player can vault into the bend before Blue resets.",
        assignmentTag: "BELT",
        condition: "steady"
      };
    }

    if (index === 1) {
      return {
        ...squadMate,
        weaponId: "shotgun",
        assignment: "Holding the first trench turn and flooding the bend once the frag lands.",
        assignmentTag: "BEND",
        condition: "steady"
      };
    }

    if (index === 2) {
      return {
        ...squadMate,
        weaponId: "smg",
        assignment: "Watching the rear ladder and refusing to let the pier pocket wrap the trench shove.",
        assignmentTag: "REAR",
        condition: "steady"
      };
    }

    return squadMate;
  });

  raidController.selectSquadMateByIndex(0);
  raidController.queueSelectedSquadTacticalAction("suppress", suppressTarget, { source: "ctrl-click" });
  raidController.selectSquadMateByIndex(1);
  raidController.queueSelectedSquadTacticalAction("grenade", fragTarget, { source: "agent" });
  raidController.queueFrontlineSupportOrder("shift-fire");

  raidController.state.frontlineTracers = [
    {
      id: 9971,
      position: { x: trenchPocket.position.x - 26, y: trenchPocket.position.y + 4 },
      origin: { x: pushOrigin.x + 16, y: pushOrigin.y - 4 },
      velocity: { x: 1280, y: -72 },
      life: 0.11,
      maxLife: 0.23,
      radius: 4,
      color: 0xf8fafc,
      faction: "friendly",
      weaponId: raidController.state.player.weaponId
    },
    {
      id: 9972,
      position: { x: trenchPocket.position.x - 12, y: trenchPocket.position.y - 22 },
      origin: { x: pushOrigin.x - 32, y: pushOrigin.y - 28 },
      velocity: { x: 1560, y: -88 },
      life: 0.12,
      maxLife: 0.24,
      radius: 5,
      color: 0x38bdf8,
      faction: "friendly",
      weaponId: "pkm"
    },
    {
      id: 9973,
      position: { x: trenchPocket.position.x + 34, y: trenchPocket.position.y + 18 },
      origin: { x: firefightIncident.position.x + 84, y: firefightIncident.position.y - 18 },
      velocity: { x: -1180, y: 46 },
      life: 0.1,
      maxLife: 0.22,
      radius: 4,
      color: 0xfca5a5,
      faction: "hostile",
      weaponId: "rifle"
    }
  ];
  raidController.state.frontlineImpacts = [
    {
      id: 9974,
      position: { x: trenchPocket.position.x + 18, y: trenchPocket.position.y - 24 },
      angle: -0.16,
      life: 0.12,
      maxLife: 0.26,
      radius: 20,
      color: 0x38bdf8,
      kind: "suppression",
      faction: "friendly",
      material: "concrete",
      weaponId: "pkm"
    },
    {
      id: 9975,
      position: { x: trenchPocket.position.x + 48, y: trenchPocket.position.y + 22 },
      angle: 0.44,
      life: 0.08,
      maxLife: 0.22,
      radius: 15,
      color: 0xf8fafc,
      kind: "impact",
      faction: "friendly",
      material: "default",
      weaponId: raidController.state.player.weaponId
    }
  ];
  raidController.state.grenades = [
    {
      id: 9976,
      source: "support",
      faction: "friendly",
      ownerLabel: "Bend frag",
      position: {
        x: pushOrigin.x + (fragTarget.x - pushOrigin.x) * 0.78,
        y: pushOrigin.y + (fragTarget.y - pushOrigin.y) * 0.78
      },
      origin: { ...pushOrigin },
      target: { ...fragTarget },
      elapsed: 0.46,
      fuseTime: 0.88,
      travelTime: 0.3,
      radius: 112,
      damage: 58
    }
  ];

  raidController.state.message =
    "Trench assault staged: Crosswind's pier trench is now a real authored shove with PKM cover on the lip, a frag into the bend, and squad roles that read like an actual lower-pier assault.";
  raidHudState.tacticalDrawerOpen = false;
  updateUi();
}

function syncStagedSquadCombatantsToAnchors(): void {
  if (raidController.state.phase !== "raid") {
    return;
  }

  for (const combatant of raidController.state.friendlyCombatants) {
    if (combatant.ownerKind !== "squadmate") {
      continue;
    }

    const deltaX = combatant.position.x - combatant.anchor.x;
    const deltaY = combatant.position.y - combatant.anchor.y;
    if (Math.hypot(deltaX, deltaY) <= 240) {
      continue;
    }

    combatant.position = { ...combatant.anchor };
    combatant.velocity = { x: 0, y: 0 };
    combatant.target = { ...combatant.anchor };
    combatant.lastNavigationSample = { ...combatant.anchor };
    combatant.navigationCommittedTarget = null;
    combatant.investigateTarget = null;
    combatant.investigateTimer = 0;
  }
}

