function setPrepLoadoutAbsolute(resource: PrepResource, targetValue: number): void {
  if (raidController.state.phase !== "stash") {
    return;
  }

  const available = raidController.state.stashSupplies[resource];
  const clampedTarget = Math.max(0, Math.min(targetValue, available));
  const delta = clampedTarget - raidController.state.prepLoadout[resource];

  if (delta !== 0) {
    raidController.adjustPrepLoadout(resource, delta);
  }
}

function getFocusedExtractLabel(): string | null {
  const route = raidController.getActiveRoute();
  const activeExtract = raidController.state.activeExtractId
    ? raidController.state.extractZones.find((extract) => extract.id === raidController.state.activeExtractId) ?? null
    : null;

  if (activeExtract) {
    return activeExtract.label;
  }

  if (raidController.state.extractZones.length > 0) {
    return raidController.state.extractZones[0].label;
  }

  return route.extractLabel;
}

